pub struct Game {
    pub sim: Sim,
    pub meta: Meta,
    pub frames: Vec<Vec<Value>>,
    pub player: Side,
    /// Стороны под внешним управлением (игрок и, если есть, штаб противника на языковой модели вне ядра): их
    /// исторические приказы сняты, приказы им отдаёт `order`.
    pub free: Vec<Side>,
    /// Час, с которого командует игрок.
    pub takeover: u32,
    /// До какого часа можно вести игру (по умолчанию — конец сценария; игра может идти и дольше, до своего срока).
    pub limit: u32,
    /// Резервы стороны игрока, ждущие ввода: индекс дивизии → с какого часа готов (ввод по сценарию).
    pub reserves: BTreeMap<u32, u32>,
}

/// Ход: `hours` шагов (не дальше `limit`).
pub fn advance(&mut self, hours: u32) {
    let left = self.limit.saturating_sub(self.hour());
    for _ in 0..hours.min(left) { self.sim.step(); self.frames.push(trace::frame(&self.sim)); }
}

/// Дивизии штаба (и подчинённых ему штабов), ещё участвующие в операции.
pub fn divisions_of(&self, hq: u32) -> Vec<u32> {
    let w = &self.sim.world;
    let under = |mut h: u32| -> bool {
        for _ in 0..8 {
            if h == hq { return true; }
            match w.hqs[h as usize].parent { Some(p) => h = p, None => return false }
        }
        false
    };
    w.divisions.iter().enumerate()
        .filter(|(_, d)| under(d.hq) && !matches!(d.state, crate::model::State::Destroyed | crate::model::State::Merged))
        .map(|(i, _)| i as u32).collect()
}

/// Приказ игрока: доходит до дивизий штаба на ближайшем шаге (с задержкой уровня штаба). Возвращает число дивизий.
pub fn order(&mut self, o: &PlayerOrder) -> Result<usize, String> {
    let w = &self.sim.world;
    let (hq, to) = if let Some(h) = w.hqs.iter().position(|h| h.id == o.hq) {
        (h as u32, self.divisions_of(h as u32))
    } else if let Some(d) = w.divisions.iter().position(|d| d.id == o.hq) {
        if matches!(w.divisions[d].state, crate::model::State::Destroyed | crate::model::State::Merged) { return Err(format!("{} выбыла", w.divisions[d].name)); }
        (w.divisions[d].hq, vec![d as u32])
    } else {
        return Err(format!("нет штаба или дивизии {}", o.hq));
    };
    if !self.free.contains(&self.sim.world.hqs[hq as usize].side) { return Err(format!("{} — не под нашим управлением", o.hq)); }
    if to.is_empty() { return Err(format!("у штаба {} нет действующих дивизий", o.hq)); }
    let n = to.len();
    let target = o.target.map(|p| self.sim.theatre.proj.to_xy(p));
    let tick = self.hour();
    // в начало очереди: в очереди только приказы с часом не раньше текущего
    self.sim.script.insert(0, ScriptOrder {
        at: tick, hq, to, kind: o.kind, target, forced: false,
        note: if o.note.is_empty() { "приказ игрока".into() } else { o.note.clone() },
        follow: None, offset: Default::default(),
    });
    Ok(n)
}

/// Распоряжения штаба на ход; возвращает неисполненные с причиной.
pub fn staff(&mut self, s: &StaffIn) -> Vec<String> {
    let mut bad = Vec::new();
    let ix: std::collections::HashMap<String, u32> = self.sim.world.divisions.iter().enumerate().map(|(i, d)| (d.id.clone(), i as u32)).collect();
    self.sim.staff.supply = s.supply.iter().filter_map(|(id, k)| ix.get(id).map(|&i| (i, k.max(0.0)))).collect();
    let theatre = self.sim.theatre.clone();
    let proj = &theatre.proj;
    for b in &s.bridges { self.sim.staff.pontoons.push((proj.to_xy(b.at), self.player, b.from)); }
    for b in &s.demolish {
        match theatre.bridges.iter().position(|x| x.id == b.bridge) {
            Some(k) => { self.sim.staff.demolished.insert(k as u16, b.from); }
            None => bad.push(format!("подрыв: моста {} в театре нет", b.bridge)),
        }
    }
    for c in &s.commit {
        let Some(&i) = ix.get(&c.division) else { bad.push(format!("резерв {}: нет такой дивизии", c.division)); continue };
        if self.reserves.remove(&i).is_none() { bad.push(format!("резерв {}: не ждёт ввода", c.division)); continue; }
        let d = &mut self.sim.world.divisions[i as usize];
        d.enter = c.from.max(self.sim.world.tick);
        d.vars.pos = proj.to_xy(c.at);
    }
    self.sim.staff.sectors = s.sectors.iter().map(|x| Sectors {
        step: x.step.max(1), cols: x.cols, foreign: x.foreign,
        label: match &x.codes { Some(c) => c.bytes().map(|b| if b == b'.' { -1 } else { b as i16 - b'0' as i16 }).collect(), None => x.label.clone() },
        group: x.groups.iter().filter_map(|(id, g)| ix.get(id).map(|&i| (i, *g))).collect(),
    }).collect();
    bad
}

/// То же, со сторонами под внешним управлением `free` (игрок и штаб противника на модели вне ядра) и состоянием
/// дивизий на час передачи `takeover_state` (заменяет рассчитанное; в последнем кадре до передачи — уже оно).
pub fn start_free(mut sim: Sim, meta: Meta, takeover: u32, player: Side, free: &[Side], takeover_state: Option<&TakeoverIn>) -> Game {
    let takeover = takeover.min(meta.hours);
    let mut frames = vec![trace::frame(&sim)];
    for _ in 0..takeover { sim.step(); frames.push(trace::frame(&sim)); }
    if let Some(st) = takeover_state {
        let w = &mut sim.world;
        let proj = &sim.theatre.proj;
        for d in w.divisions.iter_mut() {
            let Some(s) = st.divisions.get(&d.id) else { continue };
            // выбывшая (рассеяна, сведена) — факт о численности её не возвращает
            if matches!(d.state, crate::model::State::Destroyed | crate::model::State::Merged) { continue; }
            if let Some(p) = s.personnel { d.vars.personnel = p.max(0.0); }
            if let Some(t) = s.tanks { d.vars.tanks = t.max(0.0); }
            if let Some(g) = s.guns { d.vars.guns = g.max(0.0); }
            if let Some(p) = s.pos { d.vars.pos = proj.to_xy(p); d.route = None; }
            if let Some(h) = s.hq.as_deref().and_then(|h| w.hqs.iter().position(|x| x.id == h && x.side == d.side)) { d.hq = h as u32; }
        }
        if let Some(f) = frames.last_mut() { *f = trace::frame(&sim); }
    }
    let mine = |hq: u32, sim: &Sim| free.contains(&sim.world.hqs[hq as usize].side);
    let keep: Vec<bool> = sim.script.iter().map(|o| !mine(o.hq, &sim)).collect();
    let mut k = keep.iter();
    sim.script.retain(|_| *k.next().unwrap());
    let keep: Vec<bool> = sim.fires.iter().map(|f| !mine(f.hq, &sim)).collect();
    let mut k = keep.iter();
    sim.fires.retain(|_| *k.next().unwrap());
    // штабы сторон под внешним управлением сами больше не решают
    for &sd in free { sim.sources[crate::staff::side_idx(sd)] = crate::staff::Source::Script; }
    // резервы стороны игрока: ввод больше не по графику сценария — по его решению (commit)
    let mut reserves = BTreeMap::new();
    for (i, d) in sim.world.divisions.iter_mut().enumerate() {
        if d.side == player && d.state == crate::model::State::Pending && d.enter > takeover {
            reserves.insert(i as u32, d.enter);
            d.enter = u32::MAX;
        }
    }
    let limit = meta.hours;
    Game { sim, meta, frames, player, free: free.to_vec(), takeover, limit, reserves }
}

/// Ход игры в формате trace.json (кадры с начала сценария) и сведения об игре.
pub fn trace(&self) -> Value {
    let mut v = trace::describe(&self.sim, &self.meta, self.frames.clone());
    // территория сторон по клеткам театра (0 — ничья, 1 — советская, 2 — немецкая): для путей подвоза от баз
    v["control"] = serde_json::json!(self.sim.world.control.iter().map(|&c| (b'0' + c.min(9)) as char).collect::<String>());
    v["game"] = serde_json::json!({
        "player": self.player, "free": self.free,
        "reserves": self.reserves.iter().map(|(&i, &h)| serde_json::json!({ "id": self.sim.world.divisions[i as usize].id, "from": h })).collect::<Vec<_>>(),
        "takeover": self.takeover, "hour": self.hour(), "over": self.over(),
    });
    v
}

/// Приказ штабу (всем его дивизиям) или одной дивизии.
pub struct PlayerOrder {
    /// Штаб (фронт, армия, корпус) или дивизия.
    pub hq: String,
    pub kind: OrderKind,
    /// Цель; нет — на месте (у каждой дивизии своё).
    #[serde(default)]
    pub target: Option<LngLat>,
    #[serde(default)]
    pub note: String,
}

/// Полосы объединений (как sectorMap этой модели): сетка меток и объединение каждой дивизии.
pub struct SectorsIn {
    pub step: usize,
    pub cols: usize,
    #[serde(default)]
    pub label: Vec<i16>,
    /// Метки строкой, по знаку на клетку ('0' + метка, '.' — вне полос) — компактнее label.
    #[serde(default)]
    pub codes: Option<String>,
    pub groups: Vec<(String, i16)>,
    pub foreign: f64,
}

/// Распоряжения штаба на ход.
pub struct StaffIn {
    /// Множитель подвоза по дивизиям (на ход; весь набор заменяет прежний).
    #[serde(default)]
    pub supply: Vec<(String, f64)>,
    #[serde(default)]
    pub bridges: Vec<AtHour>,
    /// Подрыв мостов театра (по id моста) с часа; с часа 0 — мост снят (наводки стороны игрока после передачи командования).
    #[serde(default)]
    pub demolish: Vec<Demolish>,
    #[serde(default)]
    pub commit: Vec<Commit>,
    /// Полосы по уровням (фронты, армии); пусто — без полос.
    #[serde(default)]
    pub sectors: Vec<SectorsIn>,
}

/// Состояние дивизий на час передачи командования (из базы знаний): заменяет рассчитанное к этому часу.
pub struct TakeoverIn {
    /// id дивизии → состояние; неизвестные id не учитываются.
    #[serde(default)]
    pub divisions: std::collections::HashMap<String, TakeoverDiv>,
}

pub struct Proj {
    pub lng0: f64,
    pub lat0: f64,
}

pub fn to_lnglat(&self, q: XY) -> LngLat {
    let lat = q.y / KM_LAT + self.lat0;
    [q.x / (KM_LNG_EQ * lat.to_radians().cos()) + self.lng0, lat]
}

pub fn to_xy(&self, p: LngLat) -> XY {
    XY::new((p[0] - self.lng0) * KM_LNG_EQ * p[1].to_radians().cos(), (p[1] - self.lat0) * KM_LAT)
}

pub struct XY {
    pub x: f64,
    pub y: f64,
}

pub fn toward(self, o: XY, km: f64) -> XY {
    let d = self.dist(o);
    if d <= km || d == 0.0 { return o; }
    XY::new(self.x + (o.x - self.x) * km / d, self.y + (o.y - self.y) * km / d)
}

/// Пересекаются ли отрезки ab и cd (касание считается пересечением).
pub fn segments_cross(a: XY, b: XY, c: XY, d: XY) -> bool {
    fn orient(p: XY, q: XY, r: XY) -> f64 { (q.x - p.x) * (r.y - p.y) - (q.y - p.y) * (r.x - p.x) }
    let (d1, d2) = (orient(c, d, a), orient(c, d, b));
    let (d3, d4) = (orient(a, b, c), orient(a, b, d));
    (d1 * d2 <= 0.0) && (d3 * d4 <= 0.0) && !(d1 == 0.0 && d2 == 0.0 && d3 == 0.0 && d4 == 0.0)
}

/// Корень репозитория: от папки крейта на два уровня вверх.
pub fn repo_root() -> String {
    let here = env!("CARGO_MANIFEST_DIR");
    std::path::Path::new(here).join("../..").canonicalize().map(|p| p.to_string_lossy().into_owned()).unwrap_or_else(|_| ".".into())
}

pub struct LlmConfig {
    /// Адрес сервера с /v1, например http://localhost:1234/v1.
    pub url: String,
    /// Модель (id из /v1/models).
    pub model: String,
    /// Сколько ждать очередной части ответа (поток) или всего ответа (без потока), с.
    pub timeout_s: u64,
    pub temperature: f64,
    pub reasoning: Reasoning,
    /// Потолок токенов ответа (вместе с размышлениями); 0 — без ограничения.
    pub max_tokens: u32,
    /// Одновременных запросов к серверу; 0 — определить замером (probe_parallel).
    pub parallel: usize,
    /// Штабы на модели решают в один час (иначе — вразнобой по часам, как штабы по доктрине): запросы одного часа
    /// уходят параллельно.
    pub sync: bool,
    /// Один запрос на армию: штаб армии решает за свои корпуса (быстрее, но корпус — уже не отдельный агент).
    pub by_army: bool,
}

pub fn describe(&self) -> Value {
    json!({ "url": self.url, "model": self.model, "reasoning": self.reasoning.id(), "maxTokens": self.max_tokens, "parallel": self.parallel, "sync": self.sync, "byArmy": self.by_army })
}

pub fn new(url: &str, model: &str) -> Self {
    LlmConfig {
        url: url.trim_end_matches('/').to_string(), model: model.to_string(), timeout_s: 300, temperature: 0.2,
        reasoning: Reasoning::Default, max_tokens: 0, parallel: 1, sync: false, by_army: false,
    }
}

/// Замер: сколько запросов сервер с этой моделью обслуживает одновременно с выгодой.
pub struct Probe {
    pub best: usize,
    /// (одновременных запросов, токенов в секунду всего, секунд на ступень).
    pub rows: Vec<(usize, f64, f64)>,
}

pub fn to_json(&self) -> Value {
    json!({ "best": self.best, "rows": self.rows.iter().map(|r| json!({ "parallel": r.0, "tokensPerSec": (r.1 * 10.0).round() / 10.0, "secs": (r.2 * 10.0).round() / 10.0 })).collect::<Vec<_>>() })
}

/// Уровень размышлений модели. Серверы понимают его по-разному, поэтому отправляется всё, что распространено:
/// `reasoning_effort` (OpenAI, LM Studio, Ollama), а для «выкл» ещё `chat_template_kwargs.enable_thinking = false`
/// (vLLM, llama.cpp), `think = false` (Ollama) и метка `/no_think` (Qwen3). Незнакомые поля серверы пропускают;
/// если сервер отверг запрос, он повторяется без этих полей.
pub enum Reasoning { Default, Off, Low, Medium, High }

pub fn id(self) -> &'static str {
    match self { Self::Default => "default", Self::Off => "off", Self::Low => "low", Self::Medium => "medium", Self::High => "high" }
}

pub fn parse(s: &str) -> Option<Self> {
    Some(match s { "default" | "" => Self::Default, "off" => Self::Off, "low" => Self::Low, "medium" => Self::Medium, "high" => Self::High, _ => return None })
}

/// Ответ модели.
pub struct Reply {
    /// Ответ без размышлений.
    pub text: String,
    /// Размышления модели (поле reasoning_content / reasoning или <think>…</think> в тексте).
    pub reasoning: String,
    /// Ответ оборван потолком токенов (finish_reason = length).
    pub truncated: bool,
    /// Токенов ответа (по usage сервера, вместе с размышлениями), если сервер их сообщил.
    pub tokens: Option<u64>,
    pub secs: f64,
}

pub fn finish(&mut self, out: &mut Vec<(Part, String)>) {
    if !self.pending.is_empty() { out.push((if self.inside { Part::Think } else { Part::Text }, std::mem::take(&mut self.pending))); }
}

pub fn push(&mut self, s: &str, out: &mut Vec<(Part, String)>) {
    self.pending.push_str(s);
    loop {
        let tag = if self.inside { "</think>" } else { "<think>" };
        let part = if self.inside { Part::Think } else { Part::Text };
        if let Some(k) = self.pending.find(tag) {
            if k > 0 { out.push((part, self.pending[..k].to_string())); }
            self.pending = self.pending[k + tag.len()..].to_string();
            self.inside = !self.inside;
            continue;
        }
        // хвост, который может оказаться началом метки, ждёт следующей части (метка — латиница, граница символа цела)
        let keep = (1..tag.len()).rev().find(|&n| self.pending.ends_with(&tag[..n])).unwrap_or(0);
        let cut = self.pending.len() - keep;
        if cut > 0 { out.push((part, self.pending[..cut].to_string())); self.pending = self.pending[cut..].to_string(); }
        break;
    }
}

fn agent(timeout_s: u64) -> ureq::Agent {
    ureq::AgentBuilder::new().timeout(Duration::from_secs(timeout_s)).build()
}

fn body(cfg: &LlmConfig, messages: &[(String, String)], extras: bool) -> Value {
    let mut msgs: Vec<Value> = messages.iter().map(|(r, c)| json!({ "role": r, "content": c })).collect();
    let mut b = json!({ "model": cfg.model, "temperature": cfg.temperature, "stream": true });
    if cfg.max_tokens > 0 { b["max_tokens"] = json!(cfg.max_tokens); }
    if extras {
        b["stream_options"] = json!({ "include_usage": true });
        match cfg.reasoning {
            Reasoning::Default => {}
            Reasoning::Off => {
                b["reasoning_effort"] = json!("low");
                b["chat_template_kwargs"] = json!({ "enable_thinking": false });
                b["think"] = json!(false);
                if let Some(last) = msgs.iter_mut().rev().find(|m| m["role"] == "user") {
                    last["content"] = json!(format!("{} /no_think", last["content"].as_str().unwrap_or("")));
                }
            }
            r => b["reasoning_effort"] = json!(r.id()),
        }
    }
    b["messages"] = json!(msgs);
    b
}

/// Запрос к чату: сообщения (роль, текст) → текст ответа.
pub fn chat(cfg: &LlmConfig, messages: &[(String, String)]) -> Result<String, String> {
    complete(cfg, messages).map(|r| r.text)
}

/// Запрос к чату с уровнем размышлений и потолком токенов из настроек.
pub fn complete(cfg: &LlmConfig, messages: &[(String, String)]) -> Result<Reply, String> {
    complete_stream(cfg, messages, &mut |_, _| {}, None)
}

/// Запрос к чату потоком: `on` получает размышления и ответ по мере прихода; `cancel` — остановка. Если сервер
/// ответил не потоком, а целиком, ответ разбирается так же. Ожидание каждой части — не дольше `timeout_s`.
pub fn complete_stream(cfg: &LlmConfig, messages: &[(String, String)], on: &mut dyn FnMut(Part, &str), cancel: Option<&AtomicBool>) -> Result<Reply, String> {
    let u = format!("{}/chat/completions", cfg.url);
    let t0 = Instant::now();
    let ag = ureq::AgentBuilder::new().timeout_connect(Duration::from_secs(15)).timeout_read(Duration::from_secs(cfg.timeout_s)).build();
    let send = |extras: bool| ag.post(&u).send_json(body(cfg, messages, extras));
    let resp = match send(true) {
        // сервер отверг незнакомые поля (размышления, учёт токенов в потоке) — без них
        Err(ureq::Error::Status(400 | 422, _)) => send(false),
        r => r,
    };
    let resp = resp.map_err(|e| format!("{u}: {e}"))?;
    let (mut text, mut reasoning) = (String::new(), String::new());
    let mut split = ThinkSplit::default();
    let mut parts: Vec<(Part, String)> = Vec::new();
    let mut emit = |parts: &mut Vec<(Part, String)>, text: &mut String, reasoning: &mut String| {
        for (p, s) in parts.drain(..) {
            match p { Part::Think => reasoning.push_str(&s), Part::Text => text.push_str(&s) }
            on(p, &s);
        }
    };
    let mut truncated = false;
    let mut tokens: Option<u64> = None;
    let mut chunks = 0u64;
    if resp.content_type() == "text/event-stream" {
        let rd = std::io::BufReader::new(resp.into_reader());
        for line in rd.lines() {
            if cancel.is_some_and(|c| c.load(Ordering::Relaxed)) { return Err("остановлено".into()); }
            let line = line.map_err(|e| format!("{u}: {e}"))?;
            let Some(data) = line.strip_prefix("data:").map(str::trim) else { continue };
            if data == "[DONE]" { break; }
            let Ok(v) = serde_json::from_str::<Value>(data) else { continue };
            if let Some(t) = v.pointer("/usage/completion_tokens").and_then(Value::as_u64) { tokens = Some(t); }
            let Some(c) = v.pointer("/choices/0") else { continue };
            if c.get("finish_reason").and_then(Value::as_str) == Some("length") { truncated = true; }
            let d = &c["delta"];
            for key in ["reasoning_content", "reasoning"] {
                if let Some(r) = d.get(key).and_then(Value::as_str).filter(|r| !r.is_empty()) { parts.push((Part::Think, r.to_string())); chunks += 1; }
            }
            if let Some(t) = d.get("content").and_then(Value::as_str).filter(|t| !t.is_empty()) { split.push(t, &mut parts); chunks += 1; }
            emit(&mut parts, &mut text, &mut reasoning);
        }
    } else {
        let v: Value = resp.into_json().map_err(|e| format!("{u}: {e}"))?;
        let c = &v["choices"][0];
        truncated = c.get("finish_reason").and_then(Value::as_str) == Some("length");
        tokens = v.pointer("/usage/completion_tokens").and_then(Value::as_u64);
        for key in ["reasoning_content", "reasoning"] {
            if let Some(r) = c["message"].get(key).and_then(Value::as_str).filter(|r| !r.is_empty()) { parts.push((Part::Think, r.to_string())); }
        }
        split.push(c["message"]["content"].as_str().unwrap_or(""), &mut parts);
    }
    split.finish(&mut parts);
    emit(&mut parts, &mut text, &mut reasoning);
    // шаблон уже открыл <think> в запросе: в ответе только закрывающая метка — всё до неё размышления
    if let Some(k) = text.find("</think>") { reasoning.push_str(&text[..k]); text = text[k + 8..].to_string(); }
    if text.trim().is_empty() && reasoning.is_empty() && !truncated { return Err("в ответе модели нет текста".into()); }
    Ok(Reply { text: text.trim().to_string(), reasoning, truncated, tokens: tokens.or((chunks > 0).then_some(chunks)), secs: t0.elapsed().as_secs_f64() })
}

/// JSON из ответа модели: без рассуждений <think>…</think> и обрамления ```json, от первой «{» до последней «}».
pub fn extract_json(s: &str) -> Option<Value> {
    let s = match (s.find("<think>"), s.rfind("</think>")) { (Some(_), Some(b)) => &s[b + 8..], _ => s };
    let (a, b) = (s.find('{')?, s.rfind('}')?);
    if b <= a { return None; }
    serde_json::from_str(&s[a..=b]).ok()
}

/// Модели сервера: id из /v1/models.
pub fn list_models(url: &str) -> Result<Vec<String>, String> {
    let u = format!("{}/models", url.trim_end_matches('/'));
    let v: Value = agent(15).get(&u).call().map_err(|e| format!("{u}: {e}"))?.into_json().map_err(|e| format!("{u}: {e}"))?;
    let mut ids: Vec<String> = v.get("data").and_then(Value::as_array).map(|a| a.iter().filter_map(|m| m.get("id").and_then(Value::as_str).map(String::from)).collect()).unwrap_or_default();
    ids.sort();
    Ok(ids)
}

/// Определение числа параллельных запросов замером: короткие одинаковые ответы на 1, 2, 4, 8… одновременных
/// запросах; суммарная скорость (токенов в секунду) растёт, пока сервер и чип справляются. Берётся ступень, после
/// которой прибавка меньше 20 %, или последняя без ошибок. Сначала — один запрос на разогрев (загрузка модели).
pub fn probe_parallel(cfg: &LlmConfig, max: usize) -> Result<Probe, String> {
    let mut c = cfg.clone();
    c.reasoning = Reasoning::Off;
    c.max_tokens = 96;
    c.temperature = 0.0;
    let msgs = vec![("user".to_string(), "Перечисли через запятую словами числа от одного до шестидесяти, без пояснений.".to_string())];
    complete(&c, &msgs)?;
    let mut rows: Vec<(usize, f64, f64)> = Vec::new();
    let mut n = 1;
    while n <= max.max(1) {
        let t0 = Instant::now();
        let res: Vec<Result<Reply, String>> = std::thread::scope(|s| {
            let hs: Vec<_> = (0..n).map(|_| s.spawn(|| complete(&c, &msgs))).collect();
            hs.into_iter().map(|h| h.join().unwrap_or_else(|_| Err("поток упал".into()))).collect()
        });
        let secs = t0.elapsed().as_secs_f64();
        if res.iter().any(|r| r.is_err()) { break; }
        let toks: f64 = res.iter().flatten().map(|r| r.tokens.map(|t| t as f64).unwrap_or(r.text.chars().count() as f64 / 3.0)).sum();
        let tps = toks / secs.max(1e-6);
        let gain = rows.last().map(|r| tps / r.1.max(1e-9));
        rows.push((n, tps, secs));
        if matches!(gain, Some(g) if g < 1.2) { break; }
        n *= 2;
    }
    if rows.is_empty() { return Err("сервер не ответил на замер".into()); }
    // лучшая ступень — последняя, давшая прибавку не меньше 20 % к предыдущей
    let mut best = rows[0].0;
    for w in rows.windows(2) { if w[1].1 >= w[0].1 * 1.2 { best = w[1].0; } else { break; } }
    Ok(Probe { best, rows })
}

