        "start": "1945-04-16T05:00", "hours": 24, "seed": 1,
        "hqs": [
            { "id": "su_f", "name": "фронт", "side": "su", "echelon": "front", "parent": null, "pos": [15.2, 52.5] },
            { "id": "su_a", "name": "армия А", "side": "su", "echelon": "army", "parent": "su_f", "pos": [15.1, 52.5] },
            { "id": "su_b", "name": "армия Б", "side": "su", "echelon": "army", "parent": "su_f", "pos": [15.1, 52.6] },
            { "id": "de_a", "name": "немецкая армия", "side": "de", "echelon": "army", "parent": null, "pos": [13.4, 52.5] }
        ],
        "divisions": [
            { "id": "su_1", "name": "1 сд", "side": "su", "hq": "su_a", "kind": "sd", "mobility": "foot", "size": "rifle", "personnel": 5000, "tanks": 0, "guns": 100, "pos": [15.1, 52.5] },
            { "id": "su_2", "name": "2 сд", "side": "su", "hq": "su_b", "kind": "sd", "mobility": "foot", "size": "rifle", "personnel": 6000, "tanks": 0, "guns": 120, "pos": [15.1, 52.6], "enterAt": "1945-04-16T10:00" },
            { "id": "de_1", "name": "1 пд", "side": "de", "hq": "de_a", "kind": "pd", "mobility": "foot", "size": "rifle", "personnel": 7000, "tanks": 10, "guns": 60, "pos": [13.4, 52.5] }
        ]
    });
    let path = std::env::temp_dir().join(format!("agents-core-{name}-{}.json", std::process::id()));
    std::fs::write(&path, s.to_string()).unwrap();
    load_with(&path.to_string_lossy(), &format!("{root}/{DATA_DIR}"), &root, None, edits).expect("сценарий")
}

pub struct Index {
    cell: f64,
    buckets: HashMap<(i32, i32), Vec<u32>>,
}

pub fn build(points: impl Iterator<Item = (u32, XY)>, cell: f64) -> Index {
    let mut buckets: HashMap<(i32, i32), Vec<u32>> = HashMap::new();
    for (i, p) in points { buckets.entry(Self::key(p, cell)).or_default().push(i); }
    Index { cell, buckets }
}

/// Все индексы в радиусе `r` от `p` (кандидаты; расстояние проверяет вызывающий), по возрастанию индекса.
pub fn near(&self, p: XY, r: f64) -> Vec<u32> {
    let (k0, k1) = (Self::key(XY::new(p.x - r, p.y - r), self.cell), Self::key(XY::new(p.x + r, p.y + r), self.cell));
    let mut out = Vec::new();
    for kx in k0.0..=k1.0 {
        for ky in k0.1..=k1.1 {
            if let Some(v) = self.buckets.get(&(kx, ky)) { out.extend_from_slice(v); }
        }
    }
    out.sort_unstable();
    out
}

/// Оценка дивизии штабом.
struct Assess {
    i: usize,
    strength: f64,
    /// Сила противника в досягаемости, к своей силе.
    threat: f64,
    broken: bool,
}

/// Решение штаба: приказы и пояснения к ним.
pub(crate) struct Decision {
    pub(crate) orders: Vec<ScriptOrder>,
    pub(crate) why: Vec<String>,
}

/// Запрос к модели штаба: поток в окно приложения, запись в журнал запросов; возвращает список orders ответа.
pub(crate) fn ask_staff(&self, tick: u32, hq: &Hq, system: String, user: String, cfg: &llm::LlmConfig) -> Result<Vec<Value>, String> {
    let time = crate::time::format_hours(self.start_hour + tick as i64);
    if let Some(cb) = &self.on_progress { cb(format!("{time}: штаб «{}» запрашивает модель {}…", hq.name, cfg.model)); }
    // поток ответа — в окно приложения: хвосты размышлений и ответа, не чаще раза в 0,15 с
    let t0 = std::time::Instant::now();
    let (mut think, mut text, mut last, mut n) = (String::new(), String::new(), 0.0f64, 0u64);
    let tail = |s: &str, k: usize| { let c = s.chars().count(); s.chars().skip(c.saturating_sub(k)).collect::<String>() };
    let send = |phase: &str, think: &str, text: &str, n: u64| if let Some(cb) = &self.on_stream {
        cb(json!({ "hq": hq.id, "name": hq.name, "time": time, "phase": phase, "think": tail(think, 700), "text": tail(text, 400), "parts": n, "secs": (t0.elapsed().as_secs_f64() * 10.0).round() / 10.0 }));
    };
    send("wait", "", "", 0);
    let reply = llm::complete_stream(cfg, &[("system".into(), system), ("user".into(), user.clone())], &mut |p, s| {
        match p { llm::Part::Think => think.push_str(s), llm::Part::Text => text.push_str(s) }
        n += 1;
        let now = t0.elapsed().as_secs_f64();
        if now - last >= 0.15 { last = now; send(if text.trim().is_empty() { "think" } else { "answer" }, &think, &text, n); }
    }, None);
    send(if reply.is_ok() { "done" } else { "error" }, &think, &text, n);
    let log = |ok: bool, text: &str, r: Option<&llm::Reply>| {
        if let Ok(mut l) = self.llm_log.lock() {
            l.push(json!({ "tick": tick, "time": time, "hq": hq.id, "model": cfg.model, "request": user, "reply": text, "ok": ok,
                "reasoning": r.map(|r| r.reasoning.as_str()).unwrap_or(""), "tokens": r.and_then(|r| r.tokens), "secs": r.map(|r| (r.secs * 10.0).round() / 10.0), "truncated": r.map(|r| r.truncated) }));
        }
    };
    let reply = match reply { Ok(r) => r, Err(e) => { log(false, &e, None); return Err(e); } };
    let cut = if reply.truncated { format!("ответ оборван потолком токенов ({}) — поднимите потолок или поставьте 0", cfg.max_tokens) } else { String::new() };
    let Some(v) = llm::extract_json(&reply.text) else { log(false, &reply.text, Some(&reply)); return Err(if reply.truncated { cut } else { "ответ не в формате JSON".into() }); };
    let Some(list) = v.get("orders").and_then(Value::as_array) else { log(false, &reply.text, Some(&reply)); return Err(if reply.truncated { cut } else { "в ответе нет списка orders".into() }); };
    log(true, &reply.text, Some(&reply));
    Ok(list.clone())
}

fn assess(&self, w: &World, i: usize) -> Assess {
    let d = &w.divisions[i];
    let doc = &self.rules.doctrine;
    let reach = self.rules.contact_km + self.rules.combat.defense_frontage_km(d) / 2.0;
    let enemy_strength: f64 = w.divisions.iter()
        .filter(|e| e.side != d.side && !e.state.out() && e.vars.pos.dist(d.vars.pos) <= reach)
        .map(|e| self.strength(e)).sum();
    let strength = self.strength(d);
    let broken = strength / d.vars.strength0.max(1e-9) < doc.withdraw_strength_share || d.vars.cohesion < doc.withdraw_cohesion;
    Assess { i, strength, threat: enemy_strength / strength.max(1e-9), broken }
}

/// Точка в `km` за дивизией (по направлению «в тыл» исходной обстановки).
pub(crate) fn behind(&self, w: &World, i: usize, km: f64) -> XY {
    let p = w.divisions[i].vars.pos;
    let r = self.fronts(w)[i].0;
    XY::new(p.x + r.x * km, p.y + r.y * km)
}

/// Глубина дивизий противника в полосе дивизии (полполосы и 2 км по фронту, до 15 км) вдоль направления «в тыл».
fn depths<'a>(&'a self, w: &'a World, i: usize, r: XY) -> impl Iterator<Item = (usize, f64)> + 'a {
    let d = &w.divisions[i];
    let half = self.rules.combat.defense_frontage_km(d) / 2.0 + 2.0;
    w.divisions.iter().enumerate()
        .filter(move |(_, e)| e.side != d.side && !e.state.out())
        .filter_map(move |(j, e)| {
            let (dx, dy) = (e.vars.pos.x - d.vars.pos.x, e.vars.pos.y - d.vars.pos.y);
            let depth = dx * r.x + dy * r.y;
            let lateral = (-dx * r.y + dy * r.x).abs();
            (lateral <= half && depth < 15.0 && depth > -15.0).then_some((j, depth))
        })
}

fn doctrine_hq(&self, w: &World, tick: u32, h: usize, subs: &[usize]) -> Decision {
    let doc = &self.rules.doctrine;
    let mut dec = Decision { orders: Vec::new(), why: Vec::new() };
    let a: Vec<Assess> = subs.iter().map(|&i| self.assess(w, i)).collect();
    // прорывы на полосе штаба: противник продвинулся вглубь полосы дивизии на глубину главной полосы — часть главной
    // позиции потеряна (TM-E 30-451, A); ответ — немедленная контратака резервом во фланг вклинения, если резерва
    // хватает (не меньше 1/3 прорвавшегося — DA Pam 20-233, с. 9, B), иначе — закрыть направление рубежом за ней
    let pens: Vec<(usize, usize)> = a.iter().filter_map(|x| self.penetrator(w, x.i).map(|e| (x.i, e))).collect();
    let mut used: Vec<usize> = Vec::new();
    for x in &a {
        let d = &w.divisions[x.i];
        // окружена: прорыв к ближайшим своим (при угрозе окружения Буссе и Хейнрици выбирали прорыв вопреки приказам
        // держаться; 25.04 Буссе получил свободу направления — hold-orders-1945, LT_HALBE)
        if self.encircled(d, tick) {
            let going = d.state == crate::model::State::Attack(crate::model::AttackSub::Breakout);
            if let Some(t) = self.nearest_linked(w, d.side, d.vars.pos).filter(|_| !going) {
                let h_cut = d.cut_since.map_or(0, |s| tick.saturating_sub(s));
                self.order_for(w, tick, h, x.i, OrderKind::Attack, t, format!("окружена {h_cut} ч — прорыв к своим, до них {:.0} км", t.dist(d.vars.pos)), "доктрина", &mut dec);
            }
            continue;
        }
        let pen = pens.iter().find(|p| p.0 == x.i).map(|p| p.1);
        if x.broken || pen.is_some() {
            // разбита или обойдена: отход на следующий рубеж (угроза охвата — последовательные позиции через 8–10 км,
            // DA Pam 20-233, с. 64–70, B); при приказе «держаться» — держаться
            let why_txt = if let Some(e) = pen { format!("в тылу — {} (угроза охвата)", w.divisions[e].name) } else {
                format!("боевая сила {:.0} % от исходной, организованность {:.2}", 100.0 * x.strength / d.vars.strength0.max(1e-9), d.vars.cohesion) };
            if doc.hold_orders {
                self.order_for(w, tick, h, x.i, OrderKind::Hold, d.vars.pos, format!("{why_txt}; приказ «держаться» (Haltebefehl) — отход запрещён"), "доктрина", &mut dec);
            } else {
                let t = self.line_behind(w, x.i);
                self.order_for(w, tick, h, x.i, OrderKind::Withdraw, t, format!("{why_txt} — отход на следующий рубеж"), "доктрина", &mut dec);
            }
        } else if x.threat > 0.0 {
            let kind = if doc.hold_orders { OrderKind::Hold } else { OrderKind::Defend };
            self.order_for(w, tick, h, x.i, kind, d.vars.pos, format!("противник в соприкосновении, его сила в досягаемости — {:.1} от своей; удерживать полосу", x.threat), "доктрина", &mut dec);
        } else if let Some(&(hit, e)) = pens.iter().filter(|p| !used.contains(&p.1)).min_by(|p, q| w.divisions[p.1].vars.pos.dist(d.vars.pos).total_cmp(&w.divisions[q.1].vars.pos.dist(d.vars.pos))) {
            let ratio = x.strength / self.strength(&w.divisions[e]).max(1e-9);
            if ratio >= doc.counterattack_ratio {
                used.push(e);
                self.order_for(w, tick, h, x.i, OrderKind::Attack, w.divisions[e].vars.pos, format!("контратака во фланг вклинения: {} в тылу у {}, своих сил к прорвавшимся {:.2}", w.divisions[e].name, w.divisions[hit].name, ratio), "доктрина", &mut dec);
            } else {
                let block = self.behind(w, hit, doc.block_depth_km);
                self.order_for(w, tick, h, x.i, OrderKind::Defend, block, format!("сил для контратаки мало ({:.2} к прорвавшимся {}) — занять рубеж за {}", ratio, w.divisions[e].name, w.divisions[hit].name), "доктрина", &mut dec);
            }
        }
    }
    dec
}

/// Решения штабов (по доктрине или на модели) на шаг `tick`: приказы (с задержкой доведения — как у приказов
/// сценария) и записи журнала.
pub fn doctrine_orders(&self, w: &World, tick: u32) -> (Vec<ScriptOrder>, Vec<Event>) {
    let cycle = self.rules.doctrine.cycle_hours.max(1.0) as u32;
    // цикл управления; штабы разнесены по часам, чтобы не решать все разом (на модели — по выбору: в один час)
    let due = |key: usize, sync: bool| if sync { tick % cycle == 0 } else { (tick + key as u32) % cycle == 0 || tick == 0 };
    let subs_of = |h: usize| -> Vec<usize> { (0..w.divisions.len()).filter(|&i| w.divisions[i].hq as usize == h && !w.divisions[i].state.out() && w.divisions[i].state != State::Remnant).collect() };
    let mut decided: Vec<(usize, Decision, String)> = Vec::new();
    // запросы к модели: ведущий штаб (корпус или армия при объединении) и его корпуса с дивизиями
    let mut asks: Vec<(usize, Vec<(usize, Vec<usize>)>)> = Vec::new();
    let su_cycle = self.rules.doctrine_su.cycle_hours.max(1.0) as u32;
    for (h, hq) in w.hqs.iter().enumerate() {
        let src = self.sources[side_idx(hq.side)];
        if src == Source::Script { continue; }
        let subs = subs_of(h);
        if subs.is_empty() { continue; }
        // советская сторона — по своей доктрине (staff_su.rs); на модели решает штаб армии за все её дивизии
        if hq.side == Side::Su {
            if tick % su_cycle != 0 { continue; }
            match (src, &self.llm) {
                (Source::Llm, Some(_)) => { let lead = army_of(w, h); match asks.iter_mut().find(|a| a.0 == lead) { Some(a) => a.1.push((h, subs)), None => asks.push((lead, vec![(h, subs)])) } }
                _ => decided.push((h, self.su_doctrine_hq(w, tick, h, &subs), "по доктрине".into())),
            }
            continue;
        }
        match (src, &self.llm) {
            (Source::Llm, Some(cfg)) => {
                let lead = if cfg.by_army { army_of(w, h) } else { h };
                if !due(lead, cfg.sync || cfg.by_army) { continue; }
                match asks.iter_mut().find(|a| a.0 == lead) { Some(a) => a.1.push((h, subs)), None => asks.push((lead, vec![(h, subs)])) }
            }
            (Source::Llm, None) => if due(h, false) { decided.push((h, self.doctrine_hq(w, tick, h, &subs), "по доктрине: модель не задана".into())) },
            _ => if due(h, false) { decided.push((h, self.doctrine_hq(w, tick, h, &subs), "по доктрине".into())) },
        }
    }
    if let (Some(cfg), false) = (&self.llm, asks.is_empty()) {
        let par = self.llm_parallel(cfg).min(asks.len()).max(1);
        let time = crate::time::format_hours(self.start_hour + tick as i64);
        if let Some(cb) = &self.on_progress { cb(format!("{time}: штабов к модели {}: {}, одновременно {par}…", cfg.model, asks.len())); }
        let next = std::sync::atomic::AtomicUsize::new(0);
        let done = std::sync::atomic::AtomicUsize::new(0);
        let mut res: Vec<(usize, Result<Decision, String>)> = std::thread::scope(|s| {
            let hs: Vec<_> = (0..par).map(|_| s.spawn(|| {
                let mut out = Vec::new();
                loop {
                    let k = next.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
                    let Some((lead, groups)) = asks.get(k) else { break };
                    out.push((k, if w.hqs[*lead].side == Side::Su { self.su_llm_hq(w, tick, *lead, groups, cfg) } else { self.llm_hq(w, tick, *lead, groups, cfg) }));
                    let n = done.fetch_add(1, std::sync::atomic::Ordering::SeqCst) + 1;
                    if let Some(cb) = &self.on_progress { cb(format!("{time}: ответов модели {n} из {}", asks.len())); }
                }
                out
            })).collect();
            hs.into_iter().flat_map(|h| h.join().unwrap_or_default()).collect()
        });
        // порядок применения — по порядку штабов, а не по времени ответа: прогон воспроизводим
        res.sort_by_key(|r| r.0);
        for (k, r) in res {
            let (lead, groups) = &asks[k];
            match r {
                Ok(dec) => {
                    let how = if groups.len() > 1 || groups[0].0 != *lead { format!("языковая модель {}, за корпуса: {}", cfg.model, groups.iter().map(|g| w.hqs[g.0].name.as_str()).collect::<Vec<_>>().join(", ")) } else { format!("языковая модель {}", cfg.model) };
                    decided.push((*lead, dec, how));
                }
                Err(e) => for (h, subs) in groups {
                    let dec = if w.hqs[*h].side == Side::Su { self.su_doctrine_hq(w, tick, *h, subs) } else { self.doctrine_hq(w, tick, *h, subs) };
                    decided.push((*h, dec, format!("по доктрине: модель не дала решения — {e}")))
                },
            }
        }
    }
    let mut orders = Vec::new();
    let mut journal = Vec::new();
    for (h, dec, how) in decided {
        if !dec.why.is_empty() {
            journal.push(Event { tick, agent: u32::MAX, text: format!("штаб «{}» ({how}): {}", w.hqs[h].name, dec.why.join("; ")) });
        }
        orders.extend(dec.orders);
    }
    (orders, journal)
}

/// Центр противника вокруг дивизии (в 20 км; если никого — всех).
fn enemy_center(&self, w: &World, i: usize) -> XY {
    let d = &w.divisions[i];
    let pick = |lim: f64| -> Option<XY> {
        let v: Vec<XY> = w.divisions.iter().filter(|e| e.side != d.side && !e.state.out() && e.vars.pos.dist(d.vars.pos) <= lim).map(|e| e.vars.pos).collect();
        if v.is_empty() { None } else { Some(XY::new(v.iter().map(|p| p.x).sum::<f64>() / v.len() as f64, v.iter().map(|p| p.y).sum::<f64>() / v.len() as f64)) }
    };
    pick(20.0).or_else(|| pick(f64::INFINITY)).unwrap_or(d.vars.pos)
}

/// Направление «в тыл» каждой дивизии по исходной обстановке (от центра противника в 20 км к дивизии) и исходная
/// глубина противника в её полосе — неизменны в прогоне: на плацдарме, где противник охватывает с трёх сторон, а
/// дивизии — точки в центре своих районов, «тыл» и «прорыв» иначе сбиваются.
pub(crate) fn fronts(&self, w: &World) -> &Vec<(XY, f64)> {
    self.rear_dir.get_or_init(|| (0..w.divisions.len()).map(|i| {
        let p = w.divisions[i].vars.pos;
        let c = self.enemy_center(w, i);
        let (dx, dy) = (p.x - c.x, p.y - c.y);
        let l = (dx * dx + dy * dy).sqrt();
        let r = if l < 1e-6 { XY::new(-1.0, 0.0) } else { XY::new(dx / l, dy / l) };
        let base = self.depths(w, i, r).map(|x| x.1).fold(f64::NEG_INFINITY, f64::max);
        (r, base)
    }).collect())
}

/// Следующий свой рубеж (укреплённая полоса театра) за дивизией; если его нет — точка в withdraw_step_km за ней.
fn line_behind(&self, w: &World, i: usize) -> XY {
    let d = &w.divisions[i];
    let t = &*self.theatre;
    let side = match d.side { Side::Su => "su", Side::De => "de" };
    let c = self.enemy_center(w, i);
    let here = d.vars.pos.dist(c);
    let mut best: Option<(XY, f64)> = None;
    for l in t.lines.iter().filter(|l| l.side.as_deref() == Some(side) && l.fortification.unwrap_or(0) > 0) {
        for p in l.line.iter().map(|p| t.proj.to_xy(*p)) {
            if p.dist(c) < here + 2.0 { continue; } // не позади
            let k = p.dist(d.vars.pos);
            if best.map_or(true, |(_, b)| k < b) { best = Some((p, k)); }
        }
    }
    best.map(|b| b.0).unwrap_or_else(|| self.behind(w, i, self.rules.doctrine.withdraw_step_km))
}

    /// Решение штаба на языковой модели: обстановка → JSON с приказами из тех же действий, что у доктрины. `lead` —
    /// штаб, который решает (корпус или армия при объединении), `groups` — его корпуса с дивизиями.
    fn llm_hq(&self, w: &World, tick: u32, lead: usize, groups: &[(usize, Vec<usize>)], cfg: &llm::LlmConfig) -> Result<Decision, String> {
        let hq = &w.hqs[lead];
        let time = crate::time::format_hours(self.start_hour + tick as i64);
        let doc = &self.rules.doctrine;
        let joint = groups.len() > 1 || groups[0].0 != lead;
        let who = if joint {
            format!("Ты — начальник штаба армии «{}» в Берлинской операции, апрель 1945 года. Раз в {} ч ты решаешь за подчинённые корпуса ({}), что приказать их дивизиям.",
                hq.name, doc.cycle_hours, groups.iter().map(|g| w.hqs[g.0].name.as_str()).collect::<Vec<_>>().join(", "))
        } else {
            format!("Ты — начальник штаба соединения «{}» ({}) в Берлинской операции, апрель 1945 года. Раз в {} ч ты решаешь, что приказать подчинённым дивизиям.",
                hq.name, match hq.echelon { Echelon::Corps => "корпус", Echelon::Army => "армия", Echelon::Front => "группа армий" }, doc.cycle_hours)
        };
        let system = format!(
            "{who} Действуй по немецкой доктрине обороны 1944–1945 гг.: вклинение противника — немедленная контратака резервом во фланг (силы не меньше 1/3 прорвавшегося), если сил мало — закрыть направление рубежом; обойдённой или разбитой дивизии — отход на следующий рубеж; общий отход армии без приказа сверху запрещён{}; окружённой дивизии (encircled_hours — сколько часов нет пути к своим, own_lines_km — до своих) — прорыв к своим, пока есть боеприпасы.
Доступные действия: hold — держаться на месте, не отходить; defend — оборонять текущий район; withdraw — отойти на следующий рубеж позади; counterattack — контратаковать дивизию противника (target — её id); block — занять рубеж за своей дивизией (target — её id); breakout — окружённой дивизии прорываться к ближайшим своим.
Ответь только JSON без пояснений вокруг: {}. По дивизии, которой приказ не меняешь, приказ не давай.",
            if doc.hold_orders { "; действует приказ «держаться» — отход запрещён" } else { "" }, REPLY_FORMAT);
        let situation = if joint {
            json!({ "corps": groups.iter().map(|(h, subs)| json!({ "corps": w.hqs[*h].name, "divisions": self.situation(w, subs)["divisions"] })).collect::<Vec<_>>() })
        } else { self.situation(w, &groups[0].1) };
        let user = format!("Время: {time} (МСК). Обстановка по дивизиям (сила противника — в долях своей; strength_pct — от исходной):\n{situation}");
        let list = self.ask_staff(tick, hq, system, user, cfg)?;
        let mut dec = Decision { orders: Vec::new(), why: Vec::new() };
        let id_of = |s: &str| w.divisions.iter().position(|d| d.id == s);
        for o in &list {
            let Some(i) = o.get("division").and_then(Value::as_str).and_then(id_of) else { continue };
            let Some(h) = groups.iter().find(|g| g.1.contains(&i)).map(|g| g.0) else { continue };
            let d = &w.divisions[i];
            let reason = o.get("reason").and_then(Value::as_str).unwrap_or("").to_string();
            let target = o.get("target").and_then(Value::as_str).and_then(id_of);
            match o.get("action").and_then(Value::as_str).unwrap_or("") {
                "hold" => self.order_for(w, tick, h, i, OrderKind::Hold, d.vars.pos, reason, "модель", &mut dec),
                "defend" => self.order_for(w, tick, h, i, OrderKind::Defend, d.vars.pos, reason, "модель", &mut dec),
                "withdraw" if !doc.hold_orders => { let t = self.line_behind(w, i); self.order_for(w, tick, h, i, OrderKind::Withdraw, t, reason, "модель", &mut dec) }
                "counterattack" => match target {
                    Some(j) if w.divisions[j].side != d.side && w.divisions[j].vars.pos.dist(d.vars.pos) <= 25.0 =>
                        self.order_for(w, tick, h, i, OrderKind::Attack, w.divisions[j].vars.pos, reason, "модель", &mut dec),
                    _ => dec.why.push(format!("{} — отклонено: цель контратаки не найдена рядом", d.name)),
                },
                "block" => match target {
                    Some(j) if w.divisions[j].side == d.side => { let t = self.behind(w, j, doc.block_depth_km); self.order_for(w, tick, h, i, OrderKind::Defend, t, reason, "модель", &mut dec) }
                    _ => dec.why.push(format!("{} — отклонено: не указана своя дивизия, за которой занять рубеж", d.name)),
                },
                "breakout" => match self.encircled(d, tick).then(|| self.nearest_linked(w, d.side, d.vars.pos)).flatten() {
                    Some(t) => self.order_for(w, tick, h, i, OrderKind::Attack, t, reason, "модель", &mut dec),
                    None => dec.why.push(format!("{} — отклонено: дивизия не в окружении", d.name)),
                },
                other => dec.why.push(format!("{} — отклонено: недопустимое действие «{other}»", d.name)),
            }
        }
        Ok(dec)
    }

/// Число одновременных запросов к модели: из настроек или замером один раз за прогон.
fn llm_parallel(&self, cfg: &llm::LlmConfig) -> usize {
    if cfg.parallel > 0 { return cfg.parallel; }
    *self.llm_par.get_or_init(|| {
        if let Some(cb) = &self.on_progress { cb(format!("замер параллельных запросов к модели {}…", cfg.model)); }
        match llm::probe_parallel(cfg, 16) {
            Ok(p) => { if let Ok(mut l) = self.llm_probe.lock() { *l = Some(p.to_json()); } p.best }
            Err(e) => { if let Ok(mut l) = self.llm_probe.lock() { *l = Some(json!({ "best": 1, "error": e })); } 1 }
        }
    })
}

/// Приказ дивизии, если он отличается от действующего.
pub(crate) fn order_for(&self, w: &World, tick: u32, h: usize, i: usize, kind: OrderKind, target: XY, note: String, src: &str, dec: &mut Decision) {
    let d = &w.divisions[i];
    if let Some(o) = &d.order { if o.kind == kind && o.target.dist(target) < 2.0 { return; } }
    dec.why.push(format!("{} — {}: {}", d.name, kind.label(), note));
    dec.orders.push(ScriptOrder { at: tick, hq: h as u32, to: vec![i as u32], kind, target: Some(target), forced: false, note: format!("решение штаба ({src}): {note}"), follow: None, offset: XY::default() });
}

/// Прорвавшийся: дивизия противника в полосе дивизии, продвинувшаяся вглубь дальше исходной глубины противника
/// в этой полосе на глубину главной полосы обороны (5–6 км, БУП-42 §619, A) — главная полоса прорвана.
fn penetrator(&self, w: &World, i: usize) -> Option<usize> {
    let (r, base) = self.fronts(w)[i];
    let base = if base.is_finite() { base } else { -6.0 };
    let need = base + self.rules.doctrine.penetration_depth_km;
    self.depths(w, i, r).filter(|x| x.1 > need).max_by(|x, y| x.1.total_cmp(&y.1).then(y.0.cmp(&x.0))).map(|x| x.0)
}

/// Обстановка для штаба на модели: свои дивизии с оценкой, противник рядом, рубеж позади.
fn situation(&self, w: &World, subs: &[usize]) -> Value {
    let km1 = |x: f64| (x * 10.0).round() / 10.0;
    let divs: Vec<Value> = subs.iter().map(|&i| {
        let x = self.assess(w, i);
        let d = &w.divisions[i];
        let mut enemies: Vec<(usize, f64)> = w.divisions.iter().enumerate()
            .filter(|(_, e)| e.side != d.side && !e.state.out())
            .map(|(j, e)| (j, e.vars.pos.dist(d.vars.pos))).filter(|x| x.1 <= 15.0).collect();
        enemies.sort_by(|a, b| a.1.total_cmp(&b.1));
        let line = self.line_behind(w, i);
        json!({
            "id": d.id, "name": d.name, "state": d.state.label(),
            "people": d.vars.personnel.round(), "tanks": d.vars.tanks.round(),
            "strength_pct_of_initial": (100.0 * x.strength / d.vars.strength0.max(1e-9)).round(),
            "cohesion": km1(d.vars.cohesion), "ammo": km1(d.vars.ammo),
            "enemy_strength_in_reach_vs_own": km1(x.threat),
            "penetrated_by": self.penetrator(w, i).map(|e| json!({ "id": w.divisions[e].id, "name": w.divisions[e].name })),
            "current_order": d.order.as_ref().map(|o| o.kind.label()),
            "enemies_within_15km": enemies.iter().take(4).map(|&(j, k)| json!({ "id": w.divisions[j].id, "name": w.divisions[j].name, "km": km1(k), "state": w.divisions[j].state.label() })).collect::<Vec<_>>(),
            "next_line_behind_km": km1(line.dist(d.vars.pos)),
            "encircled_hours": self.encircled(d, w.tick).then(|| d.cut_since.map_or(0, |s| w.tick.saturating_sub(s))),
            "own_lines_km": self.encircled(d, w.tick).then(|| self.nearest_linked(w, d.side, d.vars.pos).map(|p| km1(p.dist(d.vars.pos)))).flatten(),
        })
    }).collect();
    json!({ "divisions": divs })
}

/// Источник решений штабов стороны.
pub enum Source {
    /// Приказы сценария (исторические задачи).
    Script,
    /// Штабы по доктрине стороны.
    Doctrine,
    /// Штабы на языковой модели (Sim::llm); при сбое — по доктрине.
    Llm,
}

/// Армия, в которую входит штаб (сам штаб, если он армия или выше её нет).
fn army_of(w: &World, h: usize) -> usize {
    let mut k = h;
    loop {
        if w.hqs[k].echelon == Echelon::Army { return k; }
        match w.hqs[k].parent { Some(p) => k = p as usize, None => return h }
    }
}

/// Место дивизии в построении армии.
pub enum Ech {
    #[default]
    Unset,
    First,
    Second,
    Mobile,
    Committed,
}

/// Замысел армии для дивизии: последняя задача сценария.
pub struct Plan {
    pub kind: OrderKind,
    pub target: XY,
    pub forced: bool,
    pub note: String,
}

/// Решение штаба армии по советской доктрине.
pub(crate) fn su_doctrine_hq(&self, w: &World, tick: u32, h: usize, subs: &[usize]) -> Decision {
    let doc = &self.rules.doctrine_su;
    let mut dec = Decision { orders: Vec::new(), why: Vec::new() };
    let Ok(mut st) = self.su_staff.lock() else { return dec };
    st.fit(w.divisions.len());
    let attack_plan = |st: &SuStaff, i: usize| st.plan[i].as_ref().is_some_and(|p| p.kind == OrderKind::Attack);
    let enemy_km = |i: usize| w.divisions.iter().filter(|e| e.side != w.divisions[i].side && !e.state.out()).map(|e| e.vars.pos.dist(w.divisions[i].vars.pos)).fold(f64::INFINITY, f64::min);
    // продвижение от исходного к цели замысла, км
    let advance = |st: &SuStaff, i: usize| -> f64 {
        let (Some(s), Some(p)) = (st.start[i], st.plan[i].as_ref()) else { return 0.0 };
        let (tx, ty) = (p.target.x - s.x, p.target.y - s.y);
        let l = (tx * tx + ty * ty).sqrt();
        let q = w.divisions[i].vars.pos;
        if l < 1e-6 { return 0.0 }
        ((q.x - s.x) * tx + (q.y - s.y) * ty) / l
    };
    let give = |st: &mut SuStaff, i: usize, why: String, dec: &mut Decision| {
        if let Some(p) = st.plan[i].clone() { self.order_for(w, tick, h, i, p.kind, p.target, format!("{why}; задача: {}", p.note), "доктрина", dec); }
    };
    let mobile_army = subs.iter().filter(|&&i| mobile(&w.divisions[i])).count() * 2 >= subs.len().max(1);

    // построение: кто ещё не распределён
    let unset: Vec<usize> = subs.iter().copied().filter(|&i| st.ech[i] == Ech::Unset && attack_plan(&st, i)).collect();
    if mobile_army {
        for &i in &unset { st.ech[i] = Ech::Mobile; st.since[i] = tick; dec.why.push(format!("{} — подвижная группа: ждёт прорыва тактической зоны", w.divisions[i].name)); }
    } else {
        let (mut rifle, npp): (Vec<usize>, Vec<usize>) = unset.iter().partition(|&&i| !mobile(&w.divisions[i]));
        for &i in &npp { st.ech[i] = Ech::First; give(&mut st, i, "танки непосредственной поддержки пехоты — с первым эшелоном".into(), &mut dec); }
        rifle.sort_by(|&a, &b| enemy_km(a).total_cmp(&enemy_km(b)).then(a.cmp(&b)));
        let n1 = ((rifle.len() as f64) * doc.first_echelon_share).ceil() as usize;
        for (k, &i) in rifle.iter().enumerate() {
            if k < n1 { st.ech[i] = Ech::First; give(&mut st, i, "первый эшелон армии".into(), &mut dec); }
            else { st.ech[i] = Ech::Second; st.since[i] = tick; dec.why.push(format!("{} — второй эшелон армии: ждёт прорыва главной полосы или смены", w.divisions[i].name)); }
        }
    }

    // ввод второго эшелона
    let first: Vec<usize> = subs.iter().copied().filter(|&i| st.ech[i] == Ech::First && attack_plan(&st, i)).collect();
    let mut second: Vec<usize> = subs.iter().copied().filter(|&i| st.ech[i] == Ech::Second).collect();
    if !first.is_empty() && !second.is_empty() {
        let mean = first.iter().map(|&i| advance(&st, i)).sum::<f64>() / first.len() as f64;
        let waited = second.iter().map(|&i| tick.saturating_sub(st.since[i])).min().unwrap_or(0) as f64;
        if mean >= doc.commit_depth_km || waited >= doc.second_echelon_fallback_hours {
            let why = if mean >= doc.commit_depth_km { format!("первый эшелон продвинулся на {mean:.1} км — главная полоса прорвана, ввод второго эшелона") }
                else { format!("{waited:.0} ч в ожидании — второй эшелон вводится на 2–3-й день (продвижение первого {mean:.1} км)") };
            for &i in &second { st.ech[i] = Ech::Committed; give(&mut st, i, why.clone(), &mut dec); }
            second.clear();
        } else {
            // смена остановившейся дивизии первого эшелона ближайшей дивизией второго
            for &i in &first {
                let d = &w.divisions[i];
                let stalled = matches!(d.state, State::Defense(_)) && enemy_km(i) <= self.rules.contact_km + 4.0;
                if !stalled || st.replaced[i] || second.is_empty() { continue; }
                let k = (0..second.len()).min_by(|&a, &b| w.divisions[second[a]].vars.pos.dist(d.vars.pos).total_cmp(&w.divisions[second[b]].vars.pos.dist(d.vars.pos))).unwrap();
                let j = second.remove(k);
                st.replaced[i] = true;
                st.ech[j] = Ech::Committed;
                give(&mut st, j, format!("{} остановилась ({}) — смена вторым эшелоном", d.name, d.state.label()), &mut dec);
            }
        }
    }

    // ввод подвижной группы: соседние стрелковые дивизии прорвали тактическую зону
    let mob: Vec<usize> = subs.iter().copied().filter(|&i| st.ech[i] == Ech::Mobile).collect();
    for &i in &mob {
        let p = w.divisions[i].vars.pos;
        let broke = (0..w.divisions.len()).filter(|&j| { let e = &w.divisions[j]; e.side == w.divisions[i].side && !mobile(e) && !e.state.out() && e.vars.pos.dist(p) <= 25.0 })
            .map(|j| advance(&st, j)).fold(0.0, f64::max);
        let waited = (tick - st.since[i]) as f64;
        let why = if broke >= doc.tank_commit_depth_km { Some(format!("стрелковые дивизии рядом продвинулись на {broke:.1} км — тактическая зона прорвана, ввод подвижной группы")) }
            else if waited >= doc.tank_commit_fallback_hours { Some(format!("за {waited:.0} ч тактическая зона не прорвана (продвижение {broke:.1} км) — ввод для завершения прорыва")) }
            else { None };
        if let Some(why) = why { st.ech[i] = Ech::Committed; give(&mut st, i, why, &mut dec); }
    }
    dec
}

/// Решение штаба армии на языковой модели: кем и когда наступать на цели замысла.
pub(crate) fn su_llm_hq(&self, w: &World, tick: u32, lead: usize, groups: &[(usize, Vec<usize>)], cfg: &llm::LlmConfig) -> Result<Decision, String> {
    let doc = &self.rules.doctrine_su;
    let hq = &w.hqs[lead];
    let km1 = |x: f64| (x * 10.0).round() / 10.0;
    let all: Vec<usize> = groups.iter().flat_map(|g| g.1.iter().copied()).collect();
    let situation = {
        let Ok(mut st) = self.su_staff.lock() else { return Err("штаб занят".into()) };
        st.fit(w.divisions.len());
        let divs: Vec<Value> = all.iter().map(|&i| {
            let d = &w.divisions[i];
            let plan = st.plan[i].as_ref();
            let advance = match (st.start[i], plan) {
                (Some(s0), Some(p)) => { let (tx, ty) = (p.target.x - s0.x, p.target.y - s0.y); let l = (tx * tx + ty * ty).sqrt().max(1e-6); ((d.vars.pos.x - s0.x) * tx + (d.vars.pos.y - s0.y) * ty) / l }
                _ => 0.0,
            };
            let mut enemies: Vec<(usize, f64)> = w.divisions.iter().enumerate().filter(|(_, e)| e.side != d.side && !e.state.out())
                .map(|(j, e)| (j, e.vars.pos.dist(d.vars.pos))).filter(|x| x.1 <= 15.0).collect();
            enemies.sort_by(|a, b| a.1.total_cmp(&b.1));
            json!({
                "id": d.id, "name": d.name, "type": if mobile(d) { "подвижная (танки, мехпехота, конница)" } else { "стрелковая" },
                "state": d.state.label(), "people": d.vars.personnel.round(), "tanks": d.vars.tanks.round(),
                "strength_pct_of_initial": (100.0 * self.strength(d) / d.vars.strength0.max(1e-9)).round(), "ammo": km1(d.vars.ammo),
                "echelon": match st.ech[i] { Ech::Unset => "не распределена", Ech::First => "первый эшелон", Ech::Second => "второй эшелон (ждёт)", Ech::Mobile => "подвижная группа (ждёт ввода)", Ech::Committed => "введена в бой" },
                "objective": plan.filter(|p| p.kind == OrderKind::Attack).map(|p| json!({ "task": p.note, "km_to_objective": km1(p.target.dist(d.vars.pos)), "advanced_km": km1(advance) })),
                "current_order": d.order.as_ref().map(|o| o.kind.label()),
                "enemies_within_15km": enemies.iter().take(4).map(|&(j, k)| json!({ "id": w.divisions[j].id, "name": w.divisions[j].name, "km": km1(k), "state": w.divisions[j].state.label() })).collect::<Vec<_>>(),
            })
        }).collect();
        json!({ "divisions": divs })
    };
    let system = format!(
        "Ты — начальник штаба армии «{}» в Берлинской операции, апрель 1945 года. Раз в {} ч ты решаешь, какие дивизии армии наступают на цели замысла армии, какие ждут, какие закрепляются.\nДействуй по советской доктрине наступления 1944–45 гг.: стрелковые дивизии — в два эшелона, около {:.0} % в первом; второй эшелон вводится, когда первый продвинулся на глубину главной полосы ({:.0} км) или на 2–3-й день, а дивизия второго эшелона — на смену остановившейся; подвижную группу (танковую армию, корпус) вводят после прорыва тактической зоны ({:.0} км) или для завершения прорыва, если его нет за {:.0} ч; узел, где атака не идёт, — обходить; не штурмовать с ходу неподавленного противника, а закрепиться и атаковать утром после артподготовки.\nДоступные действия: attack — наступать на цель замысла (objective); attack_enemy — атаковать дивизию противника (target — её id); wait — ждать во втором эшелоне или в резерве; defend — закрепиться на месте.\nОтветь только JSON без пояснений вокруг: {}. По дивизии, которой приказ не меняешь, приказ не давай.",
        hq.name, doc.cycle_hours, doc.first_echelon_share * 100.0, doc.commit_depth_km, doc.tank_commit_depth_km, doc.tank_commit_fallback_hours, SU_REPLY_FORMAT);
    let time = crate::time::format_hours(self.start_hour + tick as i64);
    let user = format!("Время: {time} (МСК). Обстановка по дивизиям армии (strength_pct — от исходной; advanced_km — продвижение к цели от исходного положения):\n{situation}");
    let list = self.ask_staff(tick, hq, system, user, cfg)?;
    let mut dec = Decision { orders: Vec::new(), why: Vec::new() };
    let Ok(mut st) = self.su_staff.lock() else { return Ok(dec) };
    let id_of = |s: &str| w.divisions.iter().position(|d| d.id == s);
    for o in &list {
        let Some(i) = o.get("division").and_then(Value::as_str).and_then(id_of) else { continue };
        let Some(h) = groups.iter().find(|g| g.1.contains(&i)).map(|g| g.0) else { continue };
        let d = &w.divisions[i];
        let reason = o.get("reason").and_then(Value::as_str).unwrap_or("").to_string();
        match o.get("action").and_then(Value::as_str).unwrap_or("") {
            "attack" => match st.plan[i].clone().filter(|p| p.kind == OrderKind::Attack) {
                Some(p) => { st.ech[i] = if st.ech[i] == Ech::Unset { Ech::First } else { Ech::Committed }; self.order_for(w, tick, h, i, OrderKind::Attack, p.target, format!("{reason}; задача: {}", p.note), "модель", &mut dec) }
                None => dec.why.push(format!("{} — отклонено: у дивизии нет цели наступления", d.name)),
            },
            "attack_enemy" => match o.get("target").and_then(Value::as_str).and_then(id_of) {
                Some(j) if w.divisions[j].side != d.side && w.divisions[j].vars.pos.dist(d.vars.pos) <= 25.0 => {
                    st.ech[i] = Ech::Committed;
                    self.order_for(w, tick, h, i, OrderKind::Attack, w.divisions[j].vars.pos, reason, "модель", &mut dec)
                }
                _ => dec.why.push(format!("{} — отклонено: цель атаки не найдена рядом", d.name)),
            },
            "wait" => { if st.ech[i] == Ech::Unset { st.ech[i] = if mobile(d) { Ech::Mobile } else { Ech::Second }; st.since[i] = tick; } dec.why.push(format!("{} — ждёт: {reason}", d.name)); }
            "defend" => self.order_for(w, tick, h, i, OrderKind::Defend, d.vars.pos, reason, "модель", &mut dec),
            other => dec.why.push(format!("{} — отклонено: недопустимое действие «{other}»", d.name)),
        }
    }
    Ok(dec)
}

/// Задача сценария советской дивизии в режиме «по доктрине»: замысел; дивизиям, уже введённым в бой, и задачи
/// не на наступление — сразу, остальным — по решению штаба (su_doctrine_hq).
pub(crate) fn su_plan(&self, w: &World, o: &ScriptOrder, due: &mut Vec<ScriptOrder>) {
    let Ok(mut st) = self.su_staff.lock() else { return };
    st.fit(w.divisions.len());
    let follow_at = o.follow.as_deref().and_then(|f| self.place_of(w, f));
    for &d in &o.to {
        let i = d as usize;
        let pos = w.divisions[i].vars.pos;
        let target = match follow_at { Some(c) => XY::new(c.x + o.offset.x, c.y + o.offset.y), None => o.target.unwrap_or(pos) };
        st.plan[i] = Some(Plan { kind: o.kind, target, forced: o.forced, note: o.note.clone() });
        if st.start[i].is_none() { st.start[i] = Some(pos); }
        if o.kind != OrderKind::Attack || matches!(st.ech[i], Ech::First | Ech::Committed) {
            due.push(ScriptOrder { to: vec![d], target: Some(target), follow: None, offset: XY::default(), ..o.clone() });
        }
    }
}

pub struct SuStaff {
    pub plan: Vec<Option<Plan>>,
    pub ech: Vec<Ech>,
    /// Положение дивизии, когда она получила первую задачу, — от него считается продвижение.
    pub start: Vec<Option<XY>>,
    pub since: Vec<u32>,
    pub replaced: Vec<bool>,
}

fn fit(&mut self, n: usize) {
    if self.plan.len() < n {
        self.plan.resize(n, None);
        self.ech.resize(n, Ech::Unset);
        self.start.resize(n, None);
        self.since.resize(n, 0);
        self.replaced.resize(n, false);
    }
}

pub struct AreaData {
    pub id: String,
    pub name: String,
    pub ring: Vec<LngLat>,
}

/// Мост или переправа из данных театра: когда действует.
pub struct Bridge {
    pub id: String,
    pub name: String,
    pub pos: XY,
    pub open_from: Option<i64>,
    pub destroyed_at: Option<i64>,
}

/// Действует ли мост в момент `hour` (часы от 1970-01-01) по данным театра.
pub fn open_at(&self, hour: i64) -> bool {
    self.open_from.map_or(true, |t| hour >= t) && self.destroyed_at.map_or(true, |t| hour < t)
}

struct Grid {
    bbox: [f64; 4],
    cols: usize,
    rows: usize,
    rle: String,
}

pub struct Theatre {
    pub id: String,
    pub name: String,
    pub proj: Proj,
    pub bbox: [f64; 4],
    pub cols: usize,
    pub rows: usize,
    /// Класс местности клетки (индекс в TERRAIN).
    pub terrain: Vec<u8>,
    /// Дорога в клетке: 0 — нет, 1 — дорога, 2 — шоссе.
    pub road: Vec<u8>,
    /// Биты направлений DIRS: переход в соседа пересекает большую реку.
    pub river_cross: Vec<u8>,
    /// Мост на переходе (клетка, направление) → индекс в `bridges`.
    pub crossing_bridge: HashMap<(u32, u8), u16>,
    pub bridges: Vec<Bridge>,
    pub lines: Vec<LineData>,
    pub areas: Vec<AreaData>,
    /// Центры клеток в км.
    pub centers: Vec<XY>,
    /// Укреплённая полоса в клетке: уровень (0 — нет) и чья (как в нынешней модели: клетки в пределах половины
    /// глубины полосы от её линии, не меньше одной клетки).
    pub fort: Vec<u8>,
    pub fort_side: Vec<Option<String>>,
    /// Город по обводам обороны (сценарий, cityRings): 0 — не город, 1 — внутри внешнего обвода, 2 — внутри
    /// внутреннего (кольцо S-Bahn), 3 — «Цитадель».
    pub city: Vec<u8>,
}

fn build(f: TheatreFile) -> Result<Theatre, String> {
    let g = &f.terrain_grid;
    let (cols, rows) = (g.cols, g.rows);
    let n = cols * rows;
    let terrain = decode_terrain(&g.rle, n)?;
    let mut road = vec![0u8; n];
    if let Some(rg) = &f.road_grid {
        if rg.cols != cols || rg.rows != rows || rg.bbox != g.bbox {
            return Err("roadGrid не совпадает с terrainGrid по сетке".into());
        }
        road = decode_rle(&rg.rle, n, |c| match c { 'n' => Some(0), 'r' => Some(1), 'h' => Some(2), _ => None })?;
    }
    let proj = Proj::new(f.bbox);
    let mut t = Theatre {
        id: f.id,
        name: f.name,
        proj,
        bbox: g.bbox,
        cols,
        rows,
        terrain,
        road,
        river_cross: vec![0u8; n],
        crossing_bridge: HashMap::new(),
        bridges: Vec::new(),
        lines: f.lines,
        areas: f.areas,
        centers: Vec::with_capacity(n),
        fort: vec![0u8; n],
        fort_side: vec![None; n],
        city: vec![0; n],
    };
    for i in 0..n { let c = t.cell_lnglat(i); t.centers.push(proj.to_xy(c)); }
    // шоссе из линий: отмечаем клетки вдоль линии (железные дороги в движении войск не участвуют)
    for r in &f.roads {
        let k = match r.kind.as_deref() { Some("highway") => 2, Some("road") => 1, _ => continue };
        for w in r.line.windows(2) {
            let (a, b) = (proj.to_xy(w[0]), proj.to_xy(w[1]));
            let steps = (a.dist(b) / 0.3).ceil().max(1.0) as usize;
            for s in 0..=steps {
                let p = proj.to_lnglat(XY::new(a.x + (b.x - a.x) * s as f64 / steps as f64, a.y + (b.y - a.y) * s as f64 / steps as f64));
                if let Some(c) = t.cell_of(p) { t.road[c] = t.road[c].max(k); }
            }
        }
    }
    for b in &f.bridges {
        t.bridges.push(Bridge {
            id: b.id.clone(),
            name: b.name.clone().unwrap_or_else(|| b.id.clone()),
            pos: proj.to_xy(b.at),
            open_from: b.open_from.as_deref().and_then(parse_hours),
            destroyed_at: b.destroyed_at.as_deref().and_then(parse_hours),
        });
    }
    t.mark_rivers(&f.rivers);
    t.mark_forts();
    Ok(t)
}

pub fn cell_lnglat(&self, i: usize) -> LngLat {
    let (col, row) = (i % self.cols, i / self.cols);
    let [w, s, e, n] = self.bbox;
    [w + (col as f64 + 0.5) * (e - w) / self.cols as f64, n - (row as f64 + 0.5) * (n - s) / self.rows as f64]
}

pub fn cell_of(&self, p: LngLat) -> Option<usize> {
    let [w, s, e, n] = self.bbox;
    if p[0] < w || p[0] >= e || p[1] <= s || p[1] > n { return None; }
    let col = ((p[0] - w) / (e - w) * self.cols as f64) as usize;
    let row = ((n - p[1]) / (n - s) * self.rows as f64) as usize;
    Some(row.min(self.rows - 1) * self.cols + col.min(self.cols - 1))
}

/// Ближайшая к точке клетка суши (войска не стоят в воде).
pub fn land_cell_near(&self, q: XY) -> Option<usize> {
    let c = self.cell_of_xy(q)?;
    if self.terrain[c] != WATER { return Some(c); }
    let (col, row) = ((c % self.cols) as i32, (c / self.cols) as i32);
    for r in 1..6i32 {
        let mut best: Option<(usize, f64)> = None;
        for dr in -r..=r {
            for dc in -r..=r {
                if dr.abs() != r && dc.abs() != r { continue; }
                let (cc, rr) = (col + dc, row + dr);
                if cc < 0 || rr < 0 || cc >= self.cols as i32 || rr >= self.rows as i32 { continue; }
                let k = rr as usize * self.cols + cc as usize;
                if self.terrain[k] == WATER { continue; }
                let d = self.centers[k].dist(q);
                if best.map_or(true, |(_, bd)| d < bd) { best = Some((k, d)); }
            }
        }
        if let Some((k, _)) = best { return Some(k); }
    }
    None
}

pub fn load(path: &str) -> Result<Theatre, String> {
    let text = std::fs::read_to_string(path).map_err(|e| format!("{path}: {e}"))?;
    let f: TheatreFile = serde_json::from_str(&text).map_err(|e| format!("{path}: {e}"))?;
    Theatre::build(f)
}

/// Город внутри обвода обороны: клетки внутри многоугольника получают уровень города не ниже `level`. Укреплением
/// обводы не помечаются: город замедляют городская норма темпа (combat.urban) и местность — иначе один и тот же
/// эффект учитывался бы трижды.
pub fn mark_city(&mut self, ring: &[LngLat], level: u8, side: &str) -> usize {
    let poly: Vec<XY> = ring.iter().map(|p| self.proj.to_xy(*p)).collect();
    if poly.len() < 3 { return 0; }
    let mut n = 0;
    for c in 0..self.cols * self.rows {
        let p = self.centers[c];
        let mut inside = false;
        let mut j = poly.len() - 1;
        for i in 0..poly.len() {
            let (a, b) = (poly[i], poly[j]);
            if (a.y > p.y) != (b.y > p.y) && p.x < (b.x - a.x) * (p.y - a.y) / (b.y - a.y) + a.x { inside = !inside; }
            j = i;
        }
        if !inside { continue; }
        if self.city[c] < level { self.city[c] = level; n += 1; }
        let _ = side;
    }
    n
}

fn mark_forts(&mut self) {
    let lines = self.lines.clone();
    for l in &lines {
        let Some(lv) = l.fortification.filter(|&v| v > 0) else { continue };
        let half = l.depth_km.unwrap_or(0.0) / 2.0;
        for w in l.line.windows(2) {
            let (a, b) = (self.proj.to_xy(w[0]), self.proj.to_xy(w[1]));
            let steps = (a.dist(b) / 0.3).ceil().max(1.0) as usize;
            for k in 0..=steps {
                let q = XY::new(a.x + (b.x - a.x) * k as f64 / steps as f64, a.y + (b.y - a.y) * k as f64 / steps as f64);
                let Some(c) = self.cell_of_xy(q) else { continue };
                let r = (half.max(0.0) / 1.0).ceil() as i32 + 1;
                let (c0, r0) = ((c % self.cols) as i32, (c / self.cols) as i32);
                for dr in -r..=r {
                    for dc in -r..=r {
                        let (cc, rr) = (c0 + dc, r0 + dr);
                        if cc < 0 || rr < 0 || cc >= self.cols as i32 || rr >= self.rows as i32 { continue; }
                        let i = rr as usize * self.cols + cc as usize;
                        let near = self.centers[i].dist(q) <= half.max(0.5);
                        if near && lv >= self.fort[i] { self.fort[i] = lv; self.fort_side[i] = l.side.clone(); }
                    }
                }
            }
        }
    }
}

/// Переходы между клетками, пересекающие большие реки, и мосты на них.
fn mark_rivers(&mut self, rivers: &[Line]) {
    let mut segs: Vec<(XY, XY)> = Vec::new();
    let mut buckets: HashMap<usize, Vec<u32>> = HashMap::new();
    let major: Vec<&Line> = rivers.iter().filter(|r| r.major.unwrap_or(false) && r.line.len() >= 2).collect();
    // Линии рек в данных — куски с разрывами в несколько километров (протоки, смена названия): конец куска
    // соединяется с ближайшей точкой другого куска, иначе войска «просачиваются» через разрыв.
    let mut lines: Vec<Vec<LngLat>> = major.iter().map(|r| r.line.clone()).collect();
    for (k, r) in major.iter().enumerate() {
        let _ = &r.name;
        for end in [r.line[0], r.line[r.line.len() - 1]] {
            let e = self.proj.to_xy(end);
            let best = major.iter().enumerate().filter(|&(j, _)| j != k)
                .flat_map(|(_, o)| o.line.iter())
                .map(|p| (*p, self.proj.to_xy(*p).dist(e)))
                .filter(|&(_, dk)| dk > 1e-6)
                .min_by(|a, b| a.1.total_cmp(&b.1));
            if let Some((p, dk)) = best { if dk <= RIVER_GAP_KM { lines.push(vec![end, p]); } }
        }
    }
    for line in &lines {
        for w in line.windows(2) {
            let (a, b) = (self.proj.to_xy(w[0]), self.proj.to_xy(w[1]));
            let id = segs.len() as u32;
            segs.push((a, b));
            let (Some(ca), Some(cb)) = (self.cell_of(w[0]), self.cell_of(w[1])) else { continue };
            let (c0, r0, c1, r1) = (ca % self.cols, ca / self.cols, cb % self.cols, cb / self.cols);
            for row in r0.min(r1).saturating_sub(1)..=(r0.max(r1) + 1).min(self.rows - 1) {
                for col in c0.min(c1).saturating_sub(1)..=(c0.max(c1) + 1).min(self.cols - 1) {
                    buckets.entry(row * self.cols + col).or_default().push(id);
                }
            }
        }
    }
    for c in 0..self.cols * self.rows {
        let Some(list) = buckets.get(&c) else { continue };
        for d in 0..4 {
            let Some(nb) = self.neighbor(c, d) else { continue };
            let (a, b) = (self.centers[c], self.centers[nb]);
            if list.iter().any(|&s| { let (p, q) = segs[s as usize]; segments_cross(a, b, p, q) }) {
                self.river_cross[c] |= 1 << d;
                self.river_cross[nb] |= 1 << opposite(d);
                let mid = XY::new((a.x + b.x) / 2.0, (a.y + b.y) / 2.0);
                let best = self.bridges.iter().enumerate()
                    .map(|(i, br)| (i, br.pos.dist(mid)))
                    .filter(|&(_, dk)| dk <= BRIDGE_SNAP_KM)
                    .min_by(|x, y| x.1.total_cmp(&y.1));
                if let Some((i, _)) = best {
                    self.crossing_bridge.insert((c as u32, d as u8), i as u16);
                    self.crossing_bridge.insert((nb as u32, opposite(d) as u8), i as u16);
                }
            }
        }
    }
}

/// Полоса подготовленной обороны за линией `line_id` (сценарий, defenseZones): клетки своей стороны линии не дальше
/// `depth_km` получают уровень укрепления не ниже `level`. Сторона — к западу (`west`) или к востоку от линии.
pub fn mark_zone(&mut self, line_id: &str, depth_km: f64, level: u8, west: bool) -> usize {
    let Some(l) = self.lines.iter().find(|l| l.id == line_id).cloned() else { return 0 };
    let side = l.side.clone();
    let pts: Vec<XY> = l.line.iter().map(|p| self.proj.to_xy(*p)).collect();
    let mut n = 0;
    for c in 0..self.cols * self.rows {
        if self.fort[c] >= level { continue; }
        let p = self.centers[c];
        let mut best = (f64::INFINITY, XY::default());
        for w in pts.windows(2) {
            let (a, b) = (w[0], w[1]);
            let (vx, vy) = (b.x - a.x, b.y - a.y);
            let l2 = (vx * vx + vy * vy).max(1e-9);
            let u = (((p.x - a.x) * vx + (p.y - a.y) * vy) / l2).clamp(0.0, 1.0);
            let q = XY::new(a.x + vx * u, a.y + vy * u);
            let d = p.dist(q);
            if d < best.0 { best = (d, q); }
        }
        if best.0 > depth_km { continue; }
        if (p.x < best.1.x) != west { continue; }
        self.fort[c] = level;
        self.fort_side[c] = side.clone();
        n += 1;
    }
    n
}

pub fn neighbor(&self, c: usize, d: usize) -> Option<usize> {
    let (col, row) = ((c % self.cols) as i32 + DIRS[d].0, (c / self.cols) as i32 + DIRS[d].1);
    if col < 0 || row < 0 || col >= self.cols as i32 || row >= self.rows as i32 { None } else { Some(row as usize * self.cols + col as usize) }
}

fn decode_rle(rle: &str, n: usize, map: impl Fn(char) -> Option<u8>) -> Result<Vec<u8>, String> {
    let mut out = Vec::with_capacity(n);
    let mut k = 0usize;
    for ch in rle.chars() {
        if let Some(d) = ch.to_digit(10) { k = k * 10 + d as usize; continue; }
        let v = map(ch).ok_or_else(|| format!("растр: неизвестный код «{ch}»"))?;
        out.extend(std::iter::repeat(v).take(k.max(1)));
        k = 0;
    }
    if out.len() != n { return Err(format!("растр: {} клеток вместо {n}", out.len())); }
    Ok(out)
}

pub fn decode_terrain(rle: &str, n: usize) -> Result<Vec<u8>, String> {
    decode_rle(rle, n, |c| match c { 'o' => Some(0), 'f' => Some(1), 'm' => Some(2), 'u' => Some(3), 'h' => Some(4), 'w' => Some(5), _ => None })
}

fn civil_from_days(z: i64) -> (i64, i64, i64) {
    let z = z + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1460 + doe / 36_524 - doe / 146_096) / 365;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    (if m <= 2 { yoe + era * 400 + 1 } else { yoe + era * 400 }, m, d)
}

fn days_from_civil(y: i64, m: i64, d: i64) -> i64 {
    let y = if m <= 2 { y - 1 } else { y };
    let era = y.div_euclid(400);
    let yoe = y - era * 400;
    let mp = (m + 9) % 12;
    let doy = (153 * mp + 2) / 5 + d - 1;
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    era * 146_097 + doe - 719_468
}

/// Обратно: часы → «ГГГГ-ММ-ДДTЧЧ:00».
pub fn format_hours(h: i64) -> String {
    let (days, hour) = (h.div_euclid(24), h.rem_euclid(24));
    let (y, m, d) = civil_from_days(days);
    format!("{y:04}-{m:02}-{d:02}T{hour:02}:00")
}

/// Часы от 1970-01-01T00:00 (по гражданскому календарю, без часовых поясов).
pub fn parse_hours(s: &str) -> Option<i64> {
    let (date, time) = match s.split_once('T') { Some((d, t)) => (d, Some(t)), None => (s, None) };
    let mut it = date.split('-');
    let y: i64 = it.next()?.parse().ok()?;
    let m: i64 = it.next()?.parse().ok()?;
    let d: i64 = it.next()?.parse().ok()?;
    let h: i64 = match time { Some(t) => t.split(':').next()?.parse().ok()?, None => 0 };
    Some(days_from_civil(y, m, d) * 24 + h)
}

pub fn describe(sim: &Sim, meta: &crate::scenario::Meta, frames: Vec<Vec<Value>>) -> Value {
    let w = &sim.world;
    let divisions: Vec<Value> = w.divisions.iter().map(|d| json!({
        "id": d.id, "name": d.name, "side": d.side, "hq": w.hqs[d.hq as usize].id, "kind": d.params.kind,
        "mobility": d.params.mobility, "size": d.params.size, "quality": d.params.quality, "note": d.note,
    })).collect();
    let hqs: Vec<Value> = w.hqs.iter().map(|h| json!({
        "id": h.id, "name": h.name, "side": h.side, "echelon": h.echelon,
        "parent": h.parent.map(|p| w.hqs[p as usize].id.clone()),
    })).collect();
    let journal: Vec<Value> = sim.journal.iter().map(|e| json!({
        "tick": e.tick,
        "time": format_hours(sim.start_hour + e.tick as i64),
        "agent": if e.agent == u32::MAX { Value::Null } else { json!(w.divisions[e.agent as usize].id) },
        "text": e.text,
    })).collect();
    json!({
        "scenario": meta.id, "name": meta.name, "start": meta.start, "hours": meta.hours, "seed": sim.seed,
        "theatre": sim.theatre.id,
        "fields": FIELDS, "divisions": divisions, "hqs": hqs, "frames": frames, "journal": journal,
        "sources": sim.sources.iter().map(|s| format!("{s:?}").to_lowercase()).collect::<Vec<_>>(),
        "llm": sim.llm.as_ref().map(|c| {
            let mut v = c.describe();
            if let Some(&n) = sim.llm_par.get() { v["parallelUsed"] = json!(n); }
            if let Some(p) = sim.llm_probe.lock().ok().and_then(|p| p.clone()) { v["probe"] = p; }
            v
        }),
        "staff": sim.llm_log.lock().map(|l| l.clone()).unwrap_or_default(),
        // действующий приказ каждой дивизии на последний шаг (для докладов в игре): что, куда, от кого, когда
        "orders": w.divisions.iter().map(|d| d.order.as_ref().map(|o| json!({
            "kind": o.kind, "target": sim.theatre.proj.to_lnglat(o.target), "from": w.hqs[o.from as usize].id,
            "issued": o.issued, "arrives": o.arrives, "note": o.note,
        }))).collect::<Vec<_>>(),
    })
}

/// Кадр: по строке на дивизию.
pub fn frame(sim: &Sim) -> Vec<Value> {
    sim.world.divisions.iter().map(|d| {
        let p = sim.theatre.proj.to_lnglat(d.vars.pos);
        let r2 = |x: f64| (x * 100.0).round() / 100.0;
        json!([(p[0] * 1e4).round() / 1e4, (p[1] * 1e4).round() / 1e4, d.state.label(), d.vars.personnel.round(), d.vars.tanks.round(), d.vars.guns.round(),
               r2(d.vars.ammo), r2(d.vars.fuel), r2(d.vars.fatigue), r2(d.vars.cohesion), if sim.encircled(d, sim.world.tick) { d.cut_since.map_or(0, |s| sim.world.tick.saturating_sub(s)) } else { 0 }])
    }).collect()
}

/// Прогон `hours` шагов с записью кадров; возвращает ход в формате trace.json.
pub fn run(sim: &mut Sim, hours: u32, meta: &crate::scenario::Meta) -> Value {
    let mut frames = vec![frame(sim)];
    for _ in 0..hours { sim.step(); frames.push(frame(sim)); }
    describe(sim, meta, frames)
}

/// Событие журнала: что произошло и почему.
pub struct Event {
    pub tick: u32,
    /// Индекс дивизии; u32::MAX — не дивизия.
    pub agent: u32,
    pub text: String,
}

/// Решение дивизии на шаг (фаза 1).
struct Intent {
    state: Option<(State, String)>,
    /// Новый маршрут (Some(None) — сбросить).
    route: Option<Option<Route>>,
    /// Движение по маршруту за час.
    moved: Option<Moved>,
    /// Мост на пути в этом часе: (объект, позиция перед мостом, следующая клетка перед мостом).
    bridge: Option<(u32, XY, usize)>,
    /// Атакует дивизию противника.
    attacks: Option<u32>,
    /// Досягаемые дивизии противника по возрастанию расстояния (для распределения по участкам) и расстояния до них.
    options: Vec<(u32, f64)>,
    /// Отход от противника: куда.
    retreat_to: Option<XY>,
    activity: Option<Activity>,
}

struct Moved {
    pos: XY,
    /// Номер следующей клетки маршрута.
    next: usize,
    /// Часы марша.
    used_h: f64,
    crossing_left_h: f64,
    /// Переход маршрута, уже пройденный через реку (мост занят своей колонной или форсирование начато).
    cleared: usize,
}

/// Изменение по дате (поправки сценария из базы знаний, scenario::EditsIn): пополнение дивизии или переподчинение
/// дивизии или штаба. Исполняется на первом шаге не раньше `at`; пополнение не введённой дивизии — при вводе.
pub struct ScriptChange {
    pub at: u32,
    /// id дивизии или штаба.
    pub formation: String,
    pub kind: ChangeKind,
    pub personnel: f64,
    pub tanks: f64,
    pub guns: f64,
    /// Новый вышестоящий штаб (id) — для переподчинения.
    pub parent: Option<String>,
}

/// Артподготовка (огневой удар) сценария: штаб армии в момент `at` проводит её на полосе своих дивизий.
pub struct ScriptFire {
    pub at: u32,
    pub hq: u32,
    pub duration_min: f64,
    pub density_per_km: f64,
    pub note: String,
}

/// Приказ сценария: штаб отдаёт его в момент `at` (шаг), до дивизий он доходит с задержкой штаба.
pub struct ScriptOrder {
    pub at: u32,
    pub hq: u32,
    /// Кому: индексы дивизий.
    pub to: Vec<u32>,
    pub kind: OrderKind,
    /// Цель; None — на месте (район, где дивизия получит приказ).
    pub target: Option<XY>,
    pub forced: bool,
    pub note: String,
    /// Цель — соединение («наступать вместе с 3 гв. ТА»): его место в момент приказа (центр дивизий штаба или
    /// положение дивизии) со сдвигом `offset`, км; иначе — `target`.
    pub follow: Option<String>,
    pub offset: XY,
}

/// Событие сценария: отвод войск с первой позиции (доли войск по позициям у названных дивизий).
pub struct ScriptWithdraw {
    pub at: u32,
    pub to: Vec<u32>,
    pub positions: [f64; 3],
    pub note: String,
}

/// Полосы объединений на грубой сетке театра: метка объединения клетки (−1 — вне полос), объединение дивизий.
pub struct Sectors {
    /// Клеток театра в клетке сетки по каждой оси; столбцов сетки.
    pub step: usize,
    pub cols: usize,
    pub label: Vec<i16>,
    /// Объединение (метка) дивизии по её индексу.
    pub group: std::collections::HashMap<u32, i16>,
    /// Насколько «дороже» клетка чужой полосы (как sectorPrefer: 1 + foreign).
    pub foreign: f64,
}

pub struct Sim {
    pub theatre: Arc<Theatre>,
    pub rules: Rules,
    pub seed: u64,
    /// Начало сценария, часы от 1970-01-01.
    pub start_hour: i64,
    pub world: World,
    pub script: Vec<ScriptOrder>,
    pub fires: Vec<ScriptFire>,
    pub withdrawals: Vec<ScriptWithdraw>,
    /// Изменения по датам, ещё не исполненные (по возрастанию часа).
    pub changes: Vec<ScriptChange>,
    /// Источник решений штабов: [советская сторона, немецкая].
    pub sources: [crate::staff::Source; 2],
    /// Направления «в тыл» дивизий по исходной обстановке (для штабов по доктрине).
    pub rear_dir: std::sync::OnceLock<Vec<(XY, f64)>>,
    /// Языковая модель для штабов на модели.
    pub llm: Option<crate::llm::LlmConfig>,
    /// Запросы к модели и ответы (для разбора и записи прогона).
    pub llm_log: std::sync::Mutex<Vec<serde_json::Value>>,
    /// Число одновременных запросов, определённое замером (если в настройках «авто»), и сам замер.
    pub llm_par: std::sync::OnceLock<usize>,
    pub llm_probe: std::sync::Mutex<Option<serde_json::Value>>,
    /// Советские штабы по доктрине: замысел и построение армий (staff_su.rs).
    pub su_staff: std::sync::Mutex<crate::staff_su::SuStaff>,
    /// Сообщения о ходе долгих решений (запрос к модели) — для окна приложения.
    pub on_progress: Option<Box<dyn Fn(String) + Send + Sync>>,
    /// Ход ответа модели-штаба по мере прихода (размышления и ответ) — для окна приложения.
    pub on_stream: Option<Box<dyn Fn(serde_json::Value) + Send + Sync>>,
    pub journal: Vec<Event>,
    /// Снимки по шагам для перемотки (если включено).
    pub history: Option<Vec<World>>,
    /// Распоряжения штаба игрока (игра): подвоз, переправы, подрыв мостов, полосы армий.
    pub staff: StaffFx,
}

fn apply(&self, w: &mut World, journal: &mut Vec<Event>) {
    let r = &self.rules;
    let tick = w.tick;
    let day_start = self.hour().rem_euclid(24) == 6;
    let in_battle: Vec<bool> = w.divisions.iter().map(|d| matches!(d.state, State::Attack(_))).collect();
    for (i, d) in w.divisions.iter_mut().enumerate() {
        if d.state.out() { continue; }
        let sr = r.side(d.side);
        // окружённым подвоза нет; гарнизон крепости живёт со складов (на 30 суток боя — дольше сценария)
        let supplied = d.params.kind == "garrison" || !d.cut_since.is_some_and(|s| tick.saturating_sub(s) as f64 >= r.pocket.encircle_hours);
        if supplied {
            // распоряжения тыла (игра): база далеко — меньше, приоритет — больше; без распоряжений — 1
            let k = self.staff.supply.get(&(i as u32)).copied().unwrap_or(1.0);
            d.vars.ammo = (d.vars.ammo + k * sr.ammo_per_day / 24.0).min(sr.max_ammo);
            if d.params.mobility != Mobility::Foot { d.vars.fuel = (d.vars.fuel + k * sr.fuel_per_day / 24.0).min(sr.max_fuel); }
        }
        if !in_battle[i] { d.vars.cohesion = (d.vars.cohesion + r.cohesion_recover).min(1.0); }
        if day_start { d.vars.march_h_today = 0.0; }
        if d.vars.personnel < r.destroyed_personnel {
            journal.push(Event { tick, agent: i as u32, text: format!("{} → {}: численность меньше {} человек — дивизия рассеяна", d.state.label(), State::Destroyed.label(), r.destroyed_personnel) });
            d.state = State::Destroyed;
            d.state_since = tick;
        }
    }
    self.apply_remnants(w, journal);
    // территория: клетка дивизии и соседние становятся её стороны
    let t = &*self.theatre;
    for d in w.divisions.iter().filter(|d| !d.state.out()) {
        let Some(c) = t.cell_of_xy(d.vars.pos) else { continue };
        let code = side_code(d.side);
        if let Some(x) = w.control.get_mut(c) { *x = code; }
        for k in 0..8 { if let Some(nb) = t.neighbor(c, k) { w.control[nb] = code; } }
    }
    self.apply_pockets(w, journal);
    self.apply_breakout_losses(w);
    // потери в соприкосновении без боя: огонь, мины, поиски (contact_loss_day; 0 — нет)
    if r.combat.contact_loss_day > 0.0 {
        let reach = r.contact_km;
        let hit: Vec<usize> = (0..w.divisions.len()).filter(|&i| {
            let d = &w.divisions[i];
            !d.state.out() && d.state != State::Remnant && !w.engaged.get(i).copied().unwrap_or(false)
                && w.divisions.iter().any(|e| e.side != d.side && !e.state.out() && e.state != State::Remnant && e.vars.pos.dist(d.vars.pos) <= reach)
        }).collect();
        for i in hit { lose(&mut w.divisions[i], r.combat.contact_loss_day / 24.0, 1.0, &r.combat); }
    }
    // объекты: чей район — по ближайшей дивизии в 2 км (параллельно, только чтение)
    let index = Index::build(w.divisions.iter().enumerate().filter(|(_, d)| !d.state.out()).map(|(i, d)| (i as u32, d.vars.pos)), 5.0);
    let divs = &w.divisions;
    let control: Vec<Option<Side>> = w.objects.par_iter().map(|o| {
        index.near(o.pos, 2.0).into_iter()
            .map(|j| (j, divs[j as usize].vars.pos.dist(o.pos)))
            .filter(|&(_, k)| k <= 2.0)
            .min_by(|a, b| a.1.total_cmp(&b.1).then(a.0.cmp(&b.0)))
            .map(|(j, _)| divs[j as usize].side)
            .or(o.control)
    }).collect();
    for (o, c) in w.objects.iter_mut().zip(control) { o.control = c; }
}

/// Изменения по датам на шаге `tick`. Пополнение — к текущим силам и к начальным (personnel0, strength0 — на силу
/// прибавки), чтобы доли от начальных оставались осмысленными; не введённой дивизии — откладывается до ввода.
/// Переподчинение дивизии меняет её штаб, штаба — его вышестоящий штаб; новый штаб должен существовать, быть своей
/// стороны, не совпадать с переподчиняемым и не быть его подчинённым (цикл). Иначе — запись «изменение пропущено».
fn apply_changes(&mut self, w: &mut World, tick: u32, journal: &mut Vec<Event>) {
    if self.changes.first().map_or(true, |c| c.at > tick) { return; }
    let mut keep = Vec::new();
    for c in std::mem::take(&mut self.changes) {
        if c.at > tick { keep.push(c); continue; }
        let div = w.divisions.iter().position(|d| d.id == c.formation);
        let hq = w.hqs.iter().position(|h| h.id == c.formation);
        let agent = div.map_or(u32::MAX, |i| i as u32);
        let mut skip = |why: String| journal.push(Event { tick, agent, text: format!("изменение пропущено: {why}") });
        match c.kind {
            ChangeKind::Reinforce => {
                let Some(i) = div else { skip(format!("пополнение {} — нет такой дивизии", c.formation)); continue };
                let d = &mut w.divisions[i];
                if d.state == State::Pending { keep.push(c); continue; }
                if matches!(d.state, State::Destroyed | State::Merged) { skip(format!("пополнение «{}» — дивизия выбыла, пополнять нечего", d.name)); continue; }
                let (p, t, g) = (c.personnel.max(0.0), c.tanks.max(0.0), c.guns.max(0.0));
                let (wp, wt, wg) = self.rules.side(d.side).weights;
                d.vars.personnel += p;
                d.vars.tanks += t;
                d.vars.guns += g;
                d.vars.personnel0 += p;
                d.vars.strength0 += (p / 1000.0 * wp + t * wt + g * wg) * d.params.quality;
                let mut text = format!("пополнение +{p:.0} чел.");
                if t > 0.0 { text += &format!(", танков +{t:.0}"); }
                if g > 0.0 { text += &format!(", орудий +{g:.0}"); }
                journal.push(Event { tick, agent, text });
            }
            ChangeKind::Resubordinate => {
                let Some(pid) = c.parent.as_deref() else { skip(format!("переподчинение {} — не указан новый штаб", c.formation)); continue };
                if pid == c.formation { skip(format!("переподчинение {} самому себе", c.formation)); continue; }
                let Some(p) = w.hqs.iter().position(|h| h.id == pid) else { skip(format!("переподчинение {} — нет штаба {pid}", c.formation)); continue };
                let (side, name) = (w.hqs[p].side, w.hqs[p].name.clone());
                if let Some(i) = div {
                    if w.divisions[i].side != side { skip(format!("переподчинение {} — штаб {pid} другой стороны", c.formation)); continue; }
                    w.divisions[i].hq = p as u32;
                    journal.push(Event { tick, agent, text: format!("переподчинение → {name}") });
                } else if let Some(h) = hq {
                    if w.hqs[h].side != side { skip(format!("переподчинение {} — штаб {pid} другой стороны", c.formation)); continue; }
                    // новый вышестоящий — в подчинении переподчиняемого: цикл
                    let mut up = Some(p);
                    let mut cycle = false;
                    for _ in 0..=w.hqs.len() {
                        match up { Some(x) if x == h => { cycle = true; break } Some(x) => up = w.hqs[x].parent.map(|q| q as usize), None => break }
                    }
                    if cycle { skip(format!("{pid} — в подчинении самого {}: переподчинение образовало бы цикл", c.formation)); continue; }
                    w.hqs[h].parent = Some(p as u32);
                    journal.push(Event { tick, agent: u32::MAX, text: format!("{}: переподчинение → {name}", w.hqs[h].name) });
                } else {
                    skip(format!("переподчинение {} — нет такой дивизии или штаба", c.formation));
                }
            }
        }
    }
    self.changes = keep;
}

/// Артподготовка: по каждой дивизии противника на полосе армии (в пределах досягаемости её дивизий) потери —
/// сумма по позициям «доля войск × потери от огня по позиции» (Радзиевский), в доле от нормы по плотности и
/// длительности; организованность падает так же, как в бою. Артподготовки одного часа разбираются вместе:
/// полосу дивизии противника обрабатывает одна армия — та, чьи дивизии к ней ближе всего.
fn apply_fires(&self, w: &mut World, tick: u32, journal: &mut Vec<Event>) {
    let a = &self.rules.combat.artillery;
    let now: Vec<&ScriptFire> = self.fires.iter().filter(|f| f.at == tick).collect();
    if now.is_empty() { return; }
    let reach = self.rules.contact_km + a.depth_km;
    // цель → (огонь, расстояние до ближайшей дивизии стреляющей армии)
    let mut pick: BTreeMap<usize, (usize, f64)> = BTreeMap::new();
    for (fi, f) in now.iter().enumerate() {
        let own: Vec<usize> = (0..w.divisions.len()).filter(|&i| w.divisions[i].hq == f.hq && !w.divisions[i].state.out()).collect();
        let Some(&first) = own.first() else { continue };
        let side = w.divisions[first].side;
        for j in 0..w.divisions.len() {
            let e = &w.divisions[j];
            if e.side == side || e.state.out() { continue; }
            let dmin = own.iter().map(|&i| w.divisions[i].vars.pos.dist(e.vars.pos)).fold(f64::INFINITY, f64::min);
            if dmin > reach { continue; }
            let better = pick.get(&j).map_or(true, |&(_, d0)| dmin < d0 - 1e-9);
            if better { pick.insert(j, (fi, dmin)); }
        }
    }
    let mut parts: Vec<Vec<String>> = vec![Vec::new(); now.len()];
    for (&j, &(fi, _)) in &pick {
        let f = now[fi];
        let k = (f.density_per_km / a.norm_density).min(1.0) * (f.duration_min / a.norm_duration_min).min(1.0);
        let d = &mut w.divisions[j];
        let pos = d.vars.positions.unwrap_or(a.positions);
        let loss = (0..3).map(|p| pos[p] * a.loss_by_position[p]).sum::<f64>() * k;
        lose(d, loss, a.cohesion_factor, &self.rules.combat);
        parts[fi].push(format!("{} — {:.1} %", d.name, loss * 100.0));
        journal.push(Event { tick, agent: j as u32, text: format!("под артподготовкой ({}, {:.0} ств./км, {:.0} мин): потери {:.1} %{}", w.hqs[f.hq as usize].name, f.density_per_km, f.duration_min, loss * 100.0,
            if d.vars.positions.is_some() { ", первая позиция отведена" } else { "" }) });
    }
    for (fi, f) in now.iter().enumerate() {
        let k = (f.density_per_km / a.norm_density).min(1.0) * (f.duration_min / a.norm_duration_min).min(1.0);
        let hq = w.hqs[f.hq as usize].name.clone();
        journal.push(Event { tick, agent: u32::MAX, text: format!("артподготовка: {hq}, {:.0} ств./км, {:.0} мин (доля нормы {:.2}); {}. {}", f.density_per_km, f.duration_min, k,
            if parts[fi].is_empty() { "противника на полосе нет".to_string() } else { parts[fi].join(", ") }, f.note) });
    }
}

/// Остатки разгромленных дивизий (правила — agents-v0.json, раздел remnants; источники —
/// docs/sources/division-remnants-1945.json). Немецкая дивизия ниже доли исходной численности разгромлена: выходит
/// из боя в тыл, а через сутки остатки сводятся в ближайшую свою дивизию корпуса (иначе армии) — люди и часть
/// техники переходят к ней, агент выбывает. Советская дивизия ниже порога численности выводится в резерв армии и
/// в пределах операции не сводится.
fn apply_remnants(&self, w: &mut World, journal: &mut Vec<Event>) {
    let rr = &self.rules.remnants;
    let tick = w.tick;
    for i in 0..w.divisions.len() {
        let d = &w.divisions[i];
        if d.state.out() || d.state == State::Remnant { continue; }
        let share = d.vars.personnel / d.vars.personnel0.max(1.0);
        let why = match d.side {
            Side::De if share < rr.de_share => format!("численность {:.0} % исходной — дивизия разгромлена, остатки выходят из боя", 100.0 * share),
            // порог — по стрелковым дивизиям (источники); бригады и корпуса меньше его с начала операции
            Side::Su if d.params.kind == "sd" && d.vars.personnel < rr.su_personnel => format!("численность меньше {:.0} человек — выводится из боя в резерв армии", rr.su_personnel),
            _ => continue,
        };
        let target = self.behind(w, i, rr.rear_km);
        let d = &mut w.divisions[i];
        journal.push(Event { tick, agent: i as u32, text: format!("{} → {}: {why}", d.state.label(), State::Remnant.label()) });
        d.state = State::Remnant;
        d.state_since = tick;
        d.order = Some(Order { kind: OrderKind::Withdraw, target, forced: true, issued: tick, arrives: tick, from: d.hq, note: "выход остатков из боя".into() });
        d.route = None;
    }
    // сведение немецких остатков в соседнюю дивизию
    for i in 0..w.divisions.len() {
        let d = &w.divisions[i];
        if d.side != Side::De || d.state != State::Remnant || ((tick - d.state_since) as f64) < rr.de_consolidate_hours { continue; }
        let army = |h: u32| { let mut k = h as usize; while w.hqs[k].echelon == Echelon::Corps { match w.hqs[k].parent { Some(p) => k = p as usize, None => break } } k };
        let pick = |same: &dyn Fn(&Division) -> bool| w.divisions.iter().enumerate()
            .filter(|(j, e)| *j != i && e.side == d.side && !e.state.out() && e.state != State::Remnant && same(e))
            .map(|(j, e)| (j, e.vars.pos.dist(d.vars.pos)))
            .filter(|x| x.1 <= rr.de_search_km)
            .min_by(|a, b| a.1.total_cmp(&b.1).then(a.0.cmp(&b.0)));
        let Some((j, _)) = pick(&|e| e.hq == d.hq).or_else(|| pick(&|e| army(e.hq) == army(d.hq))) else { continue };
        let (p, t, g) = (d.vars.personnel * rr.de_personnel_share, d.vars.tanks * rr.de_heavy_share, d.vars.guns * rr.de_heavy_share);
        let (from, into) = (d.name.clone(), w.divisions[j].name.clone());
        let e = &mut w.divisions[j];
        e.vars.personnel += p;
        e.vars.tanks += t;
        e.vars.guns += g;
        journal.push(Event { tick, agent: j as u32, text: format!("приняла остатки «{from}»: {:.0} человек, танков {:.0}, орудий {:.0}", p, t, g) });
        let d = &mut w.divisions[i];
        journal.push(Event { tick, agent: i as u32, text: format!("{} → {}: остатки сведены в «{into}» ({:.0} человек, танков {:.0}, орудий {:.0}; остальное — отставшие и брошенная техника)", d.state.label(), State::Merged.label(), p, t, g) });
        d.note = if d.note.is_empty() { format!("сведена в «{into}»") } else { format!("{}; сведена в «{into}»", d.note) };
        d.state = State::Merged;
        d.state_since = tick;
        d.vars.personnel = 0.0;
        d.vars.tanks = 0.0;
        d.vars.guns = 0.0;
        d.order = None;
    }
}

fn apply_withdrawals(&self, w: &mut World, tick: u32, journal: &mut Vec<Event>) {
    for ev in self.withdrawals.iter().filter(|e| e.at == tick) {
        for &d in &ev.to {
            let div = &mut w.divisions[d as usize];
            div.vars.positions = Some(ev.positions);
            journal.push(Event { tick, agent: d, text: format!("войска отведены с первой позиции: на позициях {:.0} / {:.0} / {:.0} % — {}", ev.positions[0] * 100.0, ev.positions[1] * 100.0, ev.positions[2] * 100.0, ev.note) });
        }
    }
}

fn bridge_open(&self, w: &World, b: u16) -> bool {
    w.objects.iter().find(|o| o.bridge == Some(b)).map_or(true, |o| o.intact)
}

  fn decide(&self, w: &World, index: &Index, i: u32) -> Intent {
      let d = &w.divisions[i as usize];
      let mut out = Intent::default();
      if d.state.out() { return out; }
      let r = &self.rules;
      let pos = d.vars.pos;
      // ближайший противник в пределах соприкосновения
      let reach = r.contact_km + r.size(&r.frontage_km, d.params.size) / 2.0;
      let mut options: Vec<(u32, f64)> = index.near(pos, reach).into_iter()
