/// Множитель выбора пути для дивизии `i`: в полосе соседа — 1 + foreign.
fn sector_cost(&self, i: usize, cell: usize) -> f64 {
    let t = &*self.theatre;
    self.staff.sectors.iter().map(|s| {
        let Some(&g) = s.group.get(&(i as u32)) else { return 1.0 };
        let k = (cell / t.cols / s.step) * s.cols + (cell % t.cols) / s.step;
        match s.label.get(k) { Some(&l) if l >= 0 && l != g => 1.0 + s.foreign, _ => 1.0 }
    }).product()
}

  /// Один шаг (1 час).
  pub fn step(&mut self) {
      if let Some(h) = self.history.as_mut() { h.push(self.world.clone()); }
      let tick = self.world.tick;
      // направления «в тыл» — по исходной обстановке (штабы и выход остатков из боя)
      if tick == 0 { let _ = self.fronts(&self.world); }
      let mut next = self.world.clone();
      let mut journal = Vec::new();
      // ввод в операцию по времени сценария
      for (i, d) in next.divisions.iter_mut().enumerate() {
          if d.state == State::Pending && tick >= d.enter {
              journal.push(Event { tick, agent: i as u32, text: format!("{} → {}: введена в операцию", State::Pending.label(), State::Reserve.label()) });
              d.state = State::Reserve;
              d.state_since = tick;
          }
      }
      // изменения по датам: пополнения и переподчинение (после ввода — введённая в этом часе уже пополняется)
      self.apply_changes(&mut next, tick, &mut journal);

      // 0. Приказы: штабы отдают по сценарию или решают по доктрине (staff.rs); до дивизий приказы доходят с задержкой
      // своего уровня. У стороны со штабами по доктрине приказы сценария не действуют.
      let mut due: Vec<ScriptOrder> = Vec::new();
      while let Some(o) = self.script.first() {
          if o.at > tick { break; }
          let o = self.script.remove(0);
          let side = next.hqs[o.hq as usize].side;
          match self.sources[crate::staff::side_idx(side)] {
              crate::staff::Source::Script => due.push(o),
              // советские штабы по доктрине: задача сценария — замысел армии (staff_su.rs)
              _ if side == Side::Su => self.su_plan(&next, &o, &mut due),
              _ => {}
          }
      }
      let (doc_orders, doc_journal) = self.doctrine_orders(&next, tick);
      due.extend(doc_orders);
      journal.extend(doc_journal);
      for o in due {
          let hq = &next.hqs[o.hq as usize];
          let sr = self.rules.side(hq.side);
          let delay = match hq.echelon { Echelon::Front => sr.delay_army, Echelon::Army => sr.delay_corps, Echelon::Corps => sr.delay_division };
          let follow_at = o.follow.as_deref().and_then(|f| self.place_of(&next, f));
          for &d in &o.to {
              let target = match follow_at {
                  Some(c) => XY::new(c.x + o.offset.x, c.y + o.offset.y),
                  None => o.target.unwrap_or(next.divisions[d as usize].vars.pos),
              };
              // приказы на начало сценария отданы накануне и уже дошли до дивизий (кроме атаки — у неё свой час «Ч»)
              let arrives = if o.at == 0 && o.kind != OrderKind::Attack && self.rules.start_orders_delivered { 0 } else { o.at + delay.round() as u32 };
              let order = Order { kind: o.kind, target, forced: o.forced, issued: o.at, arrives, from: o.hq, note: o.note.clone() };
              next.in_transit.push((d, order));
          }
      }
      let mut arrived = Vec::new();
      next.in_transit.retain(|(d, o)| if o.arrives <= tick { arrived.push((*d, o.clone())); false } else { true });
      for (d, o) in arrived {
          let div = &mut next.divisions[d as usize];
          // не введённая получает приказ заранее — выполнит после ввода
          if (div.state.out() && div.state != State::Pending) || div.state == State::Remnant { continue; }
          journal.push(Event { tick, agent: d, text: format!("получен приказ «{}» от штаба «{}»: {}", o.kind.label(), next.hqs[o.from as usize].name, o.note) });
          div.order = Some(o);
          div.route = None;
      }
      // отвод с первой позиции и артподготовка (события сценария)
      self.apply_withdrawals(&mut next, tick, &mut journal);
      self.apply_fires(&mut next, tick, &mut journal);
      // мосты по данным театра (наведение, подрыв)
      let hour = self.hour();
      for ob in next.objects.iter_mut() {
          if let Some(b) = ob.bridge { ob.intact = self.theatre.bridges[b as usize].open_at(hour) && !self.staff.demolished.get(&b).is_some_and(|&from| tick >= from); }
      }

      // 1. Решения — параллельно по снимку `next` (после доставки приказов).
      let index = Index::build(next.divisions.iter().enumerate().filter(|(_, d)| !d.state.out()).map(|(i, d)| (i as u32, d.vars.pos)), 5.0);
      let snap = &next;
      let intents: Vec<Intent> = (0..snap.divisions.len()).into_par_iter().map(|i| self.decide(snap, &index, i as u32)).collect();

      // 2. Разрешение по порядку: мосты, бои.
      self.resolve(&mut next, intents, &mut journal);

      // 3. Применение: расход, подвоз, усталость, объекты.
      self.apply(&mut next, &mut journal);
// … строки 350–354

/// Боевая сила дивизии (часть II описания, раздел 19.1).
pub fn strength(&self, d: &Division) -> f64 {
    let r = &self.rules;
    let (wp, wt, wg) = r.side(d.side).weights;
    let v = &d.vars;
    let base = v.personnel / 1000.0 * wp + v.tanks * wt + v.guns * wg;
    let ammo = if v.ammo >= 0.5 { 1.0 } else { r.ammo_short + (1.0 - r.ammo_short) * (v.ammo / 0.5).max(0.0) };
    let fuel = if v.fuel <= 0.0 && d.params.mobility != Mobility::Foot { r.fuel_out } else { 1.0 };
    base * d.params.quality * ammo * fuel * (1.0 - v.fatigue * r.fatigue_effect)
}

/// Распоряжения штаба, которые ядро исполняет в расчёте (игра; их проверяет и ведёт штаб вне ядра).
pub struct StaffFx {
    /// Множитель подвоза по дивизиям (индекс; нет — 1): база далеко или подвоз не доходит — меньше, приоритет — больше.
    pub supply: std::collections::HashMap<u32, f64>,
    /// Наведённые переправы: место, сторона, с какого шага — переход реки рядом (до PONTOON_KM) без задержки форсирования.
    pub pontoons: Vec<(XY, Side, u32)>,
    /// Подорванные мосты театра: индекс моста → с какого шага.
    pub demolished: std::collections::HashMap<u16, u32>,
    /// Полосы объединений (фронтов, армий): клетка в полосе соседа «дороже» при выборе пути (время движения то же);
    /// множители уровней перемножаются.
    pub sectors: Vec<Sectors>,
}

/// Снимок мира на шаг.
pub struct World {
    pub tick: u32,
    pub divisions: Vec<Division>,
    pub hqs: Vec<Hq>,
    pub objects: Vec<Object>,
    /// Приказы в пути: (дивизия, приказ).
    pub in_transit: Vec<(u32, Order)>,
    /// Чья клетка театра: 0 — ничья, 1 — советская, 2 — немецкая. В начале — по ближайшей дивизии (не дальше
    /// CONTROL_INIT_KM), дальше — клетки, где побывали войска.
    pub control: Vec<u8>,
    /// Клетки, до которых доходит путь к своим: [советская сторона, немецкая] (pocket.rs).
    pub reach: [Vec<bool>; 2],
    /// Клетки ближе pocket.hold_km к войскам стороны — её территорию там держат: [советская, немецкая].
    pub held: [Vec<bool>; 2],
    /// Дивизия вела бой в этом часе (наступала или оборонялась).
    pub engaged: Vec<bool>,
}

/// Начальная разметка территории: клетка принадлежит стороне ближайшей дивизии (не дальше CONTROL_INIT_KM).
pub fn init_control(&mut self, t: &Theatre) {
    let pts: Vec<(XY, u8)> = self.divisions.iter().map(|d| (d.vars.pos, side_code(d.side))).collect();
    self.control = t.centers.par_iter().map(|c| {
        pts.iter().map(|&(p, s)| (p.dist(*c), s)).filter(|&(k, _)| k <= CONTROL_INIT_KM)
            .min_by(|a, b| a.0.total_cmp(&b.0)).map_or(0, |(_, s)| s)
    }).collect();
}

pub(crate) fn lose(d: &mut Division, frac: f64, cohesion_factor: f64, c: &crate::rules::Combat) {
    d.vars.personnel *= 1.0 - frac;
    d.vars.tanks *= 1.0 - (frac * c.tank_loss_factor).min(1.0);
    d.vars.guns *= 1.0 - (frac * c.gun_loss_factor).min(1.0);
    d.vars.cohesion = (d.vars.cohesion - frac * cohesion_factor).max(0.0);
}

export interface AgentsScore {
  within: number; n: number; medianExcessKm: number;
  eventsHit: number; eventsTotal: number;
  events: { id: string; title: string; days: number | null }[];
  /** По объединениям (армиям и корпусам по подчинению дивизий): доля в допуске и число положений. */
  byGroup: { id: string; within: number; n: number }[];
  /** Сверка численности и потерь с документами (есть, когда в истории есть контрольные точки). */
  strength?: { n: number; within: number };
  /** Итог для калибровки: положения и события поровну (0…1); при ≥ 10 контрольных точках — на 25% сверка численности. */
  score: number;
}

export function agentsScore(base: SimContext, trace: AgentTrace, history: AgentHistory, baseHistory: History | null, toleranceKm = 10, stepHours = 6): AgentsScore {
  const { ctx, run } = agentsToRun(base, trace, stepHours);
  const h = agentsHistory(history, baseHistory);
  const devs = compareWithHistory(ctx, run, h);
  const s = summarize(devs, toleranceKm);
  const ev = checkEvents(ctx, run, h);
  const hit = ev.filter((e) => e.days != null && Math.abs(e.days) <= 2).length;
  // объединение дивизии — армия над её штабом (корпус → армия), без армии — сам штаб
  const hqs = new Map(trace.hqs.map((x) => [x.id, x]));
  const armyOf = (id: string) => { for (let x = hqs.get(id), n = 0; x && n < 6; x = x.parent ? hqs.get(x.parent) : undefined, n++) if (x.echelon === 'army') return x.id; return id; };
  const hq = new Map(trace.divisions.map((d) => [d.id, armyOf(d.hq)]));
  const name = new Map(trace.hqs.map((x) => [x.id, x.name]));
  const groups = new Map<string, { ok: number; n: number }>();
  for (const d of devs) {
    const g = hq.get(d.formation);
    if (!g) continue;
    const x = groups.get(g) ?? { ok: 0, n: 0 };
    x.n++; if (d.excessKm <= toleranceKm) x.ok++;
    groups.set(g, x);
  }
  const st = compareStrength(ctx, run, h);
  const posEv = (s.within + (ev.length ? hit / ev.length : s.within)) / 2;
  return {
    within: s.within, n: s.n, medianExcessKm: s.medianExcessKm, eventsHit: hit, eventsTotal: ev.length,
    events: ev.map((e) => ({ id: e.id, title: e.title, days: e.days })),
    byGroup: [...groups].map(([id, x]) => ({ id: name.get(id) ?? id, within: +(x.ok / x.n).toFixed(2), n: x.n })).sort((a, b) => b.n - a.n),
    ...(st.n > 0 ? { strength: { n: st.n, within: st.within } } : {}),
    score: +(st.n >= STRENGTH_MIN_POINTS ? posEv * (1 - STRENGTH_WEIGHT) + st.within * STRENGTH_WEIGHT : posEv).toFixed(3),
  };
}

/** Ход агентной модели по сторонам и в расчёте этой модели. */
export interface AgentHistory {
  divisions: { formation: string; time: string; at: LngLat; approxKm: number; reliability: string; set?: string; source?: string }[];
  /** Положения армий (штабов) по документам — для оперативного масштаба карты; в сверку не входят. */
  armies?: { formation: string; time: string; at: LngLat; approxKm: number; reliability?: string | null; source?: string }[];
  events?: History['events'];
}

/** Ход агентной модели (trace::describe). */
export interface AgentTrace {
  scenario: string;
  name: string;
  start: string;
  hours: number;
  seed: number;
  fields: string[];
  divisions: { id: string; name: string; side: string; hq: string; kind: string; mobility: string; size: string; quality: number; note?: string }[];
  hqs: { id: string; name: string; side: string; echelon: string; parent: string | null }[];
  /** По кадру на час (и начальный), в кадре — строка на дивизию в порядке divisions, поля — fields. */
  frames: unknown[][][];
  journal: { tick: number; time: string; agent: string | null; text: string }[];
  sources?: string[];
  /** Действующий приказ каждой дивизии на последний кадр (порядок divisions); null — без приказа. */
  orders?: ({ kind: AgentOrderKind; target: LngLat; from: string; issued: number; arrives: number; note: string } | null)[];
}

export function agentKindOf(task: Task): AgentOrderKind {
  switch (task) {
    case 'attack': case 'counterattack': case 'breakout': return 'attack';
    case 'defend': case 'delay': return 'defend';
    case 'hold': return 'hold';
    case 'withdraw': return 'withdraw';
    default: return 'move';
  }
}

/** История для сверки и «призраков»: положения дивизий и события агентной модели, линии фронта — из истории сценария. */
export function agentsHistory(h: AgentHistory, base?: History | null): History {
  return {
    scenario: base?.scenario ?? '',
    // положения дивизий и армий; сверка (compareWithHistory) — только по действующим (дивизиям): армий в снимках нет
    positions: [
      ...h.divisions.map((p) => ({ formation: p.formation, time: p.time, at: p.at, approxKm: p.approxKm, place: '', reliability: p.reliability, source: p.source ?? p.set ?? '' })),
      ...(h.armies ?? []).map((p) => ({ formation: p.formation, time: p.time, at: p.at, approxKm: p.approxKm, place: '', reliability: p.reliability ?? 'C', source: p.source ?? '' })),
    ],
    frontline: base?.frontline ?? [],
    events: h.events ?? [],
    // сверка численности и потерь с документами — те же контрольные точки, что у базовой истории
    ...(base?.checkpoints?.length ? { checkpoints: base.checkpoints } : {}),
  };
}

/**
 * Состояние на час h хода агентной модели для контекста из agentsToRun: формирования с положением, численностью,
 * запасами и положением дел на этот час (для докладов, разведки и игры). Не введённые — с enterAt на час ввода,
 * выбывшие (небоеспособны, сведены) — уничтожены.
 */
export function agentsStateAt(ctx: SimContext, t: AgentTrace, h: number): SimState {
  const F = (k: string) => t.fields.indexOf(k);
  const [iLng, iLat, iState, iPers, iTanks, iGuns, iAmmo, iFuel, iFat, iEnc] = ['lng', 'lat', 'state', 'personnel', 'tanks', 'guns', 'ammo', 'fuel', 'fatigue', 'encircled'].map(F);
  const hh = Math.max(0, Math.min(t.frames.length - 1, Math.round(h)));
  const time = (x: number) => addHours(t.start, x);
  const row = t.frames[hh], init = t.frames[0];
  const idx = new Map(t.divisions.map((d, k) => [d.id, k]));
  const pending = (k: number, x: number) => String(t.frames[x][k][iState]).startsWith('не введена');
  // в состоянии — только действующие соединения (дивизии); штабы — узлы подчинения сценария, как у нынешней модели
  const formations: Formation[] = ctx.scenario.formations.filter((f) => idx.has(f.id)).map((f) => {
    const k = idx.get(f.id)!;
    // приказ — только на последний кадр (его знает ядро); игрок отдаёт приказы с note «приказ игрока»
    const o = hh === t.frames.length - 1 ? t.orders?.[k] ?? null : null;
    const order: Order | null = o ? { id: `agents:${f.id}@${o.issued}`, formation: f.id, task: AGENT_TASK[o.kind] ?? 'defend', target: o.target, issuedAt: time(o.issued), source: o.note.includes('игрок') ? 'human' : 'script', note: o.note.replace(/\s*\[[^\]]*@[^\]]*\]\s*$/, '') || undefined } : null;
    const base = { id: f.id, name: f.name, side: f.side, echelon: f.echelon, parent: f.parent ?? null, type: f.type ?? '', dugInHours: 0, order, route: null };
    const r = row[k], r0 = init[k];
    const st = String(r[iState]);
    const p = postureOf(st);
    // ввод: первый час, когда дивизия уже не «не введена» (в пределах хода; дальше — неизвестно, после конца хода)
    let enterAt: string | null = null;
    if (pending(k, 0)) {
      let x = 0;
      while (x < t.frames.length && pending(k, x)) x++;
      enterAt = time(x < t.frames.length ? x : t.frames.length + 24 * 365);
    }
    return {
      ...base, position: [r[iLng] as number, r[iLat] as number] as LngLat,
      personnel: r[iPers] as number, tanks: r[iTanks] as number, guns: r[iGuns] as number,
      initial: { personnel: r0[iPers] as number, tanks: r0[iTanks] as number, guns: r0[iGuns] as number },
      ammo: r[iAmmo] as number, fuel: r[iFuel] as number, fatigue: r[iFat] as number,
      posture: p && p !== 'destroyed' ? p : 'defend',
      destroyed: p === 'destroyed' || st.startsWith('сведена'), enterAt,
      ...((r[iEnc] as number) > 0 ? { cutOff: true, cutHours: r[iEnc] as number } : {}),
    } as Formation;
  });
  return { scenario: ctx.scenario.id, time: time(hh), turn: hh, formations, pending: [], rngState: 0, seed: t.seed, journal: [] };
}

/**
 * Прогон агентной модели как RunResult для контекста сценария того же театра (berlin-1945-tasks): контекст получает
 * формирования хода (дивизии и штабы), шаг снимков stepHours и конец по последнему кадру.
 */
export function agentsToRun(base: SimContext, t: AgentTrace, stepHours = 6): { ctx: SimContext; run: RunResult } {
  const F = (k: string) => t.fields.indexOf(k);
  const [iLng, iLat, iState, iPers, iTanks, iGuns, iAmmo, iFuel, iFat, iEnc] = ['lng', 'lat', 'state', 'personnel', 'tanks', 'guns', 'ammo', 'fuel', 'fatigue', 'encircled'].map(F);
  const time = (h: number) => addHours(t.start, h);
  const hours = t.frames.length - 1;
  const end = time(hours);
  const defs: FormationDef[] = [
    ...t.hqs.map((h) => ({ id: h.id, name: h.name, side: h.side, echelon: (ECH.includes(h.echelon as Echelon) ? h.echelon : 'army') as Echelon, parent: h.parent })),
    ...t.divisions.map((d) => ({ id: d.id, name: d.name, side: d.side, echelon: 'division' as Echelon, parent: d.hq, type: typeOf(d.side, d.mobility), note: d.note })),
  ];
  const ctx: SimContext = { ...base, agentModel: true, scenario: { ...base.scenario, formations: defs, orders: [], end, turnHours: stepHours } };

  // снимки: начальный кадр и далее через stepHours (и последний)
  const at = (row: unknown[]) => [row[iLng] as number, row[iLat] as number] as LngLat;
  const ticks: number[] = [];
  for (let h = 0; h < hours; h += stepHours) ticks.push(h);
  ticks.push(hours);
  const first = new Map<string, number>();
  const gone = new Set<string>();
  const snapshots: Snapshot[] = ticks.map((h, turn) => {
    const units: Snapshot['units'] = [];
    t.frames[h].forEach((row, k) => {
      const d = t.divisions[k];
      const p = postureOf(String(row[iState]));
      if (p === null || gone.has(d.id)) return;
      if (!first.has(d.id)) first.set(d.id, h);
      const destroyed = p === 'destroyed';
      if (destroyed) gone.add(d.id);
      units.push({
        id: d.id, at: at(row), personnel: row[iPers] as number, tanks: row[iTanks] as number,
        posture: destroyed ? 'defend' : p, destroyed, ammo: row[iAmmo] as number,
        ...((row[iEnc] as number) > 0 ? { cutOff: true } : {}),
      });
    });
    return { time: time(h), turn, units };
  });

  const last = t.frames[hours];
  const init = t.frames[0];
  const formations: Formation[] = defs.map((f) => {
    const k = t.divisions.findIndex((d) => d.id === f.id);
    const row = k >= 0 ? last[k] : null;
    const r0 = k >= 0 ? init[k] : null;
    const num = (r: unknown[] | null, i: number) => (r ? (r[i] as number) : 0);
    return {
      id: f.id, name: f.name, side: f.side, echelon: f.echelon, parent: f.parent ?? null, type: f.type ?? '',
      position: row ? at(row) : [0, 0], personnel: num(row, iPers), tanks: num(row, iTanks), guns: num(row, iGuns),
      initial: { personnel: num(r0, iPers), tanks: num(r0, iTanks), guns: num(r0, iGuns) },
      ammo: num(row, iAmmo), fuel: num(row, iFuel), fatigue: num(row, iFat),
      posture: (row && postureOf(String(row[iState]))) as Posture || 'defend', dugInHours: 0, order: null, route: null,
      destroyed: gone.has(f.id), enterAt: first.get(f.id) ? time(first.get(f.id)!) : null,
    };
  });
  const final: SimState = { scenario: ctx.scenario.id, time: end, turn: snapshots.length - 1, formations, pending: [], rngState: 0, seed: t.seed, journal: [] };
  return { ctx, run: { final, snapshots } };
}

/** Состояние агента → положение соединения на карте; null — нет на карте (ещё не введена, сведена в другую). */
export function postureOf(state: string): Posture | 'destroyed' | null {
  if (state.startsWith('наступление')) return 'attack';
  if (state.startsWith('оборона')) return 'defend';
  if (state.startsWith('марш') || state === 'развёртывание') return 'march';
  if (state === 'отход' || state === 'отступление' || state.startsWith('остатки')) return 'withdraw';
  if (state === 'резерв') return 'reserve';
  if (state === 'небоеспособна') return 'destroyed';
  return null;
}

/** Тип профиля стороны для знака и силы: пешие — стрелковые, остальные — танковые/моторизованные. */
function typeOf(side: string, mobility: string): string {
  const foot = mobility === 'foot';
  return side === 'de' ? (foot ? 'inf_div' : 'pz_div') : foot ? 'rifle_corps' : 'tank_corps';
}

/** Подбираемые множители и их границы. */
export const CALIB_SPACE = {
  advance: [0.3, 1.6], attackerLoss: [0.5, 2], defenderLoss: [0.5, 2],
  prepared: [1.0, 2.2], fortPerLevel: [0, 0.8], terrainExp: [0.5, 2.5], movement: [0.4, 1.2], urbanAdvance: [0.05, 0.6], fortAdvance: [0.4, 2.0],
  // темп по территории противника, км/сут (если правила ведут территорию): пешие и подвижные
  terrFoot: [10, 80], terrMobile: [15, 150],
} as const satisfies Record<string, readonly [number, number]>;

export interface CalibScore {
  /** Мерило подбора: обучение (км) + 3 × ошибка дат событий (сут); с контрольными точками — см. strength. Меньше — лучше. */
  total: number;
  /** Среднее превышение отклонения над неопределённостью, км (до 50): обучение и проверка. */
  train: number;
  test: number;
  /** Доля положений в пределах 10 км сверх неопределённости. */
  within: number;
  /** Средняя ошибка дат событий обучения, сут (несостоявшееся — 6). */
  events: number;
  detail: { id: string; days: number | null }[];
  /**
   * Сверка численности и потерь с документами на обучении (History.checkpoints до trainUntil): точек за прогон и доля
   * в пределах ±25 %. От 10 точек входит в total: total × 0,75 + (1 − within) × 50 × 0,25. Нет точек — поля нет.
   */
  strength?: { n: number; within: number };
}

/**
 * Подбор множителей: next(k) — следующие кандидаты (их можно считать параллельно), report — результат.
 * Первые 40 % — широкий случайный поиск, дальше — уточнение вокруг лучшего с сужающимся шагом.
 */
export class Calibrator {
  private rng;
  private issued = 0;
  best: { p: CalibParams; s: CalibScore } | null = null;
  constructor(readonly start: CalibParams, readonly evals: number, seed = 2026, readonly keys: CalibKey[] = CALIB_KEYS) { this.rng = createRng(seed); }
  get done() { return this.issued >= this.evals; }
  get progress() { return this.issued; }
  private clamp(k: CalibKey, v: number) { return Math.min(CALIB_SPACE[k][1], Math.max(CALIB_SPACE[k][0], v)); }
  next(k: number): CalibParams[] {
    const out: CalibParams[] = [];
    const explore = Math.floor(this.evals * 0.4);
    for (let j = 0; j < k && this.issued < this.evals; j++, this.issued++) {
      const i = this.issued;
      const p = { ...(this.best?.p ?? this.start) };
      for (const key of this.keys) {
        p[key] = i < explore || !this.best
          ? CALIB_SPACE[key][0] + this.rng.next() * (CALIB_SPACE[key][1] - CALIB_SPACE[key][0])
          : this.clamp(key, this.best.p[key] * Math.exp(this.rng.normal() * 0.15 * (1 - i / this.evals)));
      }
      out.push(p);
    }
    return out;
  }
  /** Учесть результат; true — новый лучший. */
  report(p: CalibParams, s: CalibScore): boolean {
    if (this.best && s.total >= this.best.s.total) return false;
    this.best = { p, s };
    return true;
  }
}

/** Итог прогонов набора правил: мерило калибровки и всё для сравнения с историей и другими моделями. */
export interface RulesEvaluation {
  score: CalibScore;
  /** Доля положений в допуске и медиана превышения (по всем прогонам). */
  within: number;
  medianExcessKm: number;
  n: number;
  /** По дням: среднее превышение, км, и доля в допуске. */
  byDay: { day: string; meanExcessKm: number; within: number; n: number }[];
  /** События: историческая дата и расхождение в сутках по прогонам (null — не случилось). */
  events: { id: string; title: string; historical: string; days: (number | null)[] }[];
  ms: number;
}

/** Множители, при которых правила не меняются (исходная точка подбора). */
export function baseParams(r: Rules): CalibParams {
  return {
    advance: 1, attackerLoss: 1, defenderLoss: 1, prepared: r.defense.prepared, fortPerLevel: r.defense.fortificationPerLevel, terrainExp: 1,
    movement: r.movementScale ?? 1, urbanAdvance: r.advanceTerrain?.urban ?? 1, fortAdvance: 1,
    terrFoot: r.territory?.enemyKmPerDay.foot ?? 30, terrMobile: r.territory?.enemyKmPerDay.tracked ?? 50,
  };
}

/** Правила-итог калибровки с блоком calibration (откуда, множители, мерило до и после). */
export function calibratedRules(base: Rules, p: CalibParams, o: { id: string; scenario: string; evals: number; seeds: number; trainUntil: string; before: CalibScore; after: CalibScore; note?: string }): Rules {
  return {
    ...rulesWith(base, p, `откалибровано по ${o.scenario} (блок calibration: исходные правила, множители, мерило до и после)`),
    id: o.id,
    calibration: {
      scenario: o.scenario, date: new Date().toISOString().slice(0, 10), evals: o.evals, seeds: o.seeds, trainUntil: o.trainUntil,
      from: base.id, multipliers: Object.fromEntries(CALIB_KEYS.map((k) => [k, +p[k].toFixed(3)])),
      before: { trainKm: o.before.train, testKm: o.before.test, eventsDays: o.before.events, within: o.before.within },
      after: { trainKm: o.after.train, testKm: o.after.test, eventsDays: o.after.events, within: o.after.within },
      events: o.after.detail,
      note: o.note ?? 'Подобрано по одной операции: обязательна проверка на контрольной операции. Мерило — среднее превышение отклонения над неопределённостью исторического положения (до 50 км) + 3 × средняя ошибка дат событий (сут).',
    },
  };
}

/** Середина операции — граница «обучения» и «проверки» по умолчанию. */
export const defaultTrainUntil = (ctx: SimContext) =>
  new Date((Date.parse(ctx.scenario.start + 'Z') + Date.parse(ctx.scenario.end + 'Z')) / 2).toISOString().slice(0, 10) + 'T23:59';

/** Прогнать правила seeds раз и сравнить с историей. */
export function evaluateRules(ctx: SimContext, rules: Rules, history: History, o: { seeds?: number; trainUntil?: string; seed0?: number; toleranceKm?: number } = {}): RulesEvaluation {
  const c: SimContext = { ...ctx, rules };
  const seeds = o.seeds ?? 2, trainUntil = o.trainUntil ?? defaultTrainUntil(ctx), tol = o.toleranceKm ?? 10;
  let tr = 0, te = 0, ntr = 0, nte = 0, ev = 0, nev = 0, within10 = 0, n = 0;
  const all: number[] = [];
  const days = new Map<string, number[]>();
  const events = new Map<string, RulesEvaluation['events'][number]>();
  let detail: CalibScore['detail'] = [];
  // контрольные точки численности и потерь обучения
  const cpTrain = (history.checkpoints ?? []).filter((c) => c.at <= trainUntil);
  let cpN = 0, cpWithin = 0;
  const t0 = Date.now();
  for (let s = 0; s < seeds; s++) {
    const run = runScenario(c, (o.seed0 ?? 101) + s);
    for (const d of compareWithHistory(c, run, history)) {
      const v = Math.min(d.excessKm, 50);
      if (d.time <= trainUntil) { tr += v; ntr++; } else { te += v; nte++; }
      if (d.excessKm <= 10) within10++;
      n++;
      all.push(d.excessKm);
      const day = d.time.slice(0, 10);
      days.set(day, [...(days.get(day) ?? []), d.excessKm]);
    }
    const evs = checkEvents(c, run, history);
    for (const e of evs) {
      const x = events.get(e.id) ?? { id: e.id, title: e.title, historical: e.historical, days: [] };
      x.days.push(e.days);
      events.set(e.id, x);
      if (e.historical > trainUntil.slice(0, 10)) continue;
      ev += e.days == null ? 6 : Math.min(6, Math.abs(e.days));
      nev++;
    }
    detail = evs.map((e) => ({ id: e.id, days: e.days }));
    if (cpTrain.length) {
      const st = compareStrength(c, run, { ...history, checkpoints: cpTrain });
      cpN += st.n; cpWithin += st.within * st.n;
    }
  }
  const train = tr / Math.max(1, ntr), test = te / Math.max(1, nte), evd = ev / Math.max(1, nev);
  const sorted = [...all].sort((a, b) => a - b);
  const strength = cpN ? { n: Math.round(cpN / seeds), within: +(cpWithin / cpN).toFixed(3) } : undefined;
  const base = train + 3 * evd;
  const total = strength && strength.n >= STRENGTH_MIN_POINTS ? base * (1 - STRENGTH_WEIGHT) + (1 - strength.within) * 50 * STRENGTH_WEIGHT : base;
  return {
    score: { total: +total.toFixed(3), train: +train.toFixed(2), test: +test.toFixed(2), within: +(within10 / Math.max(1, n)).toFixed(3), events: +evd.toFixed(2), detail, ...(strength ? { strength } : {}) },
    within: +(all.filter((x) => x <= tol).length / Math.max(1, all.length)).toFixed(3),
    medianExcessKm: sorted.length ? sorted[Math.floor(sorted.length / 2)] : 0,
    n: all.length,
    byDay: [...days.entries()].sort(([a], [b]) => a.localeCompare(b)).map(([day, l]) => ({ day, meanExcessKm: +(l.reduce((a, b) => a + b, 0) / l.length).toFixed(1), within: +(l.filter((x) => x <= tol).length / l.length).toFixed(2), n: l.length })),
    events: [...events.values()],
    ms: Date.now() - t0,
  };
}

/** Слить оценки отдельных прогонов (по одному seed — из разных потоков) в одну. */
export function mergeEvaluations(list: RulesEvaluation[]): RulesEvaluation {
  if (list.length === 1) return list[0];
  const w = (f: (e: RulesEvaluation) => number) => list.reduce((a, e) => a + f(e) * e.n, 0) / Math.max(1, list.reduce((a, e) => a + e.n, 0));
  const avg = (f: (e: RulesEvaluation) => number) => list.reduce((a, e) => a + f(e), 0) / list.length;
  const meds = list.map((e) => e.medianExcessKm).sort((a, b) => a - b);
  const days = new Map<string, { s: number; w: number; n: number }>();
  for (const e of list) for (const d of e.byDay) { const x = days.get(d.day) ?? { s: 0, w: 0, n: 0 }; x.s += d.meanExcessKm * d.n; x.w += d.within * d.n; x.n += d.n; days.set(d.day, x); }
  const events = list[0].events.map((ev) => ({ ...ev, days: list.flatMap((e) => e.events.find((x) => x.id === ev.id)?.days ?? []) }));
  const st = list.filter((e) => e.score.strength?.n);
  const stN = st.reduce((a, e) => a + e.score.strength!.n, 0);
  const strength = st.length ? { n: Math.round(stN / st.length), within: +(st.reduce((a, e) => a + e.score.strength!.within * e.score.strength!.n, 0) / stN).toFixed(3) } : undefined;
  return {
    score: { total: +avg((e) => e.score.total).toFixed(3), train: +avg((e) => e.score.train).toFixed(2), test: +avg((e) => e.score.test).toFixed(2), within: +avg((e) => e.score.within).toFixed(3), events: +avg((e) => e.score.events).toFixed(2), detail: list[0].score.detail, ...(strength ? { strength } : {}) },
    within: +w((e) => e.within).toFixed(3),
    medianExcessKm: meds[Math.floor(meds.length / 2)],
    n: list.reduce((a, e) => a + e.n, 0),
    byDay: [...days.entries()].sort(([a], [b]) => a.localeCompare(b)).map(([day, x]) => ({ day, meanExcessKm: +(x.s / x.n).toFixed(1), within: +(x.w / x.n).toFixed(2), n: x.n })),
    events,
    ms: list.reduce((a, e) => a + e.ms, 0),
  };
}

/** Правила с применёнными множителями. */
export function rulesWith(r0: Rules, p: CalibParams, status?: string): Rules {
  const scale = (t: [number, number][], k: number) => t.map(([x, y]) => [x, +(y * k).toFixed(4)] as [number, number]);
  return {
    ...r0,
    ...(status ? { _status: status } : {}),
    advance: scale(r0.advance, p.advance),
    attackerLoss: scale(r0.attackerLoss, p.attackerLoss),
    defenderLoss: scale(r0.defenderLoss, p.defenderLoss),
    defense: {
      ...r0.defense,
      prepared: +p.prepared.toFixed(3),
      fortificationPerLevel: +p.fortPerLevel.toFixed(3),
      terrain: Object.fromEntries(Object.entries(r0.defense.terrain).map(([k, v]) => [k, +Math.pow(v!, p.terrainExp).toFixed(3)])),
    },
    movementScale: +p.movement.toFixed(3),
    advanceTerrain: { ...(r0.advanceTerrain ?? {}), urban: +p.urbanAdvance.toFixed(3) },
    ...(r0.fortAdvanceKm ? { fortAdvanceKm: r0.fortAdvanceKm.map((v, i) => (i ? +(v * p.fortAdvance).toFixed(2) : v)) } : {}),
    ...(r0.territory ? { territory: { ...r0.territory, enemyKmPerDay: { foot: +p.terrFoot.toFixed(1), motor: +p.terrMobile.toFixed(1), tracked: +p.terrMobile.toFixed(1) } } } : {}),
  };
}

/** Оценить правила по истории (мерило калибровки): seeds прогонов. */
export function scoreRules(ctx: SimContext, rules: Rules, history: History, o: { seeds?: number; trainUntil?: string; seed0?: number } = {}): CalibScore {
  return evaluateRules(ctx, rules, history, o).score;
}

/**
 * Названия высшего командования стороны и её объединений верхнего уровня — для текстов линий, журнала и
 * интерфейса: у Красной армии — Ставка и фронты, у вермахта — ОКХ и группы армий.
 */
export interface CommandTerms {
  /** Высшее командование: «Ставка», «ОКХ». */
  top: string;
  /** Род. падеж: «Ставки», «ОКХ». */
  topGen: string;
  /** «в Ставку», «в ОКХ». */
  topTo: string;
  /** Объединение верхнего уровня: «фронт», «группа армий». */
  group: string;
  /** Род. падеж мн. ч.: «фронтов», «групп армий». */
  groupsGen: string;
  /** Документ о линии сверху: «директива», «приказ». */
  directive: string;
}

export function commandTerms(ctx: SimContext, side: string): CommandTerms {
  let german = false;
  try { german = profileOf(ctx, side).id.startsWith('wehrmacht'); } catch { /* сторона без профиля */ }
  return german
    ? { top: 'ОКХ', topGen: 'ОКХ', topTo: 'в ОКХ', group: 'группа армий', groupsGen: 'групп армий', directive: 'приказ' }
    : { top: 'Ставка', topGen: 'Ставки', topTo: 'в Ставку', group: 'фронт', groupsGen: 'фронтов', directive: 'директива' };
}

export interface ControlMap {
  /** Индекс стороны с перевесом влияния; −1 — ничья (влияния нет). */
  owner: Int8Array;
  sides: string[];
}

export interface SupplyField {
  /** Часы подвоза до клетки по своей территории (Infinity — не доходит). */
  hours: Float64Array;
}

/**
 * Занятие территории: клетки в радиусе radiusKm от пути формирования за ход (отрезок
 * от прежнего положения к новому) переходят к его стороне, если противник к ним не ближе.
 */
export function claimTerritory(T: Theatre, owner: Int8Array, moves: { side: number; from: LngLat; to: LngLat }[], enemyCloser: (side: number, cell: [number, number], km: number) => boolean, radiusKm: number) {
  const rc = Math.ceil(radiusKm / T.cellKm) + 1;
  for (const m of moves) {
    const a = T.proj.toXY(m.from), b = T.proj.toXY(m.to);
    const len = Math.hypot(b[0] - a[0], b[1] - a[1]);
    const steps = Math.max(1, Math.ceil(len / T.cellKm));
    for (let k = 0; k <= steps; k++) {
      const q: [number, number] = [a[0] + ((b[0] - a[0]) * k) / steps, a[1] + ((b[1] - a[1]) * k) / steps];
      const i0 = T.indexOf(T.proj.toLL(q));
      if (i0 < 0) continue;
      const c0 = i0 % T.cols, r0 = Math.floor(i0 / T.cols);
      for (let r = r0 - rc; r <= r0 + rc; r++) for (let c = c0 - rc; c <= c0 + rc; c++) {
        if (!T.inside(c, r)) continue;
        const i = r * T.cols + c;
        if (owner[i] === m.side) continue;
        const p = T.cellCenter(c, r);
        const d = Math.hypot(p[0] - q[0], p[1] - q[1]);
        if (d > radiusKm) continue;
        if (!enemyCloser(m.side, p, d)) owner[i] = m.side;
      }
    }
  }
}

export function controlMap(T: Theatre, units: Formation[], sides: string[], weight: (f: Formation) => number, sigmaKm = 12, exponent = 0.3): ControlMap {
  const N = T.cols * T.rows;
  const infl = sides.map(() => new Float64Array(N));
  const reach = sigmaKm * 3, rc = Math.ceil(reach / T.cellKm);
  for (const u of units) {
    const k = sides.indexOf(u.side);
    if (k < 0) continue;
    const w = Math.pow(Math.max(0, weight(u)), exponent);
    const i0 = T.indexOf(u.position);
    if (i0 < 0) continue;
    const c0 = i0 % T.cols, r0 = Math.floor(i0 / T.cols);
    for (let r = Math.max(0, r0 - rc); r <= Math.min(T.rows - 1, r0 + rc); r++) for (let c = Math.max(0, c0 - rc); c <= Math.min(T.cols - 1, c0 + rc); c++) {
      const d = Math.hypot(c - c0, r - r0) * T.cellKm;
      if (d > reach) continue;
      infl[k][r * T.cols + c] += w * Math.exp(-(d * d) / (2 * sigmaKm * sigmaKm));
    }
  }
  const owner = new Int8Array(N).fill(-1);
  for (let i = 0; i < N; i++) {
    let best = -1, bv = 1e-9;
    for (let k = 0; k < sides.length; k++) if (infl[k][i] > bv) { bv = infl[k][i]; best = k; }
    owner[i] = best;
  }
  return { owner, sides };
}

/**
 * Исходная территория: каждая сторона «растекается» от своих войск и тылов (источники
 * подвоза) по клеткам; переход большой реки и чужой укреплённой полосы обходится дорого
 * (barrierKm), поэтому граница ложится по рекам и главной полосе обороны, а не посередине
 * между ближайшими частями. Клетка — стороне с меньшим «расстоянием». Дальше территория
 * меняется только движением войск.
 */
export function initialTerritory(T: Theatre, points: { side: number; at: LngLat }[], sideIds: string[], barrierKm = 40): Int8Array {
  const N = T.cols * T.rows;
  const best = new Float64Array(N).fill(Infinity);
  const out = new Int8Array(N).fill(-1);
  for (let k = 0; k < sideIds.length; k++) {
    const d = new Float64Array(N).fill(Infinity);
    const heap = new MinHeap();
    for (const p of points) if (p.side === k) { const i = T.indexOf(p.at); if (i >= 0 && d[i] > 0) { d[i] = 0; heap.push(i, 0); } }
    // преграда штрафуется один раз — при входе в неё (река и полоса бывают шириной в несколько клеток)
    const enemyFort = (i: number) => !!T.fort[i] && !!T.fortSide[i] && T.fortSide[i] !== sideIds[k];
    const cost = (from: number, i: number) => T.cellKm + (T.river[i] === 2 && T.river[from] !== 2 ? barrierKm : 0) + (enemyFort(i) && !enemyFort(from) ? barrierKm / 2 : 0);
    while (heap.size) {
      const cur = heap.pop();
      const c0 = cur % T.cols, r0 = Math.floor(cur / T.cols);
      for (const [dc, dr] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
        const c = c0 + dc, r = r0 + dr;
        if (!T.inside(c, r)) continue;
        const ni = r * T.cols + c, nd = d[cur] + cost(cur, ni);
        if (nd < d[ni]) { d[ni] = nd; heap.push(ni, nd); }
      }
    }
    for (let i = 0; i < N; i++) if (d[i] < best[i]) { best[i] = d[i]; out[i] = k; }
  }
  return out;
}

/** Поле времени подвоза для стороны: от источников в обход зон влияния противника. */
export function supplyField(T: Theatre, side: string, sources: LngLat[], units: Formation[], profile: SideProfile, rules: Rules, time: string, zocKm: number | ((f: Formation) => number), territory?: { owner: ArrayLike<number>; side: number; ownZoneKm: number }): SupplyField {
  const pass = supplyPassable(T, units, side, zocKm, territory);
  const src = sources.map((p) => T.indexOf(p)).filter((i) => i >= 0 && pass[i]);
  const hours = T.distanceField(src, 'motor', profile, rules, time, (i) => pass[i] === 1);
  return { hours };
}

/**
 * Проходимость для подвоза стороны: клетка закрыта, если ближайший противник
 * ближе zocKm и ближе любого своего формирования (зона влияния противника).
 * Окружение получается, когда кольцо таких зон смыкается вокруг формирования.
 */
export function supplyPassable(T: Theatre, units: Formation[], side: string, zocKm: number | ((f: Formation) => number), territory?: { owner: ArrayLike<number>; side: number; ownZoneKm: number; holdKm?: number }): Uint8Array {
  const N = T.cols * T.rows;
  const zoc = typeof zocKm === 'number' ? () => zocKm : zocKm;
  const own = units.filter((u) => u.side === side).map((u) => T.proj.toXY(u.position));
  const enemy = units.filter((u) => u.side !== side).map((u) => ({ p: T.proj.toXY(u.position), r: zoc(u) }));
  const out = new Uint8Array(N).fill(1);
  // территория противника закрыта для подвоза (сплошная полоса); зоны его формирований тогда —
  // только их собственный район (сами войска), а не широкие зоны влияния: окружение даёт территория.
  // Но где стоят наши войска (ближе holdKm и ближе противника), туда идут и их колонны: объединение
  // держит полосу в десятки км, а не точку, и обойдённые узлы противника рядом его подвоз не перерезают.
  if (territory) {
    const hold = territory.holdKm ?? 0;
    for (let i = 0; i < N; i++) {
      const o = territory.owner[i];
      if (o < 0 || o === territory.side) continue;
      out[i] = 0;
      if (!hold) continue;
      const p = T.cellCenter(i % T.cols, Math.floor(i / T.cols));
      let dOwn = Infinity, dEn = Infinity;
      for (const q of own) { const d = Math.hypot(q[0] - p[0], q[1] - p[1]); if (d < dOwn) dOwn = d; }
      if (dOwn > hold) continue;
      for (const e of enemy) { const d = Math.hypot(e.p[0] - p[0], e.p[1] - p[1]); if (d < dEn) dEn = d; }
      if (dOwn < dEn) out[i] = 1;
    }
    for (const e of enemy) e.r = territory.ownZoneKm;
  }
  for (let i = 0; i < N; i++) {
    if (!out[i]) continue;
    const p = T.cellCenter(i % T.cols, Math.floor(i / T.cols));
    let de = Infinity, inZone = false;
    for (const e of enemy) { const d = Math.hypot(e.p[0] - p[0], e.p[1] - p[1]); if (d < de) de = d; if (d < e.r) inZone = true; }
    if (!inZone) continue;
    let dOwn = Infinity;
    for (const o of own) { const d = Math.hypot(o[0] - p[0], o[1] - p[1]); if (d < dOwn) dOwn = d; }
    if (dOwn > de) out[i] = 0;
  }
  return out;
}

/** Всё, что нужно для прогона сценария: театр, профили сторон, правила. */
export function loadContext(scenarioId: string, rulesId?: string): SimContext {
  const scenario = loadScenario(scenarioId);
  const profiles = Object.fromEntries(scenario.sides.map((s) => [s.profile, loadProfile(s.profile)]));
  return { scenario, theatre: new Theatre(loadTheatre(scenario.theatre)), profiles, rules: loadRules(rulesId ?? scenario.rules) };
}

/** Правила; `extends` — взять базовые и переписать поверх указанные поля (вложенные объекты — слиянием). */
export function loadRules(id: string): Rules {
  const r = read<Rules>('rules', `${id}.json`);
  return r.extends ? mergeRules(loadRules(r.extends), r) : r;
}

/** Значение таблицы при соотношении 3:1 (интерполяция в лог-шкале) — одно число для сравнения. */
function at3(t: Table): number {
  const f = Math.log;
  if (3 <= t[0][0]) return t[0][1];
  for (let i = 1; i < t.length; i++) if (3 <= t[i][0]) { const [x0, y0] = t[i - 1], [x1, y1] = t[i]; return y0 + (y1 - y0) * ((f(3) - f(x0)) / (f(x1) - f(x0))); }
  return t[t.length - 1][1];
}

/** Профиль стороны словами. */
export function describeProfile(p: SideProfile): ParamRow[] {
  const R: ParamRow[] = [];
  const add = (key: string, group: string, title: string, value: string, hint: string) => R.push({ key, group, title, value, hint });
  add('weights', 'Боевой потенциал', 'Вес сил', `1000 чел. — ${n(p.weights.personnel)}, танк/САУ — ${n(p.weights.tanks)}, орудие — ${n(p.weights.guns)}`, 'вклад в боевой потенциал');
  add('types', 'Боевой потенциал', 'Типы формирований', Object.values(p.unitTypes).map((u) => `${u.name} (${MOB[u.mobility] ?? u.mobility}, качество ×${n(u.quality)})`).join('; '), 'качество — выучка, слаженность, управление');
  add('road', 'Движение', 'Марш по дороге', Object.entries(p.road).map(([k, v]) => `${MOB[k] ?? k} ${v} км/сут`).join(', '), 'темп марша по дорогам');
  add('offroad', 'Движение', 'Марш вне дорог (открытая)', Object.entries(p.offRoad).map(([k, v]) => `${MOB[k] ?? k} ${v.open} км/сут`).join(', '), 'по открытой местности; лес, болото, город — по таблице профиля');
  add('delay', 'Управление', 'Доведение приказов', Object.entries(p.orderDelayHours).map(([k, v]) => `${ECH[k] ?? k} — ${v} ч`).join(', '), 'сколько приказ идёт до исполнения');
  if (p.supply) add('supply', 'Тыл', 'Подвоз', `${n(p.supply.ammoPerDay)} бк и ${n(p.supply.fuelPerDay)} запр. в сутки, до ${p.supply.rangeHours} ч от базы`, `запасы не выше ${p.supply.maxAmmo} бк / ${p.supply.maxFuel} запр.`);
  if (p.engineering) add('eng', 'Тыл', 'Переправы', `большая река ${p.engineering.bridgeHoursMajor} ч, малая ${p.engineering.bridgeHoursMinor} ч, парков ${p.engineering.parks}`, 'наводка переправ инженерными войсками');
  return R;
}

/** Параметры правил по группам. */
export function describeRules(r: Rules): ParamRow[] {
  const R: ParamRow[] = [];
  const add = (key: string, group: string, title: string, value: string, hint: string, num?: number) => R.push({ key, group, title, value, hint, num });
  add('contactKm', 'Бой', 'Расстояние соприкосновения', `${n(r.contactKm, 1)} км`, 'ближе — части вступают в бой', r.contactKm);
  add('advance3', 'Бой', 'Темп наступления при 3:1', `${n(at3(r.advance), 1)} км/сут`, `таблица по соотношению сил: ${table(r.advance, ' км/сут')}`, at3(r.advance));
  add('attLoss3', 'Бой', 'Потери наступающего при 3:1', `${n(at3(r.attackerLoss) * 100, 1)} %/сут`, `доля состава в сутки: ${table(r.attackerLoss)}`, at3(r.attackerLoss));
  add('defLoss3', 'Бой', 'Потери обороняющегося при 3:1', `${n(at3(r.defenderLoss) * 100, 1)} %/сут`, `доля состава в сутки: ${table(r.defenderLoss)}`, at3(r.defenderLoss));
  add('noise', 'Бой', 'Разброс исхода боя', `±${n(r.noise * 100, 0)} %`, 'случайный множитель к соотношению сил (σ логнормального)', r.noise);
  add('prepared', 'Оборона', 'Подготовленная оборона', `×${n(r.defense.prepared)} после ${r.defense.prepareHours} ч`, 'сила обороняющегося, простоявшего на месте', r.defense.prepared);
  add('fort', 'Оборона', 'Укрепления', `+${n(r.defense.fortificationPerLevel * 100, 0)} % за уровень`, 'прибавка к силе обороны за уровень укреплённости района', r.defense.fortificationPerLevel);
  add('terrain', 'Оборона', 'Местность', Object.entries(r.defense.terrain).map(([k, v]) => `${TERR[k] ?? k} ×${n(v!)}`).join(', ') || '—', 'поправка к силе обороняющегося за местность');
  if (r.heightAdvantage) add('height', 'Оборона', 'Превышение', `±${n(r.heightAdvantage.bonus * 100, 0)} % за ${r.heightAdvantage.perM} м, не больше ±${n(r.heightAdvantage.max * 100, 0)} %`, 'оборона выше наступающих — сильнее, ниже — слабее (нужна сетка высот театра)', r.heightAdvantage.bonus);
  if (r.advanceTerrain) add('advTerrain', 'Оборона', 'Темп по местности обороны', Object.entries(r.advanceTerrain).map(([k, v]) => `${TERR[k] ?? k} ×${n(v!)}`).join(', '), 'доля обычного темпа наступления', r.advanceTerrain.urban);
  if (r.fortAdvanceKm) add('fortAdvance', 'Оборона', 'Прогрызание полос', r.fortAdvanceKm.slice(1).map((v, i) => `ур. ${i + 1}: ${n(v, 1)} км/сут`).join(', '), 'предельный темп прорыва укреплённой полосы, пока оборона в ней стоит', r.fortAdvanceKm[1]);
  if (r.fortCrossHours) add('fortCross', 'Оборона', 'Заграждения вне боя', `${n(r.fortCrossHours, 1)} ч/клетку за уровень`, 'мины, рвы, заграждения непрорванной полосы', r.fortCrossHours);
  add('ammo', 'Снабжение и состояние', 'Нехватка боеприпасов', `сила ×${n(r.ammoShort)}`, 'при запасе меньше 0,5 боекомплекта', r.ammoShort);
  add('fuel', 'Снабжение и состояние', 'Без горючего', `техника ×${n(r.fuelOut)}`, 'подвижные части без горючего не движутся и слабеют', r.fuelOut);
  if (r.supplyFlow) add('supplyFlow', 'Снабжение и состояние', 'Подвоз как пропускная способность', `полный до ${r.supplyFlow.fullHours ?? 12} ч пути, дальше слабее; ${n(r.supplyFlow.fuelPer100km ?? 1)} запр. на 100 км марша`, 'горючее подвижных частей — по пройденному пути; пополнение падает с удалением от базы');
  add('fatigue', 'Снабжение и состояние', 'Усталость', `до −${n(r.fatigueEffect * 100, 0)} % силы`, `прирост в бою ${n(r.fatigueGain.combat * 100, 0)} %/сут, на марше ${n(r.fatigueGain.march * 100, 0)} %/сут, отдых −${n(r.fatigueGain.rest * 100, 0)} %/сут`, r.fatigueEffect);
  add('encircle', 'Снабжение и состояние', 'Окружение', `${r.encircleHours ?? 36} ч без подвоза`, 'через сколько часов без подвоза формирование считается окружённым', r.encircleHours ?? 36);
  add('movement', 'Движение', 'Темп марша', `×${n(r.movementScale ?? 1)}`, 'множитель к темпам марша из профилей сторон', r.movementScale ?? 1);
  add('variety', 'Движение', 'Разброс выбора пути', r.routeVariety ? `±${n(r.routeVariety * 100, 0)} %` : 'нет — всегда самый быстрый', 'одни формирования идут дорогой, другие лесом или полем напрямик; разный seed — разные пути', r.routeVariety ?? 0);
  add('sectors', 'Движение', 'Полосы по директивам', r.sectors?.foreign ? `полоса соседа ×${n(1 + r.sectors.foreign, 1)} при выборе пути` : 'не учитываются', 'по разграничительным линиям директив войска идут своей полосой; время движения не меняется', r.sectors?.foreign ?? 0);
  if (r.followParentKm) add('followParent', 'Движение', 'Корпус за армией', `выполнив задачу (ближе ${n(r.followParentKm, 0)} км к цели), идёт к цели армии`, 'корпус или отряд, дошедший до цели своего приказа наступления, действует дальше в полосе армии до нового приказа', r.followParentKm);
  add('river', 'Движение', 'Река без моста', `+${r.riverCrossHours} ч для пехоты`, 'техника — только по мостам и переправам', r.riverCrossHours);
  if (r.territory) add('territory', 'Движение', 'Территория противника', `пешие ${n(r.territory.enemyKmPerDay.foot ?? 0, 0)}, подвижные ${n(r.territory.enemyKmPerDay.tracked ?? 0, 0)} км/сут`, `территория переходит к стороне, где прошли её войска (полоса ${r.territory.radiusKm} км); по чужой — медленнее`, r.territory.enemyKmPerDay.foot);
  const rg = Object.entries(r.regimes ?? {}).flatMap(([k, v]) => Object.entries(v ?? {}).filter(([, x]) => x !== 1).map(([p, x]) => `${REGIME_RU[k as Regime]}: ${p === 'speed' ? 'темп движения' : p === 'advance' ? 'темп боя' : 'потери'} ×${n(x as number)}`));
  if (rg.length) add('regimes', 'Режимы', 'Поправки режимов боевых действий', rg.join('; '), 'множители, которые действуют только в своём режиме (бой в застройке, в полосе, преследование и т. д.); подобраны по темпу там, где операции согласны');
  add('city', 'Движение', 'Городской бой', [r.holdGivesGround ? '«держаться» — уступая кварталы' : null, r.bypassStrongpoints === false ? 'узлы обороны не обходятся' : 'узлы обороны обходятся'].filter(Boolean).join('; '), 'правила городского масштаба');
  return R;
}

/** Чем различаются два набора правил: строки, где значения не совпадают. */
export function diffRules(a: Rules, b: Rules): { key: string; group: string; title: string; a: string; b: string }[] {
  const A = describeRules(a), B = new Map(describeRules(b).map((x) => [x.key, x]));
  return A.filter((x) => B.get(x.key) && B.get(x.key)!.value !== x.value).map((x) => ({ key: x.key, group: x.group, title: x.title, a: x.value, b: B.get(x.key)!.value }));
}

/** Откуда правила: базовые, калибровка, мерило до и после. */
export function rulesOrigin(r: Rules): { status: string; extends?: string; calibration?: { scenario: string; date: string; from: string; evals: number; before: Record<string, number>; after: Record<string, number>; multipliers: Record<string, number> } } {
  const c = r.calibration as Record<string, unknown> | undefined;
  return {
    status: String((r as unknown as Record<string, unknown>)._status ?? ''),
    extends: r.extends,
    ...(c && c.after ? { calibration: { scenario: String(c.scenario), date: String(c.date), from: String(c.from), evals: Number(c.evals), before: c.before as Record<string, number>, after: c.after as Record<string, number>, multipliers: (c.multipliers ?? {}) as Record<string, number> } } : {}),
  };
}

export interface FrontOptions {
  /** Радиус влияния формирования, км (σ гауссова затухания). */
  sigmaKm?: number;
  /** Шаг сетки поля, км. */
  stepKm?: number;
  /** Порог: доля максимума влияния, ниже которой обе стороны «отсутствуют». */
  minShare?: number;
  /**
   * Показатель степени силы во влиянии (0..1). При 1 перевес в силе «вдавливает»
   * линию прямо в позиции слабого; положение формирований важнее их силы,
   * поэтому по умолчанию 0,3: линия между сторонами, смещена к слабой.
   */
  strengthExponent?: number;
}

export function frontLine(theatre: Theatre, formations: Formation[], sides: [string, string], weight: (f: Formation) => number, o: FrontOptions = {}): LngLat[][] {
  const sigma = o.sigmaKm ?? 12, step = o.stepKm ?? Math.max(theatre.cellKm * 2, 2), minShare = o.minShare ?? 0.02, ex = o.strengthExponent ?? 0.3;
  const [w, s, e, n] = theatre.data.bbox;
  const p0 = theatre.proj.toXY([w, s]), p1 = theatre.proj.toXY([e, n]);
  const cols = Math.ceil((p1[0] - p0[0]) / step) + 1, rows = Math.ceil((p1[1] - p0[1]) / step) + 1;
  const units = formations.filter((f) => !f.destroyed).map((f) => ({ side: f.side, p: theatre.proj.toXY(f.position), w: Math.pow(Math.max(0, weight(f)), ex) }));
  const A = new Float64Array(cols * rows), B = new Float64Array(cols * rows);
  const reach = sigma * 3;
  for (const u of units) {
    const arr = u.side === sides[0] ? A : u.side === sides[1] ? B : null;
    if (!arr) continue;
    const c0 = Math.max(0, Math.floor((u.p[0] - reach - p0[0]) / step)), c1 = Math.min(cols - 1, Math.ceil((u.p[0] + reach - p0[0]) / step));
    const r0 = Math.max(0, Math.floor((u.p[1] - reach - p0[1]) / step)), r1 = Math.min(rows - 1, Math.ceil((u.p[1] + reach - p0[1]) / step));
    for (let r = r0; r <= r1; r++) for (let c = c0; c <= c1; c++) {
      const d = dist([p0[0] + c * step, p0[1] + r * step], u.p);
      arr[r * cols + c] += u.w * Math.exp(-(d * d) / (2 * sigma * sigma));
    }
  }
  let maxI = 0;
  for (let i = 0; i < A.length; i++) maxI = Math.max(maxI, A[i], B[i]);
  const thr = maxI * minShare;
  // поле: >0 — сторона 0, <0 — сторона 1; NaN — нет ни тех, ни других
  const F = new Float64Array(cols * rows);
  for (let i = 0; i < F.length; i++) F[i] = A[i] < thr && B[i] < thr ? NaN : Math.log((A[i] + thr * 0.01) / (B[i] + thr * 0.01));
  const at = (c: number, r: number): XY => [p0[0] + c * step, p0[1] + r * step];
  const segs: [XY, XY][] = [];
  const edge = (pa: XY, va: number, pb: XY, vb: number): XY => { const t = va / (va - vb); return [pa[0] + (pb[0] - pa[0]) * t, pa[1] + (pb[1] - pa[1]) * t]; };
  for (let r = 0; r < rows - 1; r++) for (let c = 0; c < cols - 1; c++) {
    const v = [F[r * cols + c], F[r * cols + c + 1], F[(r + 1) * cols + c + 1], F[(r + 1) * cols + c]];
    if (v.some(Number.isNaN)) continue;
    const p = [at(c, r), at(c + 1, r), at(c + 1, r + 1), at(c, r + 1)];
    const cuts: XY[] = [];
    for (let k = 0; k < 4; k++) {
      const a = v[k], b = v[(k + 1) % 4];
      if ((a > 0) !== (b > 0)) cuts.push(edge(p[k], a, p[(k + 1) % 4], b));
    }
    if (cuts.length === 2) segs.push([cuts[0], cuts[1]]);
    else if (cuts.length === 4) { segs.push([cuts[0], cuts[1]]); segs.push([cuts[2], cuts[3]]); }
  }
  return joinSegments(segs, step * 0.01).filter((l) => l.length >= 3).map((l) => l.map((q) => theatre.proj.toLL(q)));
}

/** Собрать отрезки в ломаные по совпадающим концам. */
function joinSegments(segs: [XY, XY][], eps: number): XY[][] {
  const key = (p: XY) => `${Math.round(p[0] / eps)}:${Math.round(p[1] / eps)}`;
  const ends = new Map<string, number[]>();
  segs.forEach((s, i) => { for (const p of s) { const k = key(p); ends.set(k, [...(ends.get(k) ?? []), i]); } });
  const used = new Uint8Array(segs.length);
  const lines: XY[][] = [];
  for (let i = 0; i < segs.length; i++) {
    if (used[i]) continue;
    used[i] = 1;
    const line: XY[] = [segs[i][0], segs[i][1]];
    for (const dir of [1, -1]) {
      for (;;) {
        const tip = dir === 1 ? line[line.length - 1] : line[0];
        const next = (ends.get(key(tip)) ?? []).find((j) => !used[j]);
        if (next === undefined) break;
        used[next] = 1;
        const [a, b] = segs[next];
        const other = key(a) === key(tip) ? b : a;
        if (dir === 1) line.push(other); else line.unshift(other);
      }
    }
    lines.push(line);
  }
  return lines;
}

/**
 * Линия фронта по территории (rules.territory): граница клеток сторон 0 и 1
 * (марширующие квадраты по центрам клеток), сглаженная срезанием углов.
 */
export function territoryLine(theatre: Theatre, owner: ArrayLike<number>, smooth = 2): LngLat[][] {
  const { cols, rows } = theatre;
  const F = (c: number, r: number) => { const o = owner[r * cols + c]; return o === 0 ? 1 : o === 1 ? -1 : NaN; };
  const segs: [XY, XY][] = [];
  const mid = (a: XY, b: XY): XY => [(a[0] + b[0]) / 2, (a[1] + b[1]) / 2];
  for (let r = 0; r < rows - 1; r++) for (let c = 0; c < cols - 1; c++) {
    const v = [F(c, r), F(c + 1, r), F(c + 1, r + 1), F(c, r + 1)];
    if (v.some(Number.isNaN)) continue;
    const p = [theatre.cellCenter(c, r), theatre.cellCenter(c + 1, r), theatre.cellCenter(c + 1, r + 1), theatre.cellCenter(c, r + 1)];
    const cuts: XY[] = [];
    for (let k = 0; k < 4; k++) if ((v[k] > 0) !== (v[(k + 1) % 4] > 0)) cuts.push(mid(p[k], p[(k + 1) % 4]));
    if (cuts.length === 2) segs.push([cuts[0], cuts[1]]);
    else if (cuts.length === 4) { segs.push([cuts[0], cuts[1]]); segs.push([cuts[2], cuts[3]]); }
  }
  const chaikin = (l: XY[]): XY[] => {
    if (l.length < 3) return l;
    const out: XY[] = [l[0]];
    for (let i = 0; i < l.length - 1; i++) {
      const a = l[i], b = l[i + 1];
      out.push([a[0] * 0.75 + b[0] * 0.25, a[1] * 0.75 + b[1] * 0.25], [a[0] * 0.25 + b[0] * 0.75, a[1] * 0.25 + b[1] * 0.75]);
    }
    out.push(l[l.length - 1]);
    return out;
  };
  return joinSegments(segs, theatre.cellKm * 0.01).filter((l) => l.length >= 3).map((l) => {
    let q = l;
    for (let k = 0; k < smooth; k++) q = chaikin(q);
    return q.map((x) => theatre.proj.toLL(x));
  });
}

/**
 * Когда кончается игра: конечной даты нет — победа (событие истории случилось в игре, например Знамя
 * Победы над рейхстагом) или поражение (сторона человека потеряла боеспособность — численность ниже
 * доли от той, что была при передаче командования, — или предельный срок вышел).
 */
export interface GameEnd {
  victory: { event: string; title: string };
  defeat: { strengthBelow: number; deadline: string; deadlineText: string };
}

export interface GameRecord {
  version: 1;
  scenario: string;
  rules: string;
  seed: number;
  /** С какого хода командование у человека и модели. */
  takeover: string;
  /** Штаб модели ведёт тыл, переправы, резервы своей стороны (иначе они идут по историческому графику). */
  aiStaff?: boolean;
  human: string;
  ai: string;
  turns: GameTurn[];
  /** Игра на агентной модели (дивизии, ядро crates/agents-core): её сценарий, история и длина хода. */
  agents?: AgentGameSpec;
  /**
   * Данные из базы знаний на момент начала игры (редактор): собранные поправки нынешней модели, поправки ядра,
   * состояние при передаче командования. Восстановление игры идёт на них, а не на нынешней базе.
   */
  kb?: { compiled: unknown; core: unknown; takeoverState?: TakeoverState };
}

export interface GameState {
  state: SimState;
  /** Состояние на начало предыдущего хода (для итога суток). */
  prev: SimState | null;
  snapshots: Snapshot[];
}

export interface GameTurn {
  /** Начало хода — когда отданы приказы. */
  time: string;
  /** Приказы обеих сторон за этот ход. */
  orders: Order[];
  /** Распоряжения штаба человека: тыл, переправы, резервы. */
  actions?: StaffAction[];
  /** Поправки посредника на этот ход (модель-посредник); влияют на расчёт — поэтому в записи. */
  umpire?: UmpireMod[];
  /** Решение штаба человека (оценка, замысел, донесение) — для журнала и разбора; на расчёт не влияет. */
  human?: unknown;
  /** Сведения о решении штаба модели (оценка, замысел, риски, замеры) — для разбора; на расчёт не влияют. */
  ai?: unknown;
  /** Разбор посредника (оценка, отброшенные поправки, справки) — для разбора; на расчёт влияют только umpire. */
  umpireNote?: unknown;
  /** Обращения к модели-Ставке (поводы, ответ, директивы) — для журнала и разбора; директивы на расчёт — в actions. */
  stavka?: unknown;
}

/**
 * Состояние соединений на момент передачи командования по фактам базы знаний (абсолютные значения):
 * численность, танки, орудия, положение [долгота, широта], вышестоящий. Чего нет — остаётся рассчитанным.
 */
export type TakeoverState = Record<string, { personnel?: number; tanks?: number; guns?: number; position?: [number, number]; parent?: string }>;

/**
 * Наложить состояние при передаче на рассчитанное: численность — как есть; положение — только формированию на
 * карте (маршрут пересчитывается); вышестоящий — только существующий в сценарии. Неизвестные id и уничтоженные
 * соединения пропускаются (факт о численности выбывшего соединения его не возрождает).
 */
export function applyTakeoverState(s: SimState, ts: TakeoverState): SimState {
  const ids = new Set(s.formations.map((f) => f.id));
  const formations = s.formations.map((f) => {
    const t = ts[f.id];
    if (!t || f.destroyed) return f;
    const n = { ...f };
    for (const k of ['personnel', 'tanks', 'guns'] as const) if (typeof t[k] === 'number') n[k] = Math.max(0, t[k]!);
    if (t.position && onMap(f, s.time)) { n.position = [t.position[0], t.position[1]]; n.route = null; }
    if (t.parent && t.parent !== f.id && ids.has(t.parent)) n.parent = t.parent;
    return n;
  });
  return { ...s, formations };
}

export function gameOutcome(ctx: SimContext, history: History, g: GameState, end: GameEnd, human: string, baseStrength: number): GameOutcome | null {
  const ev = history.events?.find((e) => e.id === end.victory.event);
  if (ev) {
    const r = checkEvents(ctx, { final: g.state, snapshots: g.snapshots }, { ...history, events: [ev] })[0];
    if (r?.at) return { result: 'victory', text: `${end.victory.title} — ${r.simulated?.slice(8, 10)}.${r.simulated?.slice(5, 7)} (в истории ${ev.date.slice(8, 10)}.${ev.date.slice(5, 7)})`, at: r.at };
  }
  const k = baseStrength ? sideStrength(g.state, human) / baseStrength : 1;
  if (k < end.defeat.strengthBelow) return { result: 'defeat', text: `войска потеряли боеспособность: в строю ${Math.round(k * 100)} % численности на момент принятия командования`, at: g.state.time };
  if (g.state.time >= end.defeat.deadline) return { result: 'defeat', text: end.defeat.deadlineText, at: g.state.time };
  return null;
}

/** Ход: распоряжения штаба, приказы обеих сторон (с задержкой доведения по ступени) и расчёт арбитра. */
export function playTurn(ctx: SimContext, g: GameState, orders: Order[], actions: StaffAction[] = [], umpire: UmpireMod[] = []): GameState & { results: ReturnType<typeof applyActions>['results'] } {
  const a = applyActions(ctx, g.state, actions);
  const s = step({ ...orders.reduce(issueOrder, a.state), ...(umpire.length ? { umpire } : {}) }, ctx);
  return { state: s, prev: a.state, snapshots: [...g.snapshots, snapshotOf(s)], results: a.results };
}

/** Восстановить игру по записи. */
export function replayGame(ctx: SimContext, rec: GameRecord): GameState {
  let g: GameState = startGame(ctx, rec.seed, rec.takeover, rec.human, rec.aiStaff ? rec.ai : undefined, rec.kb?.takeoverState);
  for (const t of rec.turns) {
    if (t.time !== g.state.time) throw new Error(`запись игры не сходится: ход ${t.time}, расчёт ${g.state.time}`);
    g = playTurn(ctx, g, t.orders, t.actions ?? [], t.umpire ?? []);
  }
  return g;
}

/**
 * Прогнать сценарий по истории до хода takeover (ход, начинающийся не раньше этого времени) и снять будущие
 * исторические приказы. human — сторона человека: её будущие наводки переправ и прибытия резервов тоже сняты,
 * тыл — под управлением штаба (prepareTakeover). takeoverState — состояние соединений по фактам базы на этот момент
 * (applyTakeoverState).
 */
export function startGame(ctx: SimContext, seed: number, takeover: string, human?: string, aiStaff?: string, takeoverState?: TakeoverState): GameState {
  let s = createState(ctx, seed), prev: SimState | null = null;
  const snapshots = [snapshotOf(s)];
  while (s.time < takeover && s.time < ctx.scenario.end) {
    prev = s;
    s = step(s, ctx);
    snapshots.push(snapshotOf(s));
  }
  s = { ...s, pending: s.pending.filter((o) => o.issuedAt < s.time) };
  // состояние по фактам — и на карте момента передачи (последний снимок)
  if (takeoverState) { s = applyTakeoverState(s, takeoverState); snapshots[snapshots.length - 1] = snapshotOf(s); }
  // директивы с этого момента — по обстановке: вступившие по истории остаются, будущие ждут своего условия
  const done = Object.fromEntries((ctx.scenario.boundaries ?? []).filter((b) => b.trigger && b.from <= s.time).map((b) => [b.id, b.from]));
  s = { ...s, directives: { conditional: true, activated: done } };
  if (human) s = prepareTakeover(ctx, s, human);
  // штаб модели ведёт и тыл, переправы, резервы своей стороны (если включён при передаче командования)
  if (aiStaff) s = prepareTakeover(ctx, s, aiStaff);
  return { state: s, prev, snapshots };
}

export interface LocalProjection {
  toXY(ll: LngLat): XY;
  toLL(p: XY): LngLat;
}

/** Точка на ломаной на расстоянии d от начала и остаток пути. */
export function alongPath(path: XY[], d: number): { point: XY; rest: XY[] } {
  if (path.length < 2 || d <= 0) return { point: path[0], rest: path };
  let left = d;
  for (let i = 1; i < path.length; i++) {
    const seg = dist(path[i - 1], path[i]);
    if (left <= seg) {
      const p = lerp(path[i - 1], path[i], seg ? left / seg : 0);
      return { point: p, rest: [p, ...path.slice(i)] };
    }
    left -= seg;
  }
  const last = path[path.length - 1];
  return { point: last, rest: [last] };
}

export function centroid(ring: XY[]): XY {
  let x = 0, y = 0;
  for (const p of ring) { x += p[0]; y += p[1]; }
  return [x / ring.length, y / ring.length];
}

export function localProjection(center: LngLat): LocalProjection {
  const kx = 111.32 * Math.cos((center[1] * Math.PI) / 180), ky = 110.57;
  return {
    toXY: (ll) => [(ll[0] - center[0]) * kx, (ll[1] - center[1]) * ky],
    toLL: (p) => [center[0] + p[0] / kx, center[1] + p[1] / ky],
  };
}

/** Длина ломаной, км. */
export function pathLength(path: XY[]): number {
  let s = 0;
  for (let i = 1; i < path.length; i++) s += dist(path[i - 1], path[i]);
  return s;
}

export function pointInPolygon(p: XY, ring: XY[]): boolean {
  let inside = false;
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
    const [xi, yi] = ring[i], [xj, yj] = ring[j];
    if ((yi > p[1]) !== (yj > p[1]) && p[0] < ((xj - xi) * (p[1] - yi)) / (yj - yi) + xi) inside = !inside;
  }
  return inside;
}

export interface Deviation {
  formation: string;
  time: string;
  place: string;
  reliability: string;
  approxKm: number;
  /** Расстояние от расчётного положения до исторического, км. */
  km: number;
  /** Сверх неопределённости исторического положения, км (0 — в пределах). */
  excessKm: number;
}

export interface EventResult {
  id: string;
  title: string;
  historical: string;
  /** Дата в расчёте (null — не случилось). */
  simulated: string | null;
  /** Расхождение в сутках (+ — позже истории); null — не случилось. */
  days: number | null;
  /** Момент в расчёте (снимок после хода, когда событие уже случилось); null — не случилось. */
  at: string | null;
}

export interface History {
  scenario: string;
  positions: { formation: string; time: string; at: LngLat; approxKm: number; place: string; reliability: string; source: string }[];
  frontline: { time: string; sector: string; line: LngLat[] }[];
  /** Ключевые события с историческими датами — проверка «случилось ли и когда». */
  events?: HistoryEvent[];
  /** Документальные контрольные точки численности и потерь (из базы знаний) — сверка с расчётом (compareStrength). */
  checkpoints?: StrengthCheckpoint[];
}

export type HistoryEvent = { id: string; title: string; date: string; source?: string; marker?: EventMarker } & (
  | { kind: 'reach'; side: string; place: string; radiusKm: number; /** взято: в радиусе нет боеспособных частей противника */ control?: boolean }
  | { kind: 'cut'; formation?: string; formations?: string[] }
  | { kind: 'meet'; formations: string[]; place: string; radiusKm: number }
);

export interface RunResult {
  final: SimState;
  snapshots: Snapshot[];
}

/**
 * Сверка численности и потерь (допущения без опоры, norms.json: assume-strength-tolerance, assume-strength-weight):
 * точка в допуске — ошибка не больше STRENGTH_TOL от документа; в мерило калибровки и итог агентной модели сверка
 * входит с весом STRENGTH_WEIGHT, если точек не меньше STRENGTH_MIN_POINTS.
 */
export const STRENGTH_TOL = 0.25;

/** Снимок после хода: время и положения формирований на карте. */
export interface Snapshot {
  time: string;
  turn: number;
  /** path — путь за ход (по дорогам и улицам), если формирование шло не напрямик. */
  units: { id: string; at: LngLat; personnel: number; tanks: number; posture: string; destroyed: boolean; cutOff?: boolean; ammo?: number; path?: LngLat[] }[];
  /** Территория после хода (если правила её ведут). */
  territory?: number[];
}

/** Контрольная точка по документу: численность на момент at или накопленные потери за [from, at]. */
export type StrengthCheckpoint =
  | { at: string; formation: string; kind: 'strength'; personnel?: number; tanks?: number; guns?: number }
  /** накопленные потери за [from, at]: personnel — люди */
  | { at: string; formation: string; kind: 'losses'; from: string; personnel: number; tanks?: number };

export interface StrengthComparison {
  /** Сверено точек; доля в допуске; медиана относительной ошибки. */
  n: number;
  within: number;
  medianRel: number;
  /** По формированиям: точек, доля в допуске, медиана относительной ошибки. */
  byFormation: { key: string; n: number; within: number; medianRel: number }[];
}

/** Когда в расчёте произошли ключевые события (по снимкам и журналу). */
export function checkEvents(ctx: SimContext, run: RunResult, history: History): EventResult[] {
  const T = ctx.theatre;
  return (history.events ?? []).map((e) => {
    let when: string | null = null;
    if (e.kind === 'reach') {
      const c = T.area(e.place)?.center;
      const side = new Set(run.final.formations.filter((f) => f.side === e.side).map((f) => f.id));
      const near = (u: Snapshot['units'][number]) => !u.destroyed && dist(T.proj.toXY(u.at), T.proj.toXY(c!)) <= e.radiusKm;
      for (const s of run.snapshots.slice(1)) { // до начала сценария событие произойти не может
        if (c && s.units.some((u) => side.has(u.id) && near(u)) && !(e.control && s.units.some((u) => !side.has(u.id) && near(u)))) { when = s.time; break; }
      }
    } else if (e.kind === 'meet') {
      const c = T.area(e.place)?.center;
      for (const s of run.snapshots) {
        if (c && e.formations.every((id) => s.units.some((u) => u.id === id && !u.destroyed && dist(T.proj.toXY(u.at), T.proj.toXY(c)) <= e.radiusKm))) { when = s.time; break; }
      }
    } else {
      // окружено (или уничтожено) хотя бы одно из перечисленных
      const ids = new Set(e.formations ?? (e.formation ? [e.formation] : []));
      const j = run.final.journal.find((x) => (x.kind === 'encircled' && ids.has(x.formation) && x.cut) || ((x.kind === 'destroyed' || x.kind === 'capitulated') && ids.has(x.formation)));
      when = j ? j.time : null;
    }
    // снимок — на утро; событие «дня» — день перед ним
    const day = when ? addHours(when, -12).slice(0, 10) : null;
    const days = day ? Math.round((Date.parse(day) - Date.parse(e.date)) / 86400000) : null;
    return { id: e.id, title: e.title, historical: e.date, simulated: day, days, at: when };
  });
}

/**
 * Сверка численности и потерь с документами по снимкам прогона (снимок — первый не раньше момента точки).
 * strength — |расч − док| / док по людям; losses — накопленные потери расчёта за [from, at] (люди на from +
 * пополнения и полученное при выделении − выделенное из него − люди на at; дата без времени: at — конец дня, from — начало; from раньше начала — начало сценария) против документа. Точки вне
 * сценария, без людей в документе или без формирования на карте — не сверяются. В допуске — ошибка ≤ tol.
 */
export function compareStrength(ctx: SimContext, run: RunResult, history: History, tol = STRENGTH_TOL): StrengthComparison {
  const rows: { key: string; rel: number }[] = [];
  const last = addHours(ctx.scenario.end, 12);
  const unitAt = (time: string, id: string) => {
    for (const s of run.snapshots) if (s.time >= time) { const u = s.units.find((x) => x.id === id); if (u) return { time: s.time, u }; }
    return null;
  };
  // дата без времени (из базы знаний): at — конец дня (00:00 следующего), from — начало дня
  const dateOnly = (t: string) => t.length <= 10;
  for (const c of history.checkpoints ?? []) {
    const cAt = dateOnly(c.at) ? addHours(`${c.at}T00:00`, 24) : c.at;
    if (!c.personnel || c.personnel <= 0 || cAt < ctx.scenario.start || cAt > last) continue;
    const b = unitAt(cAt, c.formation);
    if (!b) continue;
    let sim: number;
    if (c.kind === 'strength') sim = b.u.personnel;
    else {
      // потери от начала сценария, если документ считает раньше; резерв — с его ввода
      const from = dateOnly(c.from) ? `${c.from}T00:00` : c.from;
      const a = unitAt(from > ctx.scenario.start ? from : ctx.scenario.start, c.formation);
      if (!a || a.time >= b.time) continue;
      // журнал хода t отражён в снимках после t: учитываем записи a.time ≤ t < b.time
      let inflow = 0;
      for (const j of run.final.journal) {
        if (j.time < a.time || j.time >= b.time) continue;
        if (j.kind === 'reinforced' && j.formation === c.formation) inflow += j.personnel;
        else if (j.kind === 'detached' && j.from === c.formation) inflow -= j.personnel;
        else if (j.kind === 'detached' && j.formation === c.formation) inflow += j.personnel; // выделено при вводе — приход
      }
      sim = a.u.personnel + inflow - b.u.personnel;
    }
    rows.push({ key: c.formation, rel: Math.abs(sim - c.personnel) / c.personnel });
  }
  const med = (a: number[]) => { const s = [...a].sort((x, y) => x - y); return s.length ? s[Math.floor(s.length / 2)] : 0; };
  const share = (l: { rel: number }[]) => l.filter((r) => r.rel <= tol).length / Math.max(1, l.length);
  const by = new Map<string, number[]>();
  for (const r of rows) by.set(r.key, [...(by.get(r.key) ?? []), r.rel]);
  return {
    n: rows.length,
    within: +share(rows).toFixed(3),
    medianRel: +med(rows.map((r) => r.rel)).toFixed(3),
    byFormation: [...by.entries()].map(([key, l]) => ({ key, n: l.length, within: +share(l.map((rel) => ({ rel }))).toFixed(3), medianRel: +med(l).toFixed(3) })),
  };
}

/**
 * Сравнить снимки с историческими положениями. Историческое положение «за день»
 * (вечер) сравнивается с первым снимком не раньше его времени.
 */
export function compareWithHistory(ctx: SimContext, run: RunResult, history: History): Deviation[] {
  const T = ctx.theatre;
  const out: Deviation[] = [];
  for (const h of history.positions) {
    if (h.time <= ctx.scenario.start || h.time > addHours(ctx.scenario.end, 12)) continue;
    const s = run.snapshots.find((x) => x.time >= h.time);
    const u = s?.units.find((x) => x.id === h.formation);
    if (!s || !u || u.destroyed) continue;
    const km = dist(T.proj.toXY(u.at), T.proj.toXY(h.at));
    out.push({ formation: h.formation, time: h.time, place: h.place, reliability: h.reliability, approxKm: h.approxKm, km: +km.toFixed(1), excessKm: +Math.max(0, km - h.approxKm).toFixed(1) });
  }
  return out;
}

/** Прогнать сценарий от начала до конца (или maxTurns ходов). */
export function runScenario(ctx: SimContext, seed = 1, maxTurns = Infinity): RunResult {
  let s = createState(ctx, seed);
  const snapshots = [snapshotOf(s)];
  while (s.time < ctx.scenario.end && s.turn < maxTurns) {
    s = step(s, ctx);
    snapshots.push(snapshotOf(s));
  }
  return { final: s, snapshots };
}

/** Снимок состояния после хода. */
export const snapshotOf = (s: SimState): Snapshot => {
  // пути за ход — из записей журнала о движении (бой, затем марш — склеиваются)
  const paths = new Map<string, LngLat[]>();
  for (const j of s.journal) if (j.kind === 'move') {
    const seg = j.path ?? [j.from, j.to];
    const cur = paths.get(j.formation);
    paths.set(j.formation, cur ? [...cur, ...seg.slice(1)] : seg);
  }
  return {
  time: s.time, turn: s.turn,
  units: s.formations.filter((f) => onMap(f, s.time) || f.destroyed).map((f) => { const p = paths.get(f.id); return { id: f.id, at: f.position, personnel: f.personnel, tanks: f.tanks, posture: f.posture, destroyed: f.destroyed, ...(f.cutOff ? { cutOff: true } : {}), ammo: +f.ammo.toFixed(2), ...(p && p.length > 2 ? { path: p } : {}) }; }),
  ...(s.territory ? { territory: s.territory } : {}),
  };
};

/** Сводка: средние и медианные отклонения, доля в пределах допуска. */
export function summarize(devs: Deviation[], toleranceKm = 10) {
  const med = (a: number[]) => { const b = [...a].sort((x, y) => x - y); return b.length ? b[Math.floor(b.length / 2)] : 0; };
  const by = <K extends string>(key: (d: Deviation) => K) => {
    const m = new Map<K, Deviation[]>();
    for (const d of devs) m.set(key(d), [...(m.get(key(d)) ?? []), d]);
    return [...m.entries()].map(([k, l]) => ({ key: k, n: l.length, meanKm: +(l.reduce((s, d) => s + d.km, 0) / l.length).toFixed(1), medianExcessKm: med(l.map((d) => d.excessKm)), within: +(l.filter((d) => d.excessKm <= toleranceKm).length / l.length).toFixed(2) }));
  };
  return {
    n: devs.length,
    within: +(devs.filter((d) => d.excessKm <= toleranceKm).length / Math.max(1, devs.length)).toFixed(2),
    medianExcessKm: med(devs.map((d) => d.excessKm)),
    byFormation: by((d) => d.formation),
    byDay: by((d) => d.time.slice(0, 10)),
  };
}

export const INFRA_STATE_RU: Record<InfraState, string> = {
  destroyed: 'разрушен', damaged: 'повреждён', intact: 'цел', built: 'наведён/построен', repaired: 'восстановлен',
  blocked: 'перекрыт', mined: 'заминирован', impassable: 'непроходим', fortified: 'укреплён',
};

export interface InfraRecord {
  id: string;
  kind: InfraKind;
  state: InfraState;
  /** Что это словами: «мост через Шпрее у Фюрстенвальде». */
  title: string;
  /** Пункт, у которого объект (как в тексте, в именительном падеже). */
  place?: string;
  river?: string;
  /** С какого момента (ГГГГ-ММ-ДД или ГГГГ-ММ-ДДTчч:мм); нет — с начала операции. */
  from?: string | null;
  until?: string | null;
  /** Чьими силами (разрушен, наведён): id стороны. */
  side?: string | null;
  /** Привязка к театру: мост театра, точка, радиус (для дорог). */
  bridge?: string;
  at?: LngLat;
  radiusKm?: number;
  note?: string;
  source?: { doc?: string; docName?: string; quote?: string; reliability?: string };
  origin: 'document' | 'user';
  added?: string;
}

/** Театр с учётом сведений об инфраструктуре (исходный не меняется). */
export function applyInfrastructure(T: TheatreData, records: InfraRecord[] | undefined): TheatreData {
  if (!records?.length) return T;
  const bridges = T.bridges.map((b) => ({ ...b }));
  const obstacles = [...(T.obstacles ?? [])];
  for (const r of records) {
    if (!infraEffect(r)) {
      if (r.kind === 'rail' && r.at && ['destroyed', 'blocked', 'mined', 'impassable'].includes(r.state)) obstacles.push({ id: `infra-${r.id}`, at: r.at, radiusKm: r.radiusKm ?? 1.5, kind: 'rail', from: t(r.from), until: t(r.until), note: r.title });
      continue;
    }
    const b = r.bridge ? bridges.find((x) => x.id === r.bridge) : undefined;
    if (r.kind === 'road') { obstacles.push({ id: `infra-${r.id}`, at: r.at!, radiusKm: r.radiusKm ?? 1.5, kind: 'road', from: t(r.from), until: t(r.until), note: r.title }); continue; }
    if (r.state === 'destroyed' && b) {
      const at = t(r.from) ?? '0000-01-01T00:00';
      if (!b.destroyedAt || at < b.destroyedAt) b.destroyedAt = at;
    } else if (r.state === 'intact' && b && r.kind === 'bridge') {
      b.destroyedAt = t(r.until);
    } else {
      const at = r.at ?? b?.at;
      if (at) bridges.push({ id: `infra-${r.id}`, at, name: r.title, openFrom: t(r.from), destroyedAt: t(r.until), ...(r.side ? { side: r.side } : {}), kind: r.kind === 'crossing' ? 'ferry' : 'bridge' });
    }
  }
  return { ...T, bridges, obstacles, sources: [...(T.sources ?? []), `Сведения об инфраструктуре операции: ${records.length}`] };
}

/** Немецкое название — как его пишут по-русски (приблизительно): Fuerstenwalde → фюрстенвальде, Seelow → зелов. */
export function deToRu(name: string): string {
  let x = name.toLowerCase().replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue').replace(/ß/g, 'ss');
  x = x.replace(/\bst/g, 'шт').replace(/\bsp/g, 'шп');
  const R: [RegExp, string][] = [[/tsch/g, 'ч'], [/sch/g, 'ш'], [/ch/g, 'х'], [/ck/g, 'к'], [/ei/g, 'ай'], [/(eu|aeu)/g, 'ой'], [/ie/g, 'и'], [/ue/g, 'ю'], [/oe/g, 'ё'], [/ae/g, 'е'], [/ee/g, 'е'], [/tz/g, 'ц'], [/qu/g, 'кв'], [/ph/g, 'ф'], [/th/g, 'т'],
    [/([aeiou])h/g, '$1'], [/s(?=[aeiouy])/g, 'з'], [/l(?=[^aeiouy]|$)/g, 'ль']];
  for (const [re, v] of R) x = x.replace(re, v);
  const M: Record<string, string> = { a: 'а', b: 'б', c: 'ц', d: 'д', e: 'е', f: 'ф', g: 'г', h: 'х', i: 'и', j: 'й', k: 'к', l: 'л', m: 'м', n: 'н', o: 'о', p: 'п', r: 'р', s: 'с', t: 'т', u: 'у', v: 'ф', w: 'в', x: 'кс', y: 'и', z: 'ц' };
  return x.replace(/[a-z]/g, (c) => M[c] ?? c).replace(/(.)\1+/g, '$1');
}

/** Что сведение меняет в расчёте (словами); null — в расчёт не входит. */
export function infraEffect(r: InfraRecord): string | null {
  const from = r.from ? ` с ${ru(r.from)}` : ' с начала операции', until = r.until ? ` до ${ru(r.until)}` : '';
  if (r.kind === 'bridge' || r.kind === 'crossing') {
    if (r.state === 'destroyed' && r.bridge) return `мост не действует${from}${until}`;
    if ((r.state === 'built' || r.state === 'repaired' || (r.kind === 'crossing' && r.state === 'intact')) && (r.at || r.bridge)) return `${r.kind === 'crossing' ? 'переправа' : 'мост'} действует${from}${until}`;
    if (r.state === 'intact' && r.bridge) return `мост цел${from}${until} — разрушение в театре снимается`;
    return null;
  }
  if (r.kind === 'road' && ['destroyed', 'blocked', 'mined', 'impassable'].includes(r.state) && r.at) return `дорога в радиусе ${(r.radiusKm ?? 1.5).toFixed(1)} км не даёт дорожного темпа${from}${until}`;
  return null;
}

/** Пункт театра по названию (по-русски или в оригинале, с точностью до падежа). */
export function locatePlace(T: Theatre, name?: string): { id: string; title: string; at: LngLat; radiusKm: number } | null {
  if (!name?.trim()) return null;
  const want = variants(name);
  for (const a of T.data.areas) {
    const names = [a.name, areaOriginal(a.name), deToRu(areaOriginal(a.name).split(/[ ,]/)[0]), ...variants(areaTitle(a.name))];
    if (!names.some((n) => want.some((w) => sameName(n, w)))) continue;
    const ar = T.area(a.id);
    if (!ar) continue;
    const c = T.proj.toXY(ar.center);
    const r = Math.max(...ar.ring.map((p) => dist(T.proj.toXY(p), c)));
    return { id: a.id, title: areaTitle(a.name), at: ar.center, radiusKm: Math.min(3, Math.max(0.5, r * 0.6)) };
  }
  return null;
}

/**
 * Привязать сведение к театру: мост — ближайший мост театра у пункта (на той же реке, если она названа);
 * наведённая переправа — точка на ближайшей реке у пункта; дорога — круг у пункта. null — не нашли.
 */
export function resolveInfra(T: Theatre, r: Pick<InfraRecord, 'kind' | 'state' | 'place' | 'river' | 'title'>): InfraResolution | null {
  const p = locatePlace(T, r.place);
  const rivers = riverNames(r.river);
  if (r.kind === 'bridge' || r.kind === 'crossing') {
    // мост по названию («мост Мольтке») — среди мостов театра
    // река названа — мост театра на другой реке не подходит («Ганза-мост через Одер» — не берлинский Hansabrücke на Шпрее)
    const onRiver = (b: { river?: string }) => !rivers.length || !b.river || rivers.some((n) => sameName(n, b.river!));
    const named = T.data.bridges.find((b) => b.name && variants(r.title).some((t) => norm(t).length > 6 && norm(b.name!).includes(norm(t))) && onRiver(b as { river?: string }));
    if (named) return { bridge: named.id, at: named.at, how: `мост театра «${named.name}»` };
    if (!p) return null;
    const c = T.proj.toXY(p.at);
    const near = T.data.bridges
      .map((b) => ({ b, d: dist(T.proj.toXY(b.at), c) }))
      .filter((x) => x.d <= Math.max(5, p.radiusKm * 2) && (!rivers.length || !(x.b as { river?: string }).river || rivers.some((n) => sameName(n, (x.b as { river?: string }).river!))))
      .sort((a, b) => a.d - b.d)[0];
    const fresh = r.state === 'built' || (r.kind === 'crossing' && r.state !== 'destroyed');
    if (near && !fresh) return { bridge: near.b.id, at: near.b.at, how: `мост театра «${near.b.name ?? near.b.id}», ${near.d.toFixed(1)} км от пункта ${p.title}` };
    if (fresh || r.state === 'repaired') {
      const rv = T.nearestRiver(p.at, Math.max(6, p.radiusKm * 2));
      if (rv) return { at: rv.at, how: `точка на реке у пункта ${p.title}` };
    }
    if (near) return { bridge: near.b.id, at: near.b.at, how: `мост театра «${near.b.name ?? near.b.id}» у пункта ${p.title}` };
    // пункт есть, а моста театра рядом нет — разрушать нечего (сведение остаётся)
    return { at: p.at, how: `у пункта ${p.title} мостов театра${rivers.length ? ` через ${r.river}` : ''} нет` };
  }
  if (r.kind === 'road' || r.kind === 'rail') return p ? { at: p.at, radiusKm: p.radiusKm, how: `у пункта ${p.title}, радиус ${p.radiusKm.toFixed(1)} км` } : null;
  return p ? { at: p.at, how: `пункт ${p.title}` } : null;
}

function riverNames(river?: string): string[] {
  if (!river) return [];
  const out = variants(river);
  for (const v of [...out]) { const k = Object.keys(RIVERS).find((r) => norm(v).startsWith(r)); if (k) out.push(RIVERS[k]); }
  return out;
}

export interface Norm {
  id: string; title: string; kb: string; source: string; reliability: string; historical: string;
  measure: { kind: 'pace'; scenario: string; formation: string; from: string; to: string }
    | { kind: 'loss'; scenario: string; parent: string; from: string; to: string }
    | { kind: 'param'; expr: string }
    | { kind: 'frontage'; scenario: string; side: string; echelon: string }
    | { kind: 'unmodelled'; why: string }
    /** Допущение модели: правило есть, опоры в опыте войны нет — показывается значение и чего не хватает. */
    | { kind: 'assumption'; expr: string; why: string };
  expect?: [number, number]; unit?: string; rules: string[]; note?: string;
  /** Операции, к которым относится норматив (для покрытия), если в замере нет сценария. */
  operations?: string[];
}

/**
 * Оценить нормативы. ctxOf — контекст сценария (для правил — любой, по умолчанию Берлинской операции);
 * runsOf — прогоны сценария (несколько seed — среднее и разброс).
 */
export function evaluateNorms(t: NormTable, ctxOf: (scenario: string) => SimContext, runsOf: (scenario: string) => RunResult[], paramScenario = 'berlin-1945-tasks'): NormResult[] {
  const out: NormResult[] = [];
  for (const n of t.norms) {
    const m = n.measure;
    let values: number[] = [];
    try {
      if (m.kind === 'unmodelled') { out.push({ norm: n, values, mean: null, verdict: 'none', text: `не моделируется: ${m.why}` }); continue; }
      if (m.kind === 'assumption') { const v = measureParam(ctxOf(paramScenario), m.expr); if (!Number.isFinite(v)) { out.push({ norm: n, values: [], mean: null, verdict: 'none', text: `не включено в правилах: ${m.why}` }); continue; } out.push({ norm: n, values: [v], mean: v, verdict: 'assumed', text: `${fmt(v)} ${n.unit ?? ''} — ${m.why}` }); continue; }
      values = m.kind === 'pace' ? runsOf(m.scenario).map((r) => measurePace(ctxOf(m.scenario), r, m))
        : m.kind === 'loss' ? runsOf(m.scenario).map((r) => measureLoss(ctxOf(m.scenario), r, m))
        : m.kind === 'frontage' ? measureFrontage(ctxOf(m.scenario), m)
        : [measureParam(ctxOf(paramScenario), m.expr)];
    } catch (e) { out.push({ norm: n, values, mean: null, verdict: 'error', text: (e as Error).message }); continue; }
    const ok = values.filter(Number.isFinite);
    if (!ok.length) { out.push({ norm: n, values, mean: null, verdict: 'error', text: 'нет данных (формирования нет на карте в эти дни)' }); continue; }
    const mean = ok.reduce((a, b) => a + b, 0) / ok.length;
    const [lo, hi] = n.expect!;
    const spread = ok.length > 1 ? ` (${fmt(Math.min(...ok))}–${fmt(Math.max(...ok))})` : '';
    out.push({ norm: n, values: ok, mean, verdict: mean < lo ? 'low' : mean > hi ? 'high' : 'ok', text: `${fmt(mean)}${spread} ${n.unit}` });
  }
  return out;
}

export function measureFrontage(ctx: SimContext, m: Extract<Norm['measure'], { kind: 'frontage' }>): number[] {
  const P = profileOf(ctx, m.side);
  return ctx.scenario.formations.filter((f) => f.side === m.side && f.echelon === m.echelon).map((f) => (f.type ? P.unitTypes[f.type]?.frontageKm : undefined) ?? NaN).filter(Number.isFinite);
}

/** Потери подчинённых (по цепочке подчинённости) за период, % численности (прибывшие позже — с момента прибытия). */
export function measureLoss(ctx: SimContext, r: RunResult, m: Extract<Norm['measure'], { kind: 'loss' }>): number {
  const parent = new Map(ctx.scenario.formations.map((f) => [f.id, f.parent ?? null]));
  const under = (id: string): boolean => { for (let p = parent.get(id); p; p = parent.get(p)) if (p === m.parent) return true; return false; };
  const inWin = r.snapshots.filter((s) => s.time >= m.from && s.time <= m.to);
  let start = 0, end = 0;
  for (const id of new Set(inWin.flatMap((s) => s.units.map((u) => u.id)))) {
    if (!under(id)) continue;
    const seen = inWin.filter((s) => s.units.some((u) => u.id === id));
    const p0 = seen[0].units.find((u) => u.id === id)!.personnel;
    // сдавшиеся и уничтоженные — потеряны целиком (численность на знаке остаётся последней)
    const u1 = seen[seen.length - 1].units.find((u) => u.id === id)!;
    const p1 = u1.destroyed ? 0 : u1.personnel;
    start += p0; end += Math.min(p0, p1);
  }
  return start ? ((start - end) / start) * 100 : NaN;
}

/** Темп: смещение формирования между двумя моментами по прямой (как в источниках), км/сут. */
export function measurePace(ctx: SimContext, r: RunResult, m: Extract<Norm['measure'], { kind: 'pace' }>): number {
  const a = snapAt(r, m.from).units.find((u) => u.id === m.formation);
  const b = snapAt(r, m.to).units.find((u) => u.id === m.formation);
  if (!a || !b) return NaN;
  return dist(ctx.theatre.proj.toXY(a.at), ctx.theatre.proj.toXY(b.at)) / days(m.from, m.to);
}

/** Число из правил и профиля советской стороны (немецкой — где сказано). */
export function measureParam(ctx: SimContext, expr: string): number {
  const R = ctx.rules, su = profileOf(ctx, 'su');
  const eng = su.engineering ?? ENGINEERING;
  const EN = R.engineers === false ? undefined : R.engineers;
  switch (expr) {
    case 'stockDays.fortress': return profileOf(ctx, 'de').unitTypes.fortress?.stockDays ?? NaN;
    case 'pocket.breakoutKeep%': return (R.pocket?.breakoutKeep ?? 0.3) * 100;
    case 'pocket.capitulateHours': return R.pocket?.capitulateHours ?? 96;
    case 'territory.consolidateKm': return R.territory?.consolidateKm ?? R.contactKm * 1.5;
    case 'engineers.hours': return R.engineers === false ? NaN : EN?.hours ?? 24;
    case 'foot.road': return su.road.foot * (R.movementScale ?? 1);
    case 'foot.open': return su.offRoad.foot.open * (R.movementScale ?? 1);
    case 'supplyFlow.fullHours': return R.supplyFlow ? R.supplyFlow.fullHours ?? 12 : NaN;
    case 'beltBreachKm': return R.beltBreachKm ? R.beltBreachKm : NaN;
    case 'followParentKm': return R.followParentKm ? R.followParentKm : NaN;
    case 'strength.tolerance%': return STRENGTH_TOL * 100;
    case 'strength.weight%': return STRENGTH_WEIGHT * 100;
    case 'supplyFlow.fuelPer100km': return R.supplyFlow ? R.supplyFlow.fuelPer100km ?? 1 : NaN;
    // пороги правдоподобия проверок базы знаний (packages/knowledge/src/checks.ts, PLAUSIBLE) — допущения без опоры
    case 'plausible.division': return 20000;
    case 'plausible.lossesShare%': return 100;
    case 'plausible.dailyLossShare%': return 100 / 3;
    case 'plausible.parentSteps': return 1;
    case 'plausible.reinforceShare%': return 50;
    case 'advanceMax': return interp(R.advance, 10);
    case 'riverCrossHours': return R.riverCrossHours;
    case 'riverCrossHours/3': return R.riverCrossHours / 3;
    case 'bridgeHoursMajor': return eng.bridgeHoursMajor;
    case 'bridgeHoursMinor': return eng.bridgeHoursMinor;
    default: {
      const d = /^orderDelay\.(\w+)$/.exec(expr);
      if (d) return (su.orderDelayHours as Record<string, number>)[d[1]] ?? NaN;
      // множитель режима: нет блока regimes — режимы не включены
      const rg = /^regimes\.(\w+)\.(\w+)$/.exec(expr);
      if (rg) return R.regimes ? (R.regimes as Record<string, Record<string, number>>)[rg[1]]?.[rg[2]] ?? 1 : NaN;
      throw new Error(`неизвестное выражение ${expr}`);
    }
  }
}

/** Запись каталога переигровки: название, допуск сравнения, наборы правил, условия окончания игры. */
export interface CatalogEntry {
  id: string;
  title: string;
  detail: string;
  toleranceKm: number;
  rules: { id: string; title: string }[];
  game?: { victory: { event: string; title: string }; defeat: { strengthBelow: number; deadline: string; deadlineText: string } };
}

/** Настройки штаба на модели и советника (как services/staff/live/<сценарий>.json). */
export interface LiveSetup {
  scenario: string; side: string; sideName: string; profile: string; description: string; role: string; higher: string;
  constraints: string[]; anchor: string; anchorName: string;
  advisor?: { side: string; sideName: string; profile: string; role: string; anchor: string; anchorName: string };
}

export interface OperationPackage {
  scenario: Scenario;
  theatre: TheatreData;
  history: History;
  sectors?: { sectors: { id: string; title: string; bbox: [number, number, number, number] }[] };
  live?: LiveSetup;
  catalog?: CatalogEntry;
  rules?: Rules[];
  profiles?: SideProfile[];
  /** Сведения о состоянии инфраструктуры (мосты, переправы, дороги) — поверх театра. */
  infrastructure?: InfraRecord[];
}

/** Запись каталога по умолчанию. */
export function defaultCatalog(pkg: OperationPackage): CatalogEntry {
  const S = pkg.scenario, ev = pkg.history.events ?? [];
  const last = ev[ev.length - 1];
  const deadline = new Date(Date.parse(S.end + 'Z') + 10 * 86400_000).toISOString().slice(0, 16);
  return {
    id: S.id,
    title: S.name,
    detail: `${S.formations.filter((f) => f.type && f.position).length} формирований, клетка ${pkg.theatre.cellKm} км, ход ${S.turnHours} ч`,
    toleranceKm: pkg.theatre.cellKm <= 0.5 ? 2 : 10,
    rules: [{ id: S.rules, title: `правила сценария (${S.rules})` }],
    ...(last ? { game: { victory: { event: last.id, title: last.title }, defeat: { strengthBelow: 0.35, deadline, deadlineText: `цель не достигнута к ${deadline.slice(8, 10)}.${deadline.slice(5, 7)}` } } } : {}),
  };
}

/** Настройки штаба модели и советника по умолчанию: модель — вторая сторона, человек — первая. */
export function defaultLive(pkg: OperationPackage): LiveSetup {
  const S = pkg.scenario, T = pkg.theatre;
  const [human, ai] = S.sides;
  // опорный пункт — район в центре театра
  const cx = (T.bbox[0] + T.bbox[2]) / 2, cy = (T.bbox[1] + T.bbox[3]) / 2;
  const center = (r: [number, number][]) => r.reduce((a, p) => [a[0] + p[0] / r.length, a[1] + p[1] / r.length], [0, 0]);
  const anchor = [...T.areas].sort((a, b) => { const p = center(a.ring), q = center(b.ring); return Math.hypot(p[0] - cx, p[1] - cy) - Math.hypot(q[0] - cx, q[1] - cy); })[0];
  return {
    scenario: S.id, side: ai.id, sideName: ai.name, profile: ai.profile,
    description: `переигровка: ${S.name}`,
    role: `командующий войсками стороны «${ai.name}» в операции`,
    higher: 'верховное командование',
    constraints: [],
    anchor: anchor?.id ?? '', anchorName: anchor ? areaTitle(anchor.name) : '',
    advisor: { side: human.id, sideName: human.name, profile: human.profile, role: `начальник оперативного отдела штаба стороны «${human.name}»`, anchor: anchor?.id ?? '', anchorName: anchor ? areaTitle(anchor.name) : '' },
  };
}

/** Какой это файл пакета — по полям. */
export function detectPart(j: unknown): keyof OperationPackage | 'bundle' | null {
  if (!j || typeof j !== 'object') return null;
  const o = j as Record<string, unknown>;
  if (o.scenario && typeof o.scenario === 'object' && o.theatre && o.history) return 'bundle';
  if (Array.isArray(o.formations) && Array.isArray(o.sides)) return 'scenario';
  if (Array.isArray(o.areas) && o.bbox && o.cellKm) return 'theatre';
  if (Array.isArray(o.positions) && Array.isArray(o.frontline)) return 'history';
  if (Array.isArray(o.sectors)) return 'sectors';
  if (typeof o.side === 'string' && typeof o.role === 'string' && typeof o.anchor === 'string') return 'live';
  if (Array.isArray(o.advance) && Array.isArray(o.attackerLoss)) return 'rules';
  if (o.weights && o.unitTypes) return 'profiles';
  if (typeof o.toleranceKm === 'number' && Array.isArray(o.rules)) return 'catalog';
  return null;
}

/**
 * Проверить пакет. known — что уже есть в системе (id правил и профилей), чтобы ссылки на них не считать ошибкой.
 */
export function validateOperation(pkg: Partial<OperationPackage>, known: { rules: string[]; profiles: string[] }): PackageIssue[] {
  const I: PackageIssue[] = [];
  const err = (part: PackageIssue['part'], text: string) => I.push({ level: 'error', part, text });
  const warn = (part: PackageIssue['part'], text: string) => I.push({ level: 'warning', part, text });
  const info = (part: PackageIssue['part'], text: string) => I.push({ level: 'info', part, text });
  const { scenario: S, theatre: T, history: H } = pkg;
  if (!S) err('сценарий', 'нет файла сценария (стороны, формирования, приказы, сроки)');
  if (!T) err('театр', 'нет файла театра (местность, дороги, реки, районы)');
  if (!H) err('история', 'нет файла истории (положения по дням, линия фронта, ключевые события)');
  if (!S || !T || !H) return I;

  // сценарий
  if (!S.id || !/^[a-z0-9][a-z0-9-]*$/.test(S.id)) err('сценарий', `id «${S.id}» — нужны латинские строчные буквы, цифры и дефис`);
  if (!(Date.parse(S.start) < Date.parse(S.end))) err('сценарий', `сроки: начало ${S.start} должно быть раньше конца ${S.end}`);
  if (!(S.turnHours > 0)) err('сценарий', 'длительность хода (turnHours) должна быть больше нуля');
  if (S.theatre !== T.id) err('сценарий', `сценарий ссылается на театр «${S.theatre}», а загружен «${T.id}»`);
  if ((S.sides ?? []).length < 2) err('сценарий', 'сторон должно быть не меньше двух');
  const profiles = new Map((pkg.profiles ?? []).map((p) => [p.id, p]));
  for (const s of S.sides ?? []) if (!profiles.has(s.profile) && !known.profiles.includes(s.profile)) err('сценарий', `сторона «${s.name}»: нет профиля «${s.profile}» (есть: ${[...known.profiles, ...profiles.keys()].join(', ')})`);
  const ruleIds = [...known.rules, ...(pkg.rules ?? []).map((r) => r.id)];
  if (!ruleIds.includes(S.rules)) err('сценарий', `правила «${S.rules}» не найдены (есть: ${ruleIds.join(', ')})`);
  const areas = new Set(T.areas.map((a) => a.id));
  const sides = new Set((S.sides ?? []).map((s) => s.id));
  const ids = new Set<string>();
  let outside = 0, noType = 0;
  for (const f of S.formations ?? []) {
    if (ids.has(f.id)) err('сценарий', `формирование «${f.id}» встречается дважды`);
    ids.add(f.id);
    if (!sides.has(f.side)) err('сценарий', `${f.name}: сторона «${f.side}» не описана`);
    if (f.position && !inBox(T.bbox, f.position)) outside++;
    const prof = profiles.get(S.sides.find((s) => s.id === f.side)?.profile ?? '');
    if (f.type && prof && !prof.unitTypes[f.type]) noType++;
  }
  for (const f of S.formations ?? []) if (f.parent && !ids.has(f.parent)) warn('сценарий', `${f.name}: вышестоящий «${f.parent}» не найден`);
  // стратегический уровень карты собирает войска по фронтам (группам армий): без такого вышестоящего — отдельно
  const byIdF = new Map((S.formations ?? []).map((f) => [f.id, f]));
  const noFront = (S.formations ?? []).filter((f) => f.echelon !== 'front' && (f.type || f.echelon === 'army') && !f.parent).map((f) => f.name);
  const top = (S.formations ?? []).filter((f) => f.echelon === 'army' && (() => { let p = f.parent ? byIdF.get(f.parent) : undefined; for (let k = 0; p && k < 6; k++) { if (p.echelon === 'front') return false; p = p.parent ? byIdF.get(p.parent) : undefined; } return true; })()).map((f) => f.name);
  const loose = [...new Set([...noFront, ...top])];
  if (loose.length) warn('сценарий', `без вышестоящего фронта (группы армий): ${loose.slice(0, 6).join(', ')}${loose.length > 6 ? ` и ещё ${loose.length - 6}` : ''} — на стратегическом уровне карты покажутся отдельно; укажите parent (например, узел ОКВ или Ставки с echelon «front»)`);
  if (outside) warn('сценарий', `формирований вне театра: ${outside}`);
  if (noType) warn('сценарий', `формирований с типом, которого нет в профиле стороны: ${noType}`);
  const active = (S.formations ?? []).filter((f) => f.type && f.position);
  if (!active.length) err('сценарий', 'нет действующих формирований (с типом и положением)');
  let badOrders = 0;
  for (const o of S.orders ?? []) {
    if (!ids.has(o.formation)) badOrders++;
    else if (typeof o.target === 'string' && !areas.has(o.target)) badOrders++;
  }
  if (badOrders) warn('сценарий', `приказов с неизвестным формированием или районом: ${badOrders} (не будут исполнены)`);
  for (const [side, sp] of Object.entries(S.supply ?? {})) for (const src of sp.sources) if (typeof src === 'string' && !areas.has(src)) warn('сценарий', `снабжение стороны ${side}: район «${src}» не найден в театре`);
  if (!S.supply) info('сценарий', 'источники снабжения не заданы — снабжение без подвоза');

  // театр
  if (!(T.cellKm > 0)) err('театр', 'шаг сетки (cellKm) должен быть больше нуля');
  if (!(T.bbox[0] < T.bbox[2] && T.bbox[1] < T.bbox[3])) err('театр', 'границы (bbox) заданы неверно');
  if (!T.terrainGrid && !T.terrain?.length) warn('театр', 'нет растра местности — вся местность будет «по умолчанию»');
  if (!T.areas.length) err('театр', 'нет районов — приказам и событиям не на что ссылаться');
  if (!T.rivers?.length) info('театр', 'рек нет');
  if (!T.roads?.length && !T.roadGrid) warn('театр', 'дорог нет — марш только вне дорог');

  // история
  if (H.scenario && H.scenario !== S.id) warn('история', `история помечена для сценария «${H.scenario}»`);
  const inPeriod = H.positions.filter((p) => p.time > S.start && p.time <= S.end && ids.has(p.formation));
  if (!inPeriod.length) err('история', 'нет исторических положений формирований сценария в его сроки — сравнивать не с чем');
  else info('история', `положений для сравнения: ${inPeriod.length}, формирований: ${new Set(inPeriod.map((p) => p.formation)).size}`);
  const unknownPos = H.positions.filter((p) => !ids.has(p.formation)).length;
  if (unknownPos) warn('история', `положений неизвестных формирований: ${unknownPos} (пропускаются)`);
  const events = H.events ?? [];
  if (!events.length) warn('история', 'нет ключевых событий — не по чему сверять даты и нечем задать победу');
  for (const e of events) {
    if ('place' in e && !areas.has(e.place)) err('история', `событие «${e.title}»: район «${e.place}» не найден в театре`);
    const fs = 'formations' in e && e.formations ? e.formations : 'formation' in e && e.formation ? [e.formation] : [];
    for (const f of fs) if (!ids.has(f)) err('история', `событие «${e.title}»: формирование «${f}» не найдено`);
  }
  if (!H.frontline?.length) info('история', 'исторической линии фронта нет — на карте не будет «ист. фронта»');

  // игра (передача командования человеку)
  const g = pkg.catalog?.game;
  if (!g) warn('игра', 'условия окончания игры не заданы — будут взяты по умолчанию (победа — последнее событие истории)');
  // … строки 145–154

export interface NetworkCheck {
  /** Узнанные цвета по классам: корзина, доля точек линии, где цвет есть рядом, и доля в стороне. */
  colors: Record<string, NetColor[]>;
  /** Проверено точек и их итог. */
  points: number; covered: number;
  km: { checked: number; present: number; absent: number; unclear: number };
  /** Отрезки, которых на карте нет: номер линии в исходном списке (дорог или рек) и расстояния вдоль неё, км. */
  absent: { line: number; from: number; to: number }[];
  /** Линии с названием, которых на карте нет больше всего (км). */
  absentNamed: { name: string; km: number }[];
  /**
   * Свои линии сверки (дороги OpenStreetMap для охвата карты), если сверялись не дороги театра: номера в absent —
   * по ним; при сохранении подтверждённые куски заменяют дороги театра в охвате карты.
   */
  roads?: TheatreData['roads'];
  /** Откуда свои линии сверки (для показа): «OSM», «OSM + OpenHistoricalMap на 1945-04-16». */
  source?: string;
}

/**
 * Проверка сети: точки на линиях (дороги, реки) в области через spacing пикселей уровня z; окно поперёк — ±w пикселей
 * (≈ 200 м) — для узнавания цвета, фон — такие же окна на 3w в обе стороны. Есть ли линия в точке — по узкому
 * окну ±w/2 (≈ 100 м): в плотной сети широкое окно задевает соседние улицы. Цвета узнаются по классам линий.
 */
export class NetworkLearner {
  readonly pts: Pt[] = [];
  readonly w: number;
  readonly classes: string[];
  private readonly byTile = new Map<string, number[]>();
  /** Корзины, встреченные в узком окне каждой точки (±w/2, без повторов): по ним — есть ли линия. */
  private readonly seen: Uint16Array[] = [];
  private readonly ok: Uint8Array;
  private readonly road: Record<string, Float64Array> = {};
  private readonly side: Record<string, Float64Array> = {};
  private readonly n: Record<string, number> = {};
  private readonly nSide: Record<string, number> = {};
  tiles = 0;
  /** Шаг точек, км. */
  readonly stepKm: number;

  constructor(readonly lines: NetLine[], readonly bbox: [number, number, number, number], readonly z: number, o: { spacing?: number; windowM?: number } = {}) {
    this.classes = [...new Set(lines.map((l) => l.cls))];
    for (const c of this.classes) { this.road[c] = new Float64Array(BINS); this.side[c] = new Float64Array(BINS); this.n[c] = 0; this.nSide[c] = 0; }
    const lat = (bbox[1] + bbox[3]) / 2;
    const mpp = (156543.03 * Math.cos((lat * Math.PI) / 180)) / 2 ** z;
    this.w = Math.max(3, Math.min(20, Math.round((o.windowM ?? 200) / mpp)));
    const spacing = o.spacing ?? Math.max(6, Math.round(this.w * 0.8));
    this.stepKm = (spacing * mpp) / 1000;
    const inBox = (p: LngLat) => p[0] >= bbox[0] && p[0] <= bbox[2] && p[1] >= bbox[1] && p[1] <= bbox[3];
    const P = (p: LngLat): [number, number] => [tileXY.lon2x(p[0], z) * 256, tileXY.lat2y(p[1], z) * 256];
    lines.forEach((rd, li) => {
      let d = 0, carry = 0;
      for (let k = 1; k < rd.line.length; k++) {
        const a = rd.line[k - 1], b = rd.line[k];
        const segKm = kmBetween(a, b);
        const [ax, ay] = P(a), [bx, by] = P(b);
        const len = Math.hypot(bx - ax, by - ay);
        if (len < 1e-6) continue;
        const nx = -(by - ay) / len, ny = (bx - ax) / len;
        for (let t = carry; t < len; t += spacing) {
          const u = t / len;
          const ll: LngLat = [a[0] + (b[0] - a[0]) * u, a[1] + (b[1] - a[1]) * u];
          if (inBox(ll)) {
            const gx = ax + (bx - ax) * u, gy = ay + (by - ay) * u;
            const i = this.pts.length;
            this.pts.push({ line: li, cls: rd.cls, gx, gy, nx, ny, d: d + segKm * u, ll });
            const key = `${Math.floor(gx / 256)},${Math.floor(gy / 256)}`;
            (this.byTile.get(key) ?? this.byTile.set(key, []).get(key)!).push(i);
          }
        }
        // следующая точка — через spacing от последней, уже на следующем отрезке
        carry += Math.max(0, Math.ceil((len - carry) / spacing)) * spacing - len;
        d += segKm;
      }
    });
    this.ok = new Uint8Array(this.pts.length);
  }
  /** Тайлы, в которых есть точки проверки. */
  tileList(): { x: number; y: number }[] {
    return [...this.byTile.keys()].map((k) => { const [x, y] = k.split(',').map(Number); return { x, y }; });
  }
  addTile(rgba: Uint8ClampedArray | Uint8Array, size: number, x: number, y: number) {
    const list = this.byTile.get(`${x},${y}`);
    if (!list) return;
    this.tiles++;
    const k = size / 256, w = this.w;
    const bins = new Set<number>(), inner = new Set<number>();
    const wi = Math.ceil(w / 2);
    const read = (gx: number, gy: number): number => {
      const px = Math.round((gx - x * 256) * k), py = Math.round((gy - y * 256) * k);
      if (px < 0 || py < 0 || px >= size || py >= size) return -1;
      const o = (py * size + px) * 4;
      if (rgba[o + 3] < 128) return -2;
      return colorBin(rgba[o], rgba[o + 1], rgba[o + 2]);
    };
    for (const i of list) {
      const p = this.pts[i];
      bins.clear(); inner.clear();
      let blank = 0, total = 0;
      for (let t = -w; t <= w; t++) {
        const b = read(p.gx + p.nx * t, p.gy + p.ny * t);
        if (b === -1) continue;
        total++;
        if (b === -2) { blank++; continue; }
  // … строки 200–394

export interface OhmMerge {
  roads: TheatreData['roads'];
  rivers: { name: string; line: LngLat[]; major: boolean }[];
  /** Сколько линий OHM на дату взято (с датой / без даты), сколько отброшено как построенные позже или упразднённые. */
  ohm: { valid: number; undated: number; later: number; ended: number };
  /** Линии OSM, убранные до сверки: совпали с линией OHM, которой на дату не было (послевоенные по датам OHM). */
  postwar: { kind: Kind; name?: string; km: number }[];
  /** Линии OSM, заменённые своими двойниками из OHM. */
  replaced: number;
}

/** Вода по карте: реки и каналы линиями (как дороги) и водоёмы площадями (клетки воды растра местности театра). */
export interface WaterCheck extends NetworkCheck {
  /** Реки и каналы OSM для охвата карты, если сверялись не реки театра (номера в absent — по ним). */
  rivers?: { name: string; line: LngLat[]; major: boolean }[];
  /** Водоёмы театра (связные клетки воды): всего, подтверждены картой, нет на карте; новая вода карты. */
  areas: { total: number; present: number; gone: number; goneCells: number; added: number; addedCells: number };
}

/** Отрезки «нет на карте» линиями (для показа): куски дорог по расстояниям вдоль линии из проверки. */
export function absentLines(roads: TheatreData['roads'], absent: NetworkCheck['absent']): LngLat[][] {
  const out: LngLat[][] = [];
  for (const a of absent) {
    const rd = roads[a.line];
    if (!rd) continue;
    const line: LngLat[] = [];
    let d = 0;
    for (let k = 1; k < rd.line.length; k++) {
      const p = rd.line[k - 1], q = rd.line[k], L = kmBetween(p, q);
      const u0 = L ? (a.from - d) / L : 0, u1 = L ? (a.to - d) / L : 0;
      if (u1 >= 0 && u0 <= 1) {
        const lo = Math.max(0, u0), hi = Math.min(1, u1);
        const P = (u: number): LngLat => [p[0] + (q[0] - p[0]) * u, p[1] + (q[1] - p[1]) * u];
        if (!line.length) line.push(P(lo));
        line.push(P(hi));
      }
      d += L;
    }
    if (line.length >= 2) out.push(line);
  }
  return out;
}

/** Средний цвет корзины (для показа узнанного цвета). */
export function binColor(bin: number): [number, number, number] {
  const r = binRule(bin);
  const h = r.h ? (r.h[0] + r.h[1]) / 2 : 0, s = r.s ? (r.s[0] + r.s[1]) / 2 : 0, v = r.v ? (r.v[0] + r.v[1]) / 2 : 0.5;
  const c = v * s, x = c * (1 - Math.abs(((h / 60) % 2) - 1)), m = v - c;
  const [a, b, d] = h < 60 ? [c, x, 0] : h < 120 ? [x, c, 0] : h < 180 ? [0, c, x] : h < 240 ? [0, x, c] : h < 300 ? [x, 0, c] : [c, 0, x];
  return [Math.round((a + m) * 255), Math.round((b + m) * 255), Math.round((d + m) * 255)];
}

/** Корзина → правило легенды (окно тона, насыщенности, яркости). */
export function binRule(bin: number): LegendRule {
  if (bin >= 600) { const v = bin - 600; return { s: [0, 0.12], v: [v / 10, (v + 1) / 10] }; }
  const h = Math.floor(bin / 25), s = Math.floor((bin % 25) / 5), v = bin % 5;
  return { h: [h * 15, (h + 1) * 15], s: [Math.max(0.12, s / 5), (s + 1) / 5], v: [v / 5, (v + 1) / 5] };
}

/** Линия OSM → куски внутри рамки, упрощённые (~10 м). */
function clipRuns(geom: { lat: number; lon: number }[], b: [number, number, number, number]): LngLat[][] {
  const inB = (p: LngLat) => p[0] >= b[0] && p[0] <= b[2] && p[1] >= b[1] && p[1] <= b[3];
  const out: LngLat[][] = [];
  let run: LngLat[] = [];
  const flush = () => { if (run.length >= 2) out.push(simplify(run, 0.0001).map(([x, y]) => [+x.toFixed(6), +y.toFixed(6)] as LngLat)); run = []; };
  for (const g of geom) { const p: LngLat = [g.lon, g.lat]; if (inB(p)) run.push(p); else flush(); }
  flush();
  return out;
}

/** Цвет пикселя → корзина: тон по 15°, насыщенность и яркость по пятым; серые — только по яркости. */
export function colorBin(r: number, g: number, b: number): number {
  const [h, s, v] = hsv(r, g, b);
  if (s < 0.12) return 600 + Math.min(9, Math.floor(v * 10));
  return Math.floor(h / 15) * 25 + Math.min(4, Math.floor(s * 5)) * 5 + Math.min(4, Math.floor(v * 5));
}

/** Связные (по восьми соседям) куски маски: список номеров клеток каждого. */
function components(m: Uint8Array, cols: number, rows: number): number[][] {
  const seen = new Uint8Array(m.length), out: number[][] = [];
  for (let i0 = 0; i0 < m.length; i0++) {
    if (!m[i0] || seen[i0]) continue;
    const comp: number[] = [], st = [i0]; seen[i0] = 1;
    while (st.length) {
      const i = st.pop()!; comp.push(i);
      const c = i % cols, r = (i - c) / cols;
      for (let dr = -1; dr <= 1; dr++) for (let dc = -1; dc <= 1; dc++) {
        const cc = c + dc, rr = r + dr;
        if (cc < 0 || rr < 0 || cc >= cols || rr >= rows) continue;
        const j = rr * cols + cc;
        if (m[j] && !seen[j]) { seen[j] = 1; st.push(j); }
      }
    }
    out.push(comp);
  }
  return out;
}

/**
 * Убрать из дорог театра отрезки, которых на карте нет (absent из проверки сети): линия режется по расстоянию
 * вдоль неё, остатки короче 0,3 км не сохраняются.
 */
export function cutAbsent<R extends { line: LngLat[] }>(roads: R[], absent: NetworkCheck['absent']): { roads: R[]; km: number } {
  const by = new Map<number, { from: number; to: number }[]>();
  for (const a of absent) (by.get(a.line) ?? by.set(a.line, []).get(a.line)!).push(a);
  const out: R[] = [];
  let cut = 0;
  roads.forEach((rd, li) => {
    const gaps = by.get(li);
    if (!gaps) { out.push(rd); return; }
    gaps.sort((a, b) => a.from - b.from);
    // точка на расстоянии d вдоль линии
    const cum = [0];
    for (let k = 1; k < rd.line.length; k++) cum.push(cum[k - 1] + kmBetween(rd.line[k - 1], rd.line[k]));
    const at = (d: number): LngLat => {
      let k = 1;
      while (k < cum.length - 1 && cum[k] < d) k++;
      const u = cum[k] > cum[k - 1] ? Math.max(0, Math.min(1, (d - cum[k - 1]) / (cum[k] - cum[k - 1]))) : 0;
      const a = rd.line[k - 1], b = rd.line[k];
      return [+(a[0] + (b[0] - a[0]) * u).toFixed(6), +(a[1] + (b[1] - a[1]) * u).toFixed(6)];
    };
    const piece = (from: number, to: number) => {
      if (to - from < 0.3) return;
      const line: LngLat[] = [at(from)];
      for (let k = 0; k < cum.length; k++) if (cum[k] > from && cum[k] < to) line.push(rd.line[k]);
      line.push(at(to));
      out.push({ ...rd, line });
    };
    let pos = 0;
    const total = cum[cum.length - 1];
    for (const g of gaps) {
      const from = Math.max(pos, g.from), to = Math.min(total, g.to);
      if (to <= from) continue;
      piece(pos, from);
      cut += to - from;
      pos = to;
    }
    piece(pos, total);
  });
  return { roads: out, km: +cut.toFixed(1) };
}

/** Маска, расширенная на соседние клетки. */
function dilate(m: Uint8Array, cols: number, rows: number): Uint8Array {
  const out = new Uint8Array(m.length);
  for (let i = 0; i < m.length; i++) if (m[i]) {
    const c = i % cols, r = (i - c) / cols;
    for (let dr = -1; dr <= 1; dr++) for (let dc = -1; dc <= 1; dc++) { const cc = c + dc, rr = r + dr; if (cc >= 0 && rr >= 0 && cc < cols && rr < rows) out[rr * cols + cc] = 1; }
  }
  return out;
}

/**
 * OSM + OpenHistoricalMap на дату: линии OHM, существующие на дату, берутся вместо своих двойников из OSM (≥ 70 %
 * длины в 100 м); линии OSM, совпадающие с линией OHM, которой на дату не было (построена позже или упразднена), —
 * убираются как послевоенные; остальные линии OSM остаются (их проверит карта).
 */
export function mergeOhm(osm: { roads: TheatreData['roads']; rivers: OhmMerge['rivers'] }, ohmJson: OsmJson, date: string, b: [number, number, number, number]): OhmMerge {
  const ohm = { valid: 0, undated: 0, later: 0, ended: 0 };
  const keep: Record<Kind, LngLat[][]> = { road: [], water: [] }, gone: Record<Kind, LngLat[][]> = { road: [], water: [] };
  const ohmRoads: TheatreData['roads'] = [], ohmRivers: OhmMerge['rivers'] = [];
  for (const el of ohmJson.elements ?? []) {
    if (el.type !== 'way' || !el.geometry || !el.tags) continue;
    const t = el.tags;
    const road = t.highway && [...OSM_HIGHWAY, ...OSM_ROAD].includes(t.highway), water = t.waterway && OSM_WATERWAY.includes(t.waterway);
    if (!road && !water) continue;
    const at = ohmAt(t, date);
    ohm[at]++;
    const lines = clipRuns(el.geometry, b);
    const kind: Kind = road ? 'road' : 'water';
    if (at === 'later' || at === 'ended') { gone[kind].push(...lines); continue; }
    keep[kind].push(...lines);
    const name = road ? t.ref || t.name : t.name;
    for (const line of lines) {
      if (road) ohmRoads.push({ kind: OSM_HIGHWAY.includes(t.highway) ? 'highway' : 'road', line, ...(name ? { name } : {}) });
      else ohmRivers.push({ name: name ?? (t.waterway === 'canal' ? 'канал' : ''), line, major: false });
    }
  }
  const nearKeep = { road: segIndex(keep.road), water: segIndex(keep.water) }, nearGone = { road: segIndex(gone.road), water: segIndex(gone.water) };
  const postwar: OhmMerge['postwar'] = [];
  let replaced = 0;
  const pick = <L extends { line: LngLat[]; name?: string }>(list: L[], kind: Kind): L[] => list.filter((x) => {
    if (gone[kind].length && shareNear(x.line, nearGone[kind], 0.1) >= 0.7 && shareNear(x.line, nearKeep[kind], 0.1) < 0.3) {
      postwar.push({ kind, name: x.name || undefined, km: +lenKm(x.line).toFixed(1) }); return false;
    }
    if (keep[kind].length && shareNear(x.line, nearKeep[kind], 0.1) >= 0.7) { replaced++; return false; }
    return true;
  });
  return {
    roads: [...ohmRoads, ...pick(osm.roads, 'road')],
    rivers: [...ohmRivers, ...pick(osm.rivers, 'water')],
    ohm, postwar, replaced,
  };
}

/** Линия OHM на дату: существует, построена позже, уже не существует; без дат — undated. */
export function ohmAt(tags: Record<string, string>, date: string): 'valid' | 'later' | 'ended' | 'undated' {
  const s = ohmDate(tags.start_date), e = ohmDate(tags.end_date, true);
  if (s && s > date) return 'later';
  if (e && e <= date) return 'ended';
  return s || e ? 'valid' : 'undated';
}

/** Дата OHM («1936», «1936-09», «1936-09-27», «~1930») → ISO-день или null, если не разобрать. */
export function ohmDate(v: string | undefined, end = false): string | null {
  const m = v && /(\d{4})(?:-(\d{2}))?(?:-(\d{2}))?/.exec(v);
  if (!m) return null;
  // неполная дата: начало — с первого дня периода, конец — по последний
  return `${m[1]}-${m[2] ?? (end ? '12' : '01')}-${m[3] ?? (end ? '28' : '01')}`;
}

/** Запрос Overpass: дороги и водотоки в рамке — одним запросом. */
export function osmNetworkQuery(b: [number, number, number, number]): string {
  const bb = `${b[1]},${b[0]},${b[3]},${b[2]}`;
  return `[out:json][timeout:180];(way["highway"~"^(${[...OSM_HIGHWAY, ...OSM_ROAD].join('|')})$"](${bb});way["waterway"~"^(${OSM_WATERWAY.join('|')})$"](${bb}););out tags geom;`;
}

/** Запрос Overpass: дороги в рамке [w, s, e, n] с геометрией. */
export function osmRoadsQuery(b: [number, number, number, number]): string {
  return `[out:json][timeout:180];way["highway"~"^(${[...OSM_HIGHWAY, ...OSM_ROAD].join('|')})$"](${b[1]},${b[0]},${b[3]},${b[2]});out tags geom;`;
}

/** Ответ Overpass → реки и каналы в формате театра (major — нет: большие реки театра остаются свои). */
export function osmToRivers(json: OsmJson, b: [number, number, number, number]): { name: string; line: LngLat[]; major: boolean }[] {
  const out: { name: string; line: LngLat[]; major: boolean }[] = [];
  for (const el of json.elements ?? []) {
    if (el.type !== 'way' || !el.geometry || !el.tags?.waterway || !OSM_WATERWAY.includes(el.tags.waterway)) continue;
    for (const line of clipRuns(el.geometry, b)) out.push({ name: el.tags.name ?? (el.tags.waterway === 'canal' ? 'канал' : ''), line, major: false });
  }
  return out;
}

/**
 * Ответ Overpass → дороги в формате театра: линии обрезаются рамкой (куски внутри неё), упрощаются (~10 м),
 * название — номер дороги (ref) или имя.
 */
export function osmToRoads(json: OsmJson, b: [number, number, number, number]): TheatreData['roads'] {
  const out: TheatreData['roads'] = [];
  for (const el of json.elements ?? []) {
    if (el.type !== 'way' || !el.geometry || !el.tags?.highway) continue;
    const kind = OSM_HIGHWAY.includes(el.tags.highway) ? 'highway' : OSM_ROAD.includes(el.tags.highway) ? 'road' : null;
    if (!kind) continue;
    const name = el.tags.ref || el.tags.name;
    for (const line of clipRuns(el.geometry, b)) out.push({ kind, line, ...(name ? { name } : {}) });
  }
  return out;
}

/** Реки и каналы → линии сверки класса water. */
export const riverLines = (rivers: { line: LngLat[]; name?: string }[]): NetLine[] =>
  rivers.map((r, idx) => ({ cls: 'water', line: r.line, name: r.name || undefined, idx }));

/** Дороги театра (или OSM) → линии сверки: шоссе и дороги, без железных. */
export const roadLines = (roads: TheatreData['roads']): NetLine[] =>
  roads.flatMap((r, idx) => (r.kind === 'rail' ? [] : [{ cls: r.kind, line: r.line, name: r.name, idx }]));

/** Сетка отрезков для «есть ли линия рядом» (≈ 0,01°). */
function segIndex(lines: LngLat[][]) {
  const cell = 0.01, idx = new Map<string, [LngLat, LngLat][]>();
  for (const l of lines) for (let k = 1; k < l.length; k++) {
    const a = l[k - 1], b = l[k];
    for (let x = Math.floor(Math.min(a[0], b[0]) / cell) - 1; x <= Math.floor(Math.max(a[0], b[0]) / cell) + 1; x++)
      for (let y = Math.floor(Math.min(a[1], b[1]) / cell) - 1; y <= Math.floor(Math.max(a[1], b[1]) / cell) + 1; y++)
        (idx.get(`${x},${y}`) ?? idx.set(`${x},${y}`, []).get(`${x},${y}`)!).push([a, b]);
  }
  return (p: LngLat, km: number) => {
    const list = idx.get(`${Math.floor(p[0] / cell)},${Math.floor(p[1] / cell)}`);
    if (!list) return false;
    const k = Math.cos((p[1] * Math.PI) / 180);
    for (const [a, b] of list) {
      const ax = a[0] * k, ay = a[1], bx = b[0] * k, by = b[1], px = p[0] * k, py = p[1];
      const dx = bx - ax, dy = by - ay, L = dx * dx + dy * dy || 1e-12, u = Math.max(0, Math.min(1, ((px - ax) * dx + (py - ay) * dy) / L));
      if (Math.hypot(px - ax - dx * u, py - ay - dy * u) * KM_PER_DEG <= km) return true;
    }
    return false;
  };
}

/** Доля точек линии (через ~50 м), у которых рядом (≤ km) есть линия индекса. */
function shareNear(line: LngLat[], near: (p: LngLat, km: number) => boolean, km: number): number {
  let n = 0, hit = 0;
  for (let k = 1; k < line.length; k++) {
    const a = line[k - 1], b = line[k], steps = Math.max(1, Math.ceil(kmBetween(a, b) / 0.05));
    for (let q = 0; q < steps; q++) { const u = q / steps; n++; if (near([a[0] + (b[0] - a[0]) * u, a[1] + (b[1] - a[1]) * u], km)) hit++; }
  }
  return n ? hit / n : 0;
}

/** Упрощение ломаной (Дуглас — Пекер), допуск в градусах. */
function simplify(pts: LngLat[], tol: number): LngLat[] {
  if (pts.length < 3) return pts;
  const keep = new Uint8Array(pts.length); keep[0] = keep[pts.length - 1] = 1;
  const st: [number, number][] = [[0, pts.length - 1]];
  while (st.length) {
    const [a, b] = st.pop()!;
    const [ax, ay] = pts[a], [bx, by] = pts[b], dx = bx - ax, dy = by - ay, L = Math.hypot(dx, dy) || 1e-12;
    let m = -1, md = tol;
    for (let i = a + 1; i < b; i++) { const d = Math.abs((pts[i][0] - ax) * dy - (pts[i][1] - ay) * dx) / L; if (d > md) { md = d; m = i; } }
    if (m > 0) { keep[m] = 1; st.push([a, m], [m, b]); }
  }
  return pts.filter((_, i) => keep[i]);
}

/** Накопитель: тайлы (RGBA) → доли классов по клеткам сетки → маски. */
export class OverlayAccumulator {
  readonly names: string[];
  private readonly counts: Float64Array[];
  private readonly total: Float64Array;
  tiles = 0;
  constructor(readonly legend: OverlayLegend, readonly grid: { bbox: [number, number, number, number]; cols: number; rows: number }) {
    this.names = Object.keys(legend.pixels);
    this.counts = this.names.map(() => new Float64Array(grid.cols * grid.rows));
    this.total = new Float64Array(grid.cols * grid.rows);
  }
  /** Тайл x, y уровня z: RGBA size×size. preview — куда отметить классы пикселей (RGBA того же размера). */
  addTile(rgba: Uint8ClampedArray | Uint8Array, size: number, x: number, y: number, z: number, preview?: Uint8ClampedArray) {
    const { bbox: [w, s, e, n], cols, rows } = this.grid;
    const dLng = (e - w) / cols, dLat = (n - s) / rows;
    this.tiles++;
    // класс каждого пикселя тайла (−1 — ни один, −2 — прозрачно: карты нет)
    const cls = new Int8Array(size * size);
    for (let i = 0; i < size * size; i++) {
      const o = i * 4;
      cls[i] = rgba[o + 3] < 128 ? -2 : pixelClass(this.legend, this.names, rgba[o], rgba[o + 1], rgba[o + 2]);
    }
    // линейные классы — только длинные тонкие линии: отдельные буквы надписей, цифры, значки и пятна того же цвета
    // отбрасываются (иначе тёмные образцы дорог собирают все надписи карты)
    const cellPx = Math.max(4, (size * Math.abs(lat2y(n, z) - lat2y(n - dLat, z))));
    const minExtent = Math.max(14, Math.round(cellPx * 1.5)), maxWidth = Math.max(4, cellPx * 0.35);
    for (let k = 0; k < this.names.length; k++) if (LINEAR.includes(this.names[k])) dropBlobs(cls, size, k, minExtent, maxWidth);
    for (let py = 0; py < size; py++) {
      const lat = y2lat(y + (py + 0.5) / size, z);
      const r = Math.floor((n - lat) / dLat);
      if (r < 0 || r >= rows) continue;
      for (let px = 0; px < size; px++) {
        const lng = x2lon(x + (px + 0.5) / size, z);
        const c = Math.floor((lng - w) / dLng);
        if (c < 0 || c >= cols) continue;
        const i = py * size + px, o = i * 4;
        if (cls[i] === -2) continue;
        const cell = r * cols + c;
        this.total[cell]++;
        const k = cls[i];
        if (k >= 0) { this.counts[k][cell]++; if (preview) { const col = PREVIEW[this.names[k]] ?? [200, 0, 200]; preview[o] = col[0]; preview[o + 1] = col[1]; preview[o + 2] = col[2]; preview[o + 3] = 255; } }
      }
    }
  }
  result(meta: { source: string; zoom: number }): OverlayResult {
    const N = this.grid.cols * this.grid.rows;
    const masks: Record<string, Uint8Array> = {};
    for (const c of this.legend.cells) masks[c.cls] ??= new Uint8Array(N);
    for (let i = 0; i < N; i++) {
      if (!this.total[i]) continue;
      for (const c of this.legend.cells) {
        const f = c.of.reduce((sum, nm) => sum + (this.names.includes(nm) ? this.counts[this.names.indexOf(nm)][i] : 0), 0) / this.total[i];
        if (f >= c.min) masks[c.cls][i] = 1;
      }
    }
    // линейные классы — до осевой линии в одну клетку: толстая линия скана задевает соседние клетки, и дорога
    // выходила полосой в 2–3 клетки «лесенкой»
    for (const cls of LINEAR) if (masks[cls]) { thinMask(masks[cls], this.grid.cols, this.grid.rows); dropSpecks(masks[cls], this.grid.cols, this.grid.rows, 3); }
    const covered = new Uint8Array(N).map((_, i) => (this.total[i] > 0 ? 1 : 0));
    return {
      legend: this.legend.id, name: this.legend.name, source: meta.source, zoom: meta.zoom, bbox: this.grid.bbox, cols: this.grid.cols, rows: this.grid.rows,
      covered: maskRle(covered), masks: Object.fromEntries(Object.entries(masks).map(([k, m]) => [k, maskRle(m)])),
      stats: Object.fromEntries(Object.entries(masks).map(([k, m]) => [k, m.reduce((a, x) => a + x, 0)])),
    };
  }
}

export interface OverlayApply {
  /** Маска дорог (→ roadGrid «r») и шоссе (→ «h»). */
  road?: string; highway?: string;
  /** Убрать современные дороги в охвате карты: только дороги или и шоссе. */
  replaceModernRoads?: false | 'road' | 'all';
  water?: string; urban?: string; forest?: string; marsh?: string;
  /** Современная застройка, которой на карте нет, → этот класс (обычно open); keepUrban — маска, где застройку оставить. */
  demoteModernUrban?: TerrainClass; keepUrban?: string;
  /** Убрать отрезки дорог театра, которых на карте нет (по проверке сети, ov.network). */
  dropAbsent?: boolean;
  /**
   * Вода по проверке сети (ov.water): реки и каналы, которых на карте нет, вырезаются (реки OSM — заменяют малые реки
   * театра в охвате); водоёмы, которых на карте нет, становятся сушей (класс — по соседним клеткам); новая вода карты
   * (маска water-new) — водой.
   */
  waterNet?: boolean;
  /** Только внутри рамки (поля листа с легендой не трогать). */
  clip?: [number, number, number, number];
}

export interface OverlayLegend {
  id: string; name: string; note?: string;
  /** Классы пикселей: пиксель относится к первому подходящему. */
  pixels: Record<string, LegendRule[]>;
  /** Класс клетки: доля пикселей класса (или суммы классов) не меньше порога. */
  cells: { cls: string; of: string[]; min: number }[];
}

export interface OverlayResult {
  legend: string; name: string; source: string; zoom: number;
  bbox: [number, number, number, number]; cols: number; rows: number;
  /** RLE «число+0/1» через запятую, строки с севера на юг. */
  covered: string; masks: Record<string, string>; stats: Record<string, number>;
  /** Проверка дорог театра по карте (распознавание по современной сети). */
  network?: NetworkCheck;
  /** Проверка воды театра по карте: реки линиями, водоёмы площадями. */
  water?: WaterCheck;
}

/** Сравнение дорог исторической карты и театра в охвате карты (по клеткам поправки). */
export interface RoadComparison {
  bbox: [number, number, number, number]; cols: number; rows: number;
  /** 0 — нет дороги, 1 — есть и там и там, 2 — только на карте, 3 — только в театре. */
  cells: Uint8Array;
  stats: { covered: number; map: number; theatre: number; both: number; mapOnly: number; theatreOnly: number };
  /** Клетка ≈ км (для перевода клеток в длину дорог). */
  cellKm: number;
  /** Дороги театра (линии с названием), которых на карте почти нет: послевоенные или неверно распознанные. */
  absent: { name: string; kind: string; km: number; share: number }[];
}

/** Поправка по исторической карте → театр (как apply_overlays сборщика). Возвращает новый театр и что изменилось. */
export function applyOverlay(T: TheatreData, ov: OverlayResult, o: OverlayApply): { theatre: TheatreData; changes: Record<string, number> } {
  const N0 = ov.cols * ov.rows;
  const cov = decodeMask(ov.covered, N0);
  const masks = Object.fromEntries(Object.entries(ov.masks).map(([k, m]) => [k, decodeMask(m, N0)]));
  const changes: Record<string, number> = {};
  const [ow, os, oe, on] = ov.bbox;
  const cellAt = (lng: number, lat: number) => {
