    const c = Math.floor(((lng - ow) / (oe - ow)) * ov.cols), r = Math.floor(((on - lat) / (on - os)) * ov.rows);
    if (c < 0 || r < 0 || c >= ov.cols || r >= ov.rows) return -1;
