  // сетка результата — растр местности театра (или сама сетка поправки, если растра нет)
  const g: TerrainGrid = T.terrainGrid ?? { bbox: ov.bbox, cols: ov.cols, rows: ov.rows, rle: `${ov.cols * ov.rows}${'o'}` };
