}

export function analyze(ctx: SimContext, history: History, o: AnalysisOptions = {}): Analysis {
  const seed = o.seed ?? 1, runs = Math.max(1, o.runs ?? 1), tol = o.toleranceKm ?? 10;
  const t0 = Date.now();
  o.onRun?.(1, runs);
  const run = runScenario(ctx, seed);
  const ms = Date.now() - t0;
  const deviations = compareWithHistory(ctx, run, history);
  const summary = summarize(deviations, tol);
  const events = checkEvents(ctx, run, history);
  const spread = [{ seed, within: summary.within, median: summary.medianExcessKm }];
  const bySeed = events.map((e) => ({ id: e.id, title: e.title, historical: e.historical, days: [e.days] as (number | null)[] }));
  for (let k = 1; k < runs; k++) {
    o.onRun?.(k + 1, runs);
    const r = runScenario(ctx, seed + k);
    const s = summarize(compareWithHistory(ctx, r, history), tol);
    spread.push({ seed: seed + k, within: s.within, median: s.medianExcessKm });
    const ev = checkEvents(ctx, r, history);
    for (const b of bySeed) b.days.push(ev.find((e) => e.id === b.id)?.days ?? null);
  }
  const strength = history.checkpoints?.length ? compareStrength(ctx, run, history) : undefined;
  return { run, ms, seed, toleranceKm: tol, deviations, summary, spread, events, eventsBySeed: bySeed, sectors: sectorBreaches(ctx, run), ...(strength ? { strength } : {}) };
}

/** Отчёт о сравнении с историей (Markdown). */
export function reportMarkdown(ctx: SimContext, a: Analysis): string {
  const { run, summary: sum, spread, toleranceKm: tol } = a;
  const names = new Map(run.final.formations.map((f) => [f.id, shortName(f.name)]));
  const runs = spread.length;
  const L: string[] = [];
  L.push(`# Исторический прогон: ${ctx.scenario.name}`, '');
  L.push(`Сценарий \`${ctx.scenario.id}\`, правила \`${ctx.rules.id}\`, seed ${a.seed}; ходов ${run.final.turn} по ${ctx.scenario.turnHours} ч; расчёт ${a.ms} мс.`, '');
  L.push('Обе стороны получают исторические задачи (наступать на…, держаться, отходить), а не исторические положения: темпы, окружения и исходы боёв считает арбитр. Отклонение — расстояние от расчётного положения до исторического; «сверх» — за вычетом неопределённости исторического положения. Устройство модели — docs/system.md, часть II.', '');
  L.push(`**В пределах ${tol} км сверх неопределённости: ${(sum.within * 100).toFixed(0)} %** положений (${sum.n}); медиана превышения ${sum.medianExcessKm} км.`, '');
  if (runs > 1) {
    const w = spread.map((x) => x.within);
    L.push(`Разброс по ${runs} прогонам (seed ${a.seed}…${a.seed + runs - 1}): доля в допуске ${(Math.min(...w) * 100).toFixed(0)}–${(Math.max(...w) * 100).toFixed(0)} %.`, '');
  }
  if (a.eventsBySeed.length) {
    L.push('## Ключевые события', '');
    if (runs > 1) {
      L.push(`| событие | история | расчёт (seed ${a.seed}) | расхождение по прогонам, сут |`, '|---|---|---|---|');
      for (const e of a.eventsBySeed) {
        const first = a.events.find((x) => x.id === e.id);
        L.push(`| ${e.title} | ${e.historical.slice(5)} | ${first?.simulated?.slice(5) ?? 'не произошло'} | ${e.days.map(fmtDays).join(' ')} |`);
      }
      const all = a.eventsBySeed.flatMap((e) => e.days);
      L.push('', `В пределах ±2 сут: ${all.filter((d) => d != null && Math.abs(d) <= 2).length} из ${all.length}.`);
    } else {
      L.push('| событие | история | расчёт | расхождение, сут |', '|---|---|---|---|');
      for (const e of a.events) L.push(`| ${e.title} | ${e.historical.slice(5)} | ${e.simulated?.slice(5) ?? 'не произошло'} | ${fmtDays(e.days)} |`);
    }
    L.push('');
  }
  if (ctx.scenario.boundaries?.some((b) => b.kind !== 'air')) {
    const bs = ctx.scenario.boundaries.filter((b) => b.kind !== 'air');
    const title = new Map(bs.map((b) => [b.id, b.title]));
    const fname = new Map(ctx.scenario.formations.map((f) => [f.id, shortName(f.name)]));
    L.push('## Разграничительные линии', '', `Линии по директивам (${bs.length}): ${bs.map((b) => `${b.title} (${b.reliability ?? '—'})`).join('; ')}. Где линий нет и за их концами — полосы расчётные (по ближайшим войскам фронтов).`, '');
    if (!a.sectors.length) L.push('Выходов в полосу соседа нет.', '');
    else {
      L.push(`Выходы в полосу соседа (seed ${a.seed}): ${a.sectors.length}.`, '', '| формирование | линия | в полосе | ходов | с |', '|---|---|---|---|---|');
      for (const b of a.sectors) L.push(`| ${names.get(b.formation) ?? b.formation} | ${title.get(b.boundary) ?? b.boundary} | ${fname.get(b.in) ?? b.in} | ${b.turns} | ${b.first.slice(5, 16).replace('T', ' ')} |`);
      L.push('');
    }
  }
  if (a.strength?.n) {
    const st = a.strength;
    L.push('## Численность и потери против документов', '',
      `Контрольные точки по документам: ${st.n}; в пределах ±25 %: ${(st.within * 100).toFixed(0)} %; медиана относительной ошибки ${(st.medianRel * 100).toFixed(0)} %. Численность — люди в расчёте против документа; потери — накопленные за период (люди в начале + пополнения − выделенное − люди в конце).`, '');
    const worst = [...st.byFormation].sort((x, y) => x.within - y.within || y.medianRel - x.medianRel).slice(0, 10);
    L.push('Наибольшие расхождения (до 10 формирований):', '', '| формирование | точек | в допуске | медиана ошибки |', '|---|---|---|---|');
    for (const b of worst) L.push(`| ${names.get(b.key) ?? b.key} | ${b.n} | ${(b.within * 100).toFixed(0)} % | ${(b.medianRel * 100).toFixed(0)} % |`);
    L.push('');
  }
  L.push('## По дням', '', '| день | положений | среднее отклонение, км | медиана сверх, км | в допуске |', '|---|---|---|---|---|');
  for (const d of [...sum.byDay].sort((x, y) => x.key.localeCompare(y.key))) L.push(`| ${d.key} | ${d.n} | ${d.meanKm} | ${d.medianExcessKm} | ${(d.within * 100).toFixed(0)} % |`);
  L.push('', '## По формированиям', '', '| формирование | положений | среднее, км | медиана сверх, км | в допуске |', '|---|---|---|---|---|');
  for (const d of [...sum.byFormation].sort((x, y) => x.within - y.within)) L.push(`| ${names.get(d.key) ?? d.key} | ${d.n} | ${d.meanKm} | ${d.medianExcessKm} | ${(d.within * 100).toFixed(0)} % |`);
  L.push('', '## Наибольшие расхождения', '', '| формирование | дата | историческое место | отклонение, км | сверх, км |', '|---|---|---|---|---|');
  for (const d of [...a.deviations].sort((x, y) => y.excessKm - x.excessKm).slice(0, 15)) L.push(`| ${names.get(d.formation)} | ${d.time.slice(0, 10)} | ${d.place} (${d.reliability}, ±${d.approxKm}) | ${d.km} | ${d.excessKm} |`);
  L.push('', '## Бои', '', '| ход | наступающие | обороняющиеся | соотношение | исход | продвижение, км | потери наст./обор., % |', '|---|---|---|---|---|---|---|');
  const OUT: Record<string, string> = { breakthrough: 'прорыв', advance: 'продвижение', repelled: 'отражено', held: 'удержано' };
  for (const j of run.final.journal) {
    if (j.kind !== 'combat') continue;
    L.push(`| ${j.time.slice(5, 10)} | ${j.attackers.map((x) => names.get(x)).join(', ')} | ${j.defenders.map((x) => names.get(x)).join(', ')} | ${j.ratio} | ${OUT[j.outcome] ?? j.outcome} | ${j.advanceKm} | ${(j.attackerLoss * 100).toFixed(1)} / ${(j.defenderLoss * 100).toFixed(1)} |`);
  }
  L.push('', '## Итог по силам', '', '| формирование | люди (нач. → кон.) | танки (нач. → кон.) |', '|---|---|---|');
  for (const f of run.final.formations) L.push(`| ${shortName(f.name)} | ${f.initial.personnel.toLocaleString('ru')} → ${f.personnel.toLocaleString('ru')}${f.destroyed ? ' (разгромлено)' : ''} | ${f.initial.tanks} → ${f.tanks} |`);
  L.push('', '## Оговорки', '',
    '- Задачи сторон записаны составителем по книгам и мемуарам; у каждой — источник в рецепте сценария.',
    '- Численность части объединений и положения с достоверностью C — оценки составителя набора данных.',
    '- Соединение — точка с полосой обороны, а не занимаемый район; местность — современная с историческими поправками (подробно — раздел «Ограничения» в docs/system.md, часть II).');
  return L.join('\n');
}

/** Выходы формирований в полосу соседа по действующим разграничительным линиям — по снимкам прогона. */
export function sectorBreaches(ctx: SimContext, run: Run): SectorBreach[] {
  if (!ctx.scenario.boundaries?.length) return [];
  const groups = groupOf(ctx.scenario, 'front');
  const side = new Map(run.final.formations.map((f) => [f.id, f.side]));
  const acc = new Map<string, SectorBreach>();
  for (const s of run.snapshots) {
    for (const v of sectorViolations(ctx.theatre, ctx.scenario, s.units.map((u) => ({ id: u.id, side: side.get(u.id) ?? '', at: u.at, destroyed: u.destroyed })), s.time, groups)) {
      const k = `${v.formation}|${v.boundary}`;
      const b = acc.get(k);
      if (b) b.turns++; else acc.set(k, { formation: v.formation, boundary: v.boundary, in: v.in, turns: 1, first: s.time });
    }
  }
  return [...acc.values()].sort((a, b) => a.first.localeCompare(b.first));
}

export interface IntelReport {
  id: string;
  name: string;
  at: LngLat;
  place: string;
  posture: string;
  /** Оценка сил, словами (округлённо). */
  estimate: string;
  /** Ближайшее своё формирование и расстояние до него, км. */
  nearest: { name: string; km: number } | null;
  /** Новое (вчера не было в разведсводке). */
  fresh: boolean;
}

export const TASK_RU: Record<Task, string> = {
  defend: 'оборонять', hold: 'удерживать любой ценой', delay: 'сдерживать', withdraw: 'отходить', counterattack: 'контратаковать',
  attack: 'наступать', breakout: 'прорываться', regroup: 'перегруппироваться', reserve: 'в резерв', relieve: 'деблокировать',
};

export interface UnitReport {
  id: string;
  name: string;
  parent: string | null;
  echelon: Echelon;
  /** На театре и не уничтожено; arrives — прибывает позже (дата). */
  status: 'active' | 'destroyed' | 'arriving' | 'reserve';
  arrives?: string;
  /** Резерв Ставки: с какого момента может быть введён. */
  reserveFrom?: string;
  at: LngLat;
  place: string;
  posture: string;
  task: string | null;
  target: string | null;
  /** Источник действующего приказа: сценарий (история), эксперт, модель. */
  orderSource: string | null;
  personnel: number;
  tanks: number;
  guns: number;
  /** Укомплектованность, доля начальной численности. */
  strength: number;
  ammo: number;
  fuel: number;
  fatigue: number;
  cutOff: boolean;
  /** Продвижение за последний ход, км. */
  movedKm: number;
  combats: CombatNote[];
  /** Приказы, ещё не дошедшие до исполнителя. */
  pending: { task: string; target: string; issuedAt: string }[];
}

/** Исходное написание пункта: «BadFreienwalde» → «Bad Freienwalde», «B_Reichstag» → «Reichstag». */
export function areaOriginal(name: string): string {
  return name.replace(/^B_/, '').replace(/_/g, ' ').replace(/([a-z])([A-Z])/g, '$1 $2');
}

/**
 * Название пункта для людей и модели: по-русски, исходное — в скобках: «Зелов (Seelow)», «Берлин, Рейхстаг
 * (Reichstag)». Русские названия — data/places-ru.json; нет перевода — исходное (с «Берлин-» для объектов города).
 * Приказы модели узнают пункт по любому из двух названий.
 */
export function areaTitle(name: string): string {
  if (/[^\x00-\x7f]/.test(name) && !(name in PLACES_RU)) return name;
  const ru = (PLACES_RU as Record<string, string>)[name];
  const orig = areaOriginal(name);
  if (ru && ru !== orig) return `${ru} (${orig})`;
  return name.startsWith('B_') ? `Берлин-${orig}` : orig;
}

/** Бои за ход, в которых участвовало формирование. */
function combatsOf(id: string, journal: JournalEntry[], names: Map<string, string>): CombatNote[] {
  const out: CombatNote[] = [];
  for (const j of journal) {
    if (j.kind !== 'combat') continue;
    const att = j.attackers.includes(id), def = j.defenders.includes(id);
    if (!att && !def) continue;
    out.push({
      against: (att ? j.defenders : j.attackers).map((x) => names.get(x) ?? x), role: att ? 'attack' : 'defend',
      outcome: OUTCOME_RU[j.outcome], ratio: j.ratio, advanceKm: j.advanceKm, lossPct: Math.round((att ? j.attackerLoss : j.defenderLoss) * 100), at: j.time,
    });
  }
  return out;
}

/** Сводка «за сутки» для стороны: бои, окружения, уничтоженные, дошедшие приказы (только свои — для чужих — без подробностей). */
export function dayEvents(ctx: SimContext, state: SimState, side: string, prev: SimState): string[] {
  const names = new Map(state.formations.map((f) => [f.id, f.name]));
  const sideOf = new Map(state.formations.map((f) => [f.id, f.side]));
  const out: string[] = [];
  for (const j of state.journal.slice(prev.journal.length)) {
    if (j.kind === 'combat') {
      const ours = sideOf.get(j.attackers[0]) === side;
      const a = j.attackers.map((x) => names.get(x)).join(', '), d = j.defenders.map((x) => names.get(x)).join(', ');
      out.push(ours
        ? `Наступление: ${a} против ${d} — ${OUTCOME_RU[j.outcome]}${j.advanceKm ? ` на ${km1(j.advanceKm)} км` : ''}; соотношение сил ${km1(j.ratio)}:1; потери ${Math.round(j.attackerLoss * 100)} %.`
        : `Атака противника: ${a} против ${d} — ${OUTCOME_RU[j.outcome]}${j.advanceKm ? `, противник продвинулся на ${km1(j.advanceKm)} км` : ''}; наши потери ${Math.round(j.defenderLoss * 100)} %.`);
    } else if (j.kind === 'encircled') {
      const ours = sideOf.get(j.formation) === side;
      if (ours) out.push(j.cut ? `${names.get(j.formation)} — ОТРЕЗАНО от подвоза (окружено).` : `${names.get(j.formation)} — подвоз восстановлен.`);
      else if (j.cut) out.push(`По данным разведки, ${names.get(j.formation)} отрезано от своих.`);
    } else if (j.kind === 'destroyed') {
      out.push(sideOf.get(j.formation) === side ? `${names.get(j.formation)} потеряло боеспособность.` : `${names.get(j.formation)} (противник) разгромлено.`);
    } else if (j.kind === 'capitulated') {
      out.push(sideOf.get(j.formation) === side ? `${names.get(j.formation)} — в окружении без боеприпасов, капитулировало (${j.personnel.toLocaleString('ru')} чел.).` : `${names.get(j.formation)} (противник) в котле капитулировало: около ${j.personnel.toLocaleString('ru')} пленных.`);
    } else if (j.kind === 'brokeOut') {
      out.push(sideOf.get(j.formation) === side ? `${names.get(j.formation)} прорвалось из окружения (${j.personnel.toLocaleString('ru')} чел.), тяжёлое вооружение брошено.` : `По данным разведки, ${names.get(j.formation)} прорвалось из котла.`);
    } else if (j.kind === 'detached' && sideOf.get(j.formation) === side) {
      out.push(`Из ${names.get(j.from)} выделено: ${names.get(j.formation)} (${j.personnel.toLocaleString('ru')} чел., ${j.tanks} танков, ${j.guns} орудий).`);
    } else if (j.kind === 'directive' && j.side === side) {
      const t = commandTerms(ctx, side);
      const who = j.issuedBy === 'player' ? 'распоряжение' : `${t.directive} ${t.topGen}`;
      out.push(`С ${j.from.slice(8, 10)}.${j.from.slice(5, 7)} ${j.from.slice(11, 16)} — разграничительная линия ${j.title.replace(/\s*\(.*\)$/, '')} (${who}).`);
    } else if (j.kind === 'supply' && sideOf.get(j.formation) === side) {
      out.push(j.what === 'ammo' ? `${names.get(j.formation)}: боеприпасы на исходе (${j.left} бк).` : j.what === 'stock' ? `${names.get(j.formation)}: склады крепости исчерпаны.` : `${names.get(j.formation)}: горючее кончилось.`);
    }
  }
  return out;
}

/** «у Зелова» / «8 км к СВ от Зелова». */
export function describePlace(T: Theatre, at: LngLat): string {
  let best: { title: string; at: LngLat } | null = null, bd = Infinity;
  const p = T.proj.toXY(at);
  for (const a of places(T)) {
    const d = dist(p, T.proj.toXY(a.at));
    if (d < bd) { bd = d; best = a; }
  }
  if (!best) return `${at[1].toFixed(2)}° с.ш., ${at[0].toFixed(2)}° в.д.`;
  const near = Math.max(1.5, T.cellKm * 3);
  if (bd <= near) return `у ${best.title}`;
  return `${bd < 10 ? bd.toFixed(1).replace('.', ',') : Math.round(bd)} км к ${rumb(T, best.at, at)} от ${best.title}`;
}

/** Цель приказа словами: пункт, точка или формирование. */
export function describeTarget(ctx: SimContext, t: Target | undefined, names: Map<string, string>): string {
  if (!t) return 'на месте';
  if (Array.isArray(t)) return describePlace(ctx.theatre, t);
  if (typeof t === 'object') return `против: ${names.get(t.formation) ?? t.formation}`;
  const a = ctx.theatre.area(t);
  return a ? areaTitle(a.name) : t;
}

export function estimate(f: Pick<Formation, 'personnel' | 'tanks' | 'guns'>): string {
  const parts = [`до ${rough(f.personnel / 1000)} тыс. чел.`];
  if (f.tanks >= 5) parts.push(`около ${rough(f.tanks)} танков и САУ`);
  if (f.guns >= 50) parts.push(`около ${rough(f.guns)} орудий и минометов`);
  return parts.join(', ');
}

/**
 * Доклады армий и корпусов стороны по докладам их дивизий: в агентной модели действуют дивизии, а приказы удобно
 * отдавать и объединениям (ядро разошлёт приказ всем их дивизиям). Место — центр тяжести, силы — сумма, запасы и
 * укомплектованность — средние по численности, положение и задача — у большинства людей.
 */
export function hqReports(ctx: SimContext, own: UnitReport[], side: string): UnitReport[] {
  const parent = new Map(ctx.scenario.formations.map((f) => [f.id, f.parent ?? null]));
  const under = (id: string, hq: string) => { for (let x: string | null | undefined = parent.get(id), n = 0; x && n < 8; x = parent.get(x), n++) if (x === hq) return true; return false; };
  const top = <K extends string>(l: UnitReport[], key: (u: UnitReport) => K | null) => {
    const m = new Map<K, number>();
    for (const u of l) { const k = key(u); if (k) m.set(k, (m.get(k) ?? 0) + u.personnel); }
    return [...m].sort((a, b) => b[1] - a[1])[0]?.[0] ?? null;
  };
  return ctx.scenario.formations.filter((f) => f.side === side && (f.echelon === 'army' || f.echelon === 'corps') && !f.type).map((h): UnitReport | null => {
    const l = own.filter((u) => u.status === 'active' && under(u.id, h.id));
    if (!l.length) return null;
    const P = l.reduce((s, u) => s + u.personnel, 0) || 1;
    const w = (k: (u: UnitReport) => number) => l.reduce((s, u) => s + k(u) * u.personnel, 0) / P;
    const at: LngLat = [w((u) => u.at[0]), w((u) => u.at[1])];
    const task = top(l, (u) => u.task);
    return {
      id: h.id, name: h.name, parent: h.parent ?? null, echelon: h.echelon, status: 'active', at, place: describePlace(ctx.theatre, at),
      posture: top(l, (u) => u.posture) ?? '', task, target: task ? top(l.filter((u) => u.task === task), (u) => u.target) : null,
      orderSource: top(l, (u) => u.orderSource), personnel: Math.round(P), tanks: l.reduce((s, u) => s + u.tanks, 0), guns: l.reduce((s, u) => s + u.guns, 0),
      strength: w((u) => u.strength), ammo: +w((u) => u.ammo).toFixed(2), fuel: +w((u) => u.fuel).toFixed(2), fatigue: +w((u) => u.fatigue).toFixed(2),
      cutOff: l.some((u) => u.cutOff), movedKm: +w((u) => u.movedKm).toFixed(1), combats: [], pending: [],
    };
  }).filter((x): x is UnitReport => !!x);
}

/** Разведсводка стороны: обнаруженный противник (prev — для пометки «новое»). */
export function intelReport(ctx: SimContext, state: SimState, side: string, prev?: SimState | null): IntelReport[] {
  const T = ctx.theatre, km = detectKm(ctx);
  const pos = (s: SimState) => s.formations.filter((f) => onMap(f, s.time)).map((f) => ({ id: f.id, at: f.position, side: f.side, f }));
  const now = pos(state);
  const seen = detected(T, now.filter((u) => u.side === side), now.filter((u) => u.side !== side), km);
  const before = prev ? (() => { const p = pos(prev); return detected(T, p.filter((u) => u.side === side), p.filter((u) => u.side !== side), km); })() : null;
  const own = now.filter((u) => u.side === side);
  return now.filter((u) => seen.has(u.id)).map(({ f }) => {
    let nearest: IntelReport['nearest'] = null;
    for (const o of own) {
      const d = dist(T.proj.toXY(o.at), T.proj.toXY(f.position));
      if (!nearest || d < nearest.km) nearest = { name: o.f.name, km: +d.toFixed(1) };
    }
    return { id: f.id, name: f.name, at: f.position, place: describePlace(T, f.position), posture: POSTURE_RU[f.posture] ?? f.posture, estimate: estimate(f), nearest, fresh: !!before && !before.has(f.id) };
  }).sort((a, b) => (a.nearest?.km ?? 1e9) - (b.nearest?.km ?? 1e9));
}

/** Пункты театра вблизи войск стороны и обнаруженного противника (для приказов и обстановки модели). */
export function nearbyPlaces(ctx: SimContext, state: SimState, side: string, km: number, limit = 80) {
  const T = ctx.theatre;
  const live = state.formations.filter((f) => onMap(f, state.time));
  const seen = intelReport(ctx, state, side).map((x) => x.id);
  const pts = live.filter((f) => f.side === side || seen.includes(f.id)).map((f) => T.proj.toXY(f.position));
  return places(T).map((a) => {
    const q = T.proj.toXY(a.at);
    return { ...a, km: Math.min(...pts.map((p) => dist(p, q))) };
  }).filter((a) => a.km <= km).sort((a, b) => a.km - b.km).slice(0, limit);
}

/** Задержка доведения приказа до формирования, часов (по ступени). */
export function orderDelay(ctx: SimContext, f: Pick<Formation, 'side' | 'echelon'>): number {
  return profileOf(ctx, f.side).orderDelayHours[f.echelon as keyof ReturnType<typeof profileOf>['orderDelayHours']] ?? 0;
}

/** Именованные пункты театра с центрами (кэш на театр). */
export function places(T: Theatre) {
  let l = centers.get(T);
  if (!l) {
    l = T.data.areas.map((a) => ({ id: a.id, title: areaTitle(a.name), at: T.area(a.id)!.center }));
    centers.set(T, l);
  }
  return l;
}

/** Округлённо, как в разведсводке: 1 значащая цифра (до 10 — до единиц). */
function rough(n: number): string {
  if (n < 10) return String(Math.round(n));
  const p = Math.pow(10, Math.floor(Math.log10(n)));
  return (Math.round(n / p) * p).toLocaleString('ru');
}

/** Направление от a на b по восьми румбам (на плоскости театра: ось y — на север). */
export function rumb(T: Theatre, a: LngLat, b: LngLat): string {
  const p = T.proj.toXY(a), q = T.proj.toXY(b);
  const ang = (Math.atan2(q[0] - p[0], q[1] - p[1]) * 180) / Math.PI;
  return RUMB[((Math.round(ang / 45) % 8) + 8) % 8];
}

/** Доклады формирований стороны на утро (state — после хода; prev — до него, для итога суток). */
export function unitReports(ctx: SimContext, state: SimState, side: string, prev?: SimState | null): UnitReport[] {
  const T = ctx.theatre;
  const names = new Map(state.formations.map((f) => [f.id, f.name]));
  const before = new Map((prev?.formations ?? []).map((f) => [f.id, f]));
  const last = prev ? state.journal.slice(prev.journal.length) : [];
  const byId = new Map(state.formations.map((f) => [f.id, f]));
  return state.formations.filter((f) => f.side === side).map((f) => {
    const b = before.get(f.id);
    const status = f.destroyed ? 'destroyed' : onMap(f, state.time) ? 'active' : f.reserveFrom ? 'reserve' : 'arriving';
    const o = f.order;
    const tp = o ? targetPoint(ctx, o.target, byId) : null;
    return {
      id: f.id, name: f.name, parent: f.parent, echelon: f.echelon, status, ...(status === 'arriving' ? { arrives: f.enterAt! } : {}), ...(f.reserveFrom ? { reserveFrom: f.reserveFrom } : {}),
      at: f.position, place: describePlace(T, f.position), posture: POSTURE_RU[f.posture] ?? f.posture,
      task: o ? TASK_RU[o.task] : null, target: o ? (tp || o.target ? describeTarget(ctx, o.target, names) : 'на месте') : null, orderSource: o?.source ?? null,
      personnel: f.personnel, tanks: f.tanks, guns: f.guns,
      strength: f.initial.personnel ? f.personnel / f.initial.personnel : 1,
      ammo: f.ammo, fuel: f.fuel, fatigue: f.fatigue, cutOff: !!f.cutOff,
      movedKm: b ? +dist(T.proj.toXY(b.position), T.proj.toXY(f.position)).toFixed(1) : 0,
      combats: combatsOf(f.id, last, names),
      pending: state.pending.filter((p) => p.formation === f.id).map((p) => ({ task: TASK_RU[p.task], target: describeTarget(ctx, p.target, names), issuedAt: p.issuedAt })),
    } satisfies UnitReport;
  });
}

/** Детерминированный генератор случайных чисел (mulberry32): один и тот же seed — один и тот же прогон. */
export interface Rng {
  /** Равномерно на [0, 1). */
  next(): number;
  /** Нормальное распределение N(0, 1). */
  normal(): number;
  /** Текущее внутреннее состояние — для сохранения и продолжения прогона. */
  state(): number;
}

export function createRng(seed: number): Rng {
  let a = seed >>> 0;
  const next = () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
  return {
    next,
    normal() {
      const u = Math.max(next(), 1e-12), v = next();
      return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
    },
    state: () => a,
  };
}

/** Двоичная куча по приоритету. */
class Heap {
  private ids: number[] = []; private pr: number[] = [];
  get size() { return this.ids.length; }
  peek() { return this.pr[0]; }
  push(id: number, p: number) {
    const ids = this.ids, pr = this.pr;
    let i = ids.length; ids.push(id); pr.push(p);
    while (i > 0) { const q = (i - 1) >> 1; if (pr[q] <= p) break; ids[i] = ids[q]; pr[i] = pr[q]; i = q; }
    ids[i] = id; pr[i] = p;
  }
  pop(): number {
    const ids = this.ids, pr = this.pr, top = ids[0], lid = ids.pop()!, lp = pr.pop()!;
    if (ids.length) {
      let i = 0;
      for (;;) { let c = 2 * i + 1; if (c >= ids.length) break; if (c + 1 < ids.length && pr[c + 1] < pr[c]) c++; if (pr[c] >= lp) break; ids[i] = ids[c]; pr[i] = pr[c]; i = c; }
      ids[i] = lid; pr[i] = lp;
    }
    return top;
  }
}

export class RoadNet {
  readonly nodes: XY[] = [];
  readonly adj: { to: number; w: number }[][] = [];
  private readonly segs: [number, number][] = [];
  private readonly buckets = new Map<string, number[]>();
  private readonly B: number;

  constructor(readonly T: Theatre) {
    this.B = Math.max(0.5, T.cellKm * 2);
    // отрезки линий дорог (км); перекрёстки в данных театра не всегда общие вершины — достраиваются:
    // пересечения отрезков и концы линий, не доходящие до соседней улицы, режут отрезки
    const seg: [XY, XY][] = [];
    const ends: XY[] = [];
    for (const r of T.data.roads) {
      if (r.kind === 'rail' || r.line.length < 2) continue;
      const xy = r.line.map((p) => T.proj.toXY(p));
      for (let k = 1; k < xy.length; k++) if (xy[k][0] !== xy[k - 1][0] || xy[k][1] !== xy[k - 1][1]) seg.push([xy[k - 1], xy[k]]);
      ends.push(xy[0], xy[xy.length - 1]);
    }
    const bk = new Map<string, number[]>();
    const cells = (a: XY, b: XY, pad = 0) => {
      const out: string[] = [];
      for (let x = Math.floor((Math.min(a[0], b[0]) - pad) / this.B); x <= Math.floor((Math.max(a[0], b[0]) + pad) / this.B); x++)
        for (let y = Math.floor((Math.min(a[1], b[1]) - pad) / this.B); y <= Math.floor((Math.max(a[1], b[1]) + pad) / this.B); y++) out.push(`${x},${y}`);
      return out;
    };
    seg.forEach(([a, b], i) => { for (const k of cells(a, b)) { const l = bk.get(k); if (l) l.push(i); else bk.set(k, [i]); } });
    const cuts: number[][] = seg.map(() => []);
    const extra: [XY, XY][] = [];
    // пересечения
    for (const list of bk.values()) for (let x = 0; x < list.length; x++) for (let y = x + 1; y < list.length; y++) {
      const i = list[x], j = list[y];
      const [p, p2] = seg[i], [q, q2] = seg[j];
      const r0 = p2[0] - p[0], r1 = p2[1] - p[1], s0 = q2[0] - q[0], s1 = q2[1] - q[1];
      const den = r0 * s1 - r1 * s0;
      if (Math.abs(den) < 1e-12) continue;
      const t = ((q[0] - p[0]) * s1 - (q[1] - p[1]) * s0) / den, u = ((q[0] - p[0]) * r1 - (q[1] - p[1]) * r0) / den;
      if (t > 1e-6 && t < 1 - 1e-6 && u >= -1e-6 && u <= 1 + 1e-6) cuts[i].push(t);
      if (u > 1e-6 && u < 1 - 1e-6 && t >= -1e-6 && t <= 1 + 1e-6) cuts[j].push(u);
    }
    // концы линий у соседней улицы (недотянутые перекрёстки)
    const gap = Math.max(0.02, Math.min(0.08, T.cellKm * 0.25));
    for (const e of ends) {
      let best: { i: number; t: number; d: number } | null = null;
      for (const k of cells(e, e, gap)) for (const i of bk.get(k) ?? []) {
        const [a, b] = seg[i], dx = b[0] - a[0], dy = b[1] - a[1], L = dx * dx + dy * dy || 1;
        const t = Math.max(0, Math.min(1, ((e[0] - a[0]) * dx + (e[1] - a[1]) * dy) / L));
        const d = Math.hypot(a[0] + dx * t - e[0], a[1] + dy * t - e[1]);
        if (d > 1e-6 && d <= gap && (!best || d < best.d)) best = { i, t, d };
      }
      if (!best) continue;
      const [a, b] = seg[best.i];
      const q: XY = [a[0] + (b[0] - a[0]) * best.t, a[1] + (b[1] - a[1]) * best.t];
      if (best.t > 1e-6 && best.t < 1 - 1e-6) cuts[best.i].push(best.t);
      extra.push([e, q]);
    }
    const ids = new Map<string, number>();
    const node = (p: XY) => {
      const k = `${p[0].toFixed(4)},${p[1].toFixed(4)}`;
      let i = ids.get(k);
      if (i == null) { i = this.nodes.length; ids.set(k, i); this.nodes.push(p); this.adj.push([]); }
      return i;
    };
    const edge = (a: XY, b: XY) => {
      const u = node(a), v = node(b);
      if (u === v) return;
      const w = Math.hypot(b[0] - a[0], b[1] - a[1]);
      this.adj[u].push({ to: v, w }); this.adj[v].push({ to: u, w });
      const s = this.segs.length;
      this.segs.push([u, v]);
      for (const k of cells(a, b)) { const l = this.buckets.get(k); if (l) l.push(s); else this.buckets.set(k, [s]); }
    };
    seg.forEach(([a, b], i) => {
      const ts = [0, ...cuts[i].sort((x, y) => x - y), 1];
      for (let k = 1; k < ts.length; k++) if (ts[k] - ts[k - 1] > 1e-9) edge([a[0] + (b[0] - a[0]) * ts[k - 1], a[1] + (b[1] - a[1]) * ts[k - 1]], [a[0] + (b[0] - a[0]) * ts[k], a[1] + (b[1] - a[1]) * ts[k]]);
    });
    for (const [a, b] of extra) edge(a, b);
  }

  get empty() { return this.segs.length === 0; }
  // … строки 95–144

/** Убрать повторы и точки на прямой. */
function dedupe(p: XY[]): XY[] {
  const o: XY[] = [];
  for (const q of p) {
    const l = o[o.length - 1];
    if (l && Math.hypot(q[0] - l[0], q[1] - l[1]) < 1e-3) continue;
    if (o.length >= 2) {
      const a = o[o.length - 2];
      const cross = (l[0] - a[0]) * (q[1] - a[1]) - (l[1] - a[1]) * (q[0] - a[0]);
      const dot = (l[0] - a[0]) * (q[0] - l[0]) + (l[1] - a[1]) * (q[1] - l[1]);
      if (Math.abs(cross) < 1e-6 && dot > 0) { o[o.length - 1] = q; continue; }
      // разворот назад (шпора: дошли до узла и вернулись) — вершину убрать
      const L1 = Math.hypot(l[0] - a[0], l[1] - a[1]), L2 = Math.hypot(q[0] - l[0], q[1] - l[1]);
      if (dot < -0.85 * L1 * L2) { o.pop(); if (o.length >= 1 && Math.hypot(q[0] - o[o.length - 1][0], q[1] - o[o.length - 1][1]) < 1e-3) continue; o.push(q); continue; }
    }
    o.push(q);
  }
  return o;
}

/** Упрощение ломаной (Дуглас — Пекер), tol — км. */
function douglas(p: XY[], tol: number): XY[] {
  if (p.length < 3) return p;
  const keep = new Uint8Array(p.length);
  keep[0] = keep[p.length - 1] = 1;
  const stack: [number, number][] = [[0, p.length - 1]];
  while (stack.length) {
    const [a, b] = stack.pop()!;
    const [ax, ay] = p[a], [bx, by] = p[b], dx = bx - ax, dy = by - ay, L = Math.hypot(dx, dy) || 1e-9;
    let worst = -1, wd = tol;
    for (let i = a + 1; i < b; i++) {
      const d = Math.abs((p[i][0] - ax) * dy - (p[i][1] - ay) * dx) / L;
      if (d > wd) { wd = d; worst = i; }
    }
    if (worst > 0) { keep[worst] = 1; stack.push([a, worst], [worst, b]); }
  }
  return p.filter((_, i) => keep[i]);
}

/** Сглаживание ломаной по клеткам (Чайкин, концы на месте). */
function smooth(p: XY[]): XY[] {
  if (p.length < 3) return p;
  let a = dedupe(p);
  for (let it = 0; it < 2; it++) {
    const o: XY[] = [a[0]];
    for (let i = 0; i < a.length - 1; i++) {
      const [x0, y0] = a[i], [x1, y1] = a[i + 1];
      o.push([x0 * 0.75 + x1 * 0.25, y0 * 0.75 + y1 * 0.25], [x0 * 0.25 + x1 * 0.75, y0 * 0.25 + y1 * 0.75]);
    }
    o.push(a[a.length - 1]);
    a = o;
  }
  return a;
}

/**
 * Путь для показа: участки по клеткам с дорогой — по линиям дорог (кратчайший путь по графу), остальное — по
 * клеткам. Начало и конец — как в расчёте.
 */
export function visualPath(T: Theatre, trail: LngLat[]): LngLat[] {
  if (trail.length < 2) return trail;
  const net = roadNet(T);
  const xy = trail.map((p) => T.proj.toXY(p));
  // точки пути через полклетки
  const step = T.cellKm / 2;
  const pts: XY[] = [xy[0]];
  for (let i = 1; i < xy.length; i++) {
    const a = xy[i - 1], b = xy[i], L = Math.hypot(b[0] - a[0], b[1] - a[1]), n = Math.max(1, Math.ceil(L / step));
    for (let k = 1; k <= n; k++) pts.push([a[0] + ((b[0] - a[0]) * k) / n, a[1] + ((b[1] - a[1]) * k) / n]);
  }
  if (net.empty) return douglas(smooth(pts), Math.max(0.01, T.cellKm * 0.08)).map((p) => T.proj.toLL(p));
  const reach = T.cellKm * 0.9;
  const tol = Math.max(0.01, T.cellKm * 0.08);
  // весь ход — улицами, если начало и конец у дороги и путь по ним не длиннее полутора расчётных
  let trailKm = 0;
  for (let i = 1; i < xy.length; i++) trailKm += Math.hypot(xy[i][0] - xy[i - 1][0], xy[i][1] - xy[i - 1][1]);
  // начало и конец могут быть внутри квартала (положение — центр участка): выход к ближайшей улице, не дальше
  // трети пути и километра
  const edgeKm = Math.max(reach, Math.min(1, trailKm * 0.35));
  // целиком по улицам — только там, где войска и в расчёте шли дорогами или городом: полем, лесом, болотом —
  // как в расчёте (по участкам с дорогой — по дороге), чтобы показ не прятал выбор пути вне дорог
  const cellOf = pts.map((p) => T.indexOf(T.proj.toLL(p)));
  const share = (f: (i: number) => boolean) => cellOf.filter((i) => i >= 0 && f(i)).length / pts.length;
  const urban = TERRAIN_CLASSES.indexOf('urban');
  const streetwise = share((i) => T.terrain[i] === urban) >= 0.5 || share((i) => T.road[i] > 0) >= 0.6;
  const sa = streetwise ? net.snap(xy[0], edgeKm) : null, sb = streetwise ? net.snap(xy[xy.length - 1], edgeKm) : null;
  if (sa && sb) {
    const whole = net.between(sa, sb, trailKm * 1.5);
    if (whole) return douglas(dedupe([xy[0], ...whole, xy[xy.length - 1]]), tol).map((p) => T.proj.toLL(p));
  }
  const snaps = pts.map((p, k) => { const i = cellOf[k]; return i >= 0 && T.road[i] ? net.snap(p, reach) : null; });
  // куски: по линиям дорог — как есть; вне линий (поле, дороги только растром) — по клеткам, сглаженные
  const out: XY[] = [];
  let free: XY[] = [pts[0]];
  const flush = () => { out.push(...(free.length >= 3 ? smooth(free) : free)); free = []; };
  for (let i = 1; i < pts.length;) {
    if (!snaps[i]) { free.push(pts[i]); i++; continue; }
    flush();
    // участок по дороге: от первой до последней точки подряд с дорогой
    // короткий разрыв (срезанный угол квартала, до клетки) участок по дороге не прерывает
    let j = i;
    for (;;) {
      if (j + 1 < pts.length && snaps[j + 1]) { j++; continue; }
      const k = [2, 3].map((g) => j + g).find((x) => x < pts.length && snaps[x]);
      if (k == null) break;
      j = k;
    }
    let runKm = 0;
    for (let k = i + 1; k <= j; k++) runKm += Math.hypot(pts[k][0] - pts[k - 1][0], pts[k][1] - pts[k - 1][1]);
    const road = j > i ? net.between(snaps[i]!, snaps[j]!, runKm * 1.8 + T.cellKm * 2) : null;
    if (road) out.push(...road); else for (let k = i; k <= j; k++) out.push(snaps[k]?.p ?? pts[k]);
    i = j + 1;
    if (i < pts.length) free = [out[out.length - 1]];
  }
  flush();
  out.push(xy[xy.length - 1]);
  // упростить с допуском в десятки метров: путь тот же, кадров меньше
  return douglas(dedupe(out), Math.max(0.01, T.cellKm * 0.08)).map((p) => T.proj.toLL(p));
}

/** Составляющие силы — для объяснения исхода («почему так»). */
export interface PowerBreakdown {
  base: number;
  quality: number;
  supply: number;
  fatigue: number;
  total: number;
}

/** Значение таблицы; по соотношению сил — интерполяция в логарифмической шкале. */
export function interp(table: Table, x: number, logScale = true): number {
  if (!table.length) return 0;
  const f = (v: number) => (logScale ? Math.log(Math.max(v, 1e-6)) : v);
  if (x <= table[0][0]) return table[0][1];
  if (x >= table[table.length - 1][0]) return table[table.length - 1][1];
  for (let i = 1; i < table.length; i++) {
    const [x1, y1] = table[i];
    if (x <= x1) {
      const [x0, y0] = table[i - 1];
      const t = (f(x) - f(x0)) / (f(x1) - f(x0));
      return y0 + (y1 - y0) * t;
    }
  }
  return table[table.length - 1][1];
}

export function power(f: Formation, profile: SideProfile, rules: Rules): PowerBreakdown {
  const w = profile.weights;
  const base = (f.personnel / 1000) * w.personnel + f.tanks * w.tanks + f.guns * w.guns;
  const type = profile.unitTypes[f.type];
  const quality = type?.quality ?? 1;
  let supply = 1;
  if (f.ammo < 0.5) supply *= rules.ammoShort + (1 - rules.ammoShort) * (f.ammo / 0.5);
  if (type && type.mobility !== 'foot' && f.fuel <= 0) supply *= rules.fuelOut;
  const fatigue = 1 - f.fatigue * rules.fatigueEffect;
  return { base, quality, supply, fatigue, total: base * quality * supply * fatigue };
}

export interface SectorLine {
  /** Пара объединений (по алфавиту). */
  pair: [string, string];
  points: LngLat[];
  /** Доля длины по исторической линии. */
  historical: number;
}

export interface SectorMap {
  side: string;
  level: SectorLevel;
  /** Объединения стороны (индекс — значение label). */
  groups: string[];
  /** Сетка полос: шаг stepKm, клетки сетки театра, сгруппированные по step × step. */
  step: number;
  stepKm: number;
  cols: number;
  rows: number;
  /** Объединение клетки (индекс в groups), −1 — дальше reachKm от войск стороны. */
  label: Int16Array;
  /** 1 — клетка поделена по исторической линии (директиве). */
  hist: Uint8Array;
  /** Расстояние до ближайших своих и чужих войск, км (для линий на карте: только своя сторона от переднего края). */
  ownKm: Float32Array;
  enemyKm: Float32Array;
  /** Действующие линии этой стороны. */
  boundaries: Boundary[];
}

export interface SectorOptions {
  level?: SectorLevel;
  /** Дальше этого от своих войск полосы не продолжаются, км (по умолчанию 80, но не меньше 6 клеток театра). */
  reachKm?: number;
  /** Шаг сетки полос, км (по умолчанию — две клетки театра, но не мельче 1 км на оперативном театре). */
  stepKm?: number;
  groups?: Map<string, string>;
}

export interface SectorViolation {
  formation: string;
  group: string;
  /** В чьей полосе (по директиве) оказалось. */
  in: string;
  time: string;
  boundary: string;
}

/** Разграничительные линии, действующие в момент time (наземные; авиационные — только для карты). */
export function activeBoundaries(scenario: Scenario, time: string, side?: string): Boundary[] {
  return (scenario.boundaries ?? []).filter((b) => b.kind !== 'air' && (!side || b.side === side) && b.from <= time && (!b.until || time < b.until));
}

/** Центр клетки сетки полос (км). */
function centerOf(T: Theatre, step: number, c: number, r: number): XY {
  const o = T.cellCenter(0, 0), s = step * T.cellKm;
  return [o[0] - T.cellKm / 2 + (c + 0.5) * s, o[1] - T.cellKm / 2 + (r + 0.5) * s];
}

/**
 * Условия вступления директив (игра): линия сценария с условием, ещё не вступившая, вступает, если войска её
 * объединения trigger.group — в радиусе от точки; срок — через delayHours (по умолчанию 6 ч). Возвращает новые записи.
 */
export function checkTriggers(T: Theatre, scenario: Scenario, state: SimState, now: string, addHours: (t: string, h: number) => string): Record<string, string> {
  const d = state.directives;
  if (!d?.conditional) return {};
  const groups = groupOf(scenario, 'front');
  const fresh: Record<string, string> = {};
  for (const b of scenario.boundaries ?? []) {
    if (!b.trigger || d.activated[b.id]) continue;
    const at = T.proj.toXY(b.trigger.at);
    const hit = state.formations.some((f) => !f.destroyed && (!f.enterAt || f.enterAt <= now) && (groups.get(f.id) ?? f.id) === b.trigger!.group
      && Math.hypot(T.proj.toXY(f.position)[0] - at[0], T.proj.toXY(f.position)[1] - at[1]) <= b.trigger!.radiusKm);
    if (hit) fresh[b.id] = addHours(now, b.delayHours ?? 6);
  }
  return fresh;
}

/**
 * Линии с действительными сроками: линии сценария (в игре — с условием вступления: только вступившие, с момента
 * вступления) и линии, установленные в ходе игры (модель-Ставка, игрок). Новая линия той же пары и того же рода
 * заканчивает срок прежней.
 */
export function effectiveBoundaries(scenario: Scenario, state?: Pick<SimState, 'directives' | 'boundaries'> | null): Boundary[] {
  const cond = !!state?.directives?.conditional, act = state?.directives?.activated ?? {};
  const base = (scenario.boundaries ?? []).flatMap((b) => {
    if (!cond || !b.trigger) return [b];
    return act[b.id] ? [{ ...b, from: act[b.id] }] : [];
  });
  const all = [...base, ...(state?.boundaries ?? [])];
  const groups = new Map<string, Boundary[]>();
  for (const b of all) { const k = pairKey(b); groups.set(k, [...(groups.get(k) ?? []), b]); }
  const out: Boundary[] = [];
  for (const list of groups.values()) {
    list.sort((x, y) => x.from.localeCompare(y.from));
    list.forEach((b, i) => {
      const next = list.slice(i + 1).find((x) => x.from > b.from)?.from ?? null;
      // в игре срок линии сценария — до следующей вступившей (расписание сценария не действует)
      const own = cond && (b.issuedBy ?? 'scenario') === 'scenario' && b.kind !== 'air' ? null : b.until ?? null;
      const until = next && (!own || next < own) ? next : own;
      out.push({ ...b, until });
    });
  }
  return out.sort((x, y) => x.from.localeCompare(y.from));
}

/** Объединение уровня level для каждого формирования сценария: фронт (группа армий) или армия; нет такого предка — верхний предок. */
export function groupOf(scenario: Scenario, level: SectorLevel = 'front'): Map<string, string> {
  const defs = new Map(scenario.formations.map((f) => [f.id, f]));
  const want: Echelon = level;
  const out = new Map<string, string>();
  for (const f of scenario.formations) {
    let cur = f, hit = f.echelon === want ? f : null;
    const seen = new Set([f.id]);
    while (cur.parent && defs.has(cur.parent) && !seen.has(cur.parent)) {
      cur = defs.get(cur.parent)!;
      seen.add(cur.id);
      if (cur.echelon === want && (level === 'front' || !hit)) hit = cur;
    }
    out.set(f.id, (hit ?? cur).id);
  }
  // соединение без объединения нужного уровня (дивизия СС без подчинения в сценарии) — к единственному объединению
  // этого уровня своей стороны, если оно одно; армия без фронта (12 А при ОКВ) остаётся отдельной полосой
  const ECH: Echelon[] = ['front', 'army', 'corps', 'division', 'brigade', 'regiment'];
  for (const f of scenario.formations) {
    const g = defs.get(out.get(f.id)!)!;
    if (g.echelon === want || ECH.indexOf(g.echelon) <= ECH.indexOf(want) + (level === 'front' ? 1 : 0)) continue;
    const only = [...new Set(scenario.formations.filter((x) => x.side === f.side && defs.get(out.get(x.id)!)!.echelon === want).map((x) => out.get(x.id)!))];
    if (only.length === 1) out.set(f.id, only[0]);
  }
  return out;
}

/** Объединение, в чьей полосе точка (id), или null. */
export function sectorAt(T: Theatre, m: SectorMap, at: LngLat): { group: string; historical: boolean } | null {
  const [c, r] = T.cellOfXY(T.proj.toXY(at));
  const cc = Math.floor(c / m.step), rr = Math.floor(r / m.step);
  if (cc < 0 || rr < 0 || cc >= m.cols || rr >= m.rows) return null;
  const k = rr * m.cols + cc;
  return m.label[k] < 0 ? null : { group: m.groups[m.label[k]], historical: !!m.hist[k] };
}

/** Где подписать полосу объединения: средняя точка его клеток у переднего края (в 3–25 км от противника). */
export function sectorLabels(T: Theatre, m: SectorMap): { group: string; at: LngLat; cells: number }[] {
  const acc = m.groups.map(() => ({ x: 0, y: 0, n: 0 }));
  for (let k = 0; k < m.label.length; k++) {
    const g = m.label[k];
    if (g < 0 || m.ownKm[k] > m.enemyKm[k] || m.enemyKm[k] < 3 || m.enemyKm[k] > 25) continue;
    const p = centerOf(T, m.step, k % m.cols, Math.floor(k / m.cols));
    acc[g].x += p[0]; acc[g].y += p[1]; acc[g].n++;
  }
  return acc.flatMap((a, i) => (a.n ? [{ group: m.groups[i], at: T.proj.toLL([a.x / a.n, a.y / a.n]), cells: a.n }] : []));
}

/**
 * Разграничительные линии на карте: границы полос между объединениями на своей стороне фронта — от переднего
 * края в глубину не дальше depthKm (по умолчанию 40 км). Сглажены; короче minKm — отбрасываются.
 */
export function sectorLines(T: Theatre, m: SectorMap, o: { depthKm?: number; minKm?: number } = {}): SectorLine[] {
  const depth = o.depthKm ?? 40, minKm = o.minKm ?? m.stepKm * 3;
  const ok = (k: number) => m.label[k] >= 0 && m.ownKm[k] <= m.enemyKm[k] && m.enemyKm[k] <= depth;
  // рёбра между клетками с разными объединениями: вершины сетки (c, r) — углы клеток
  type Edge = { a: number; b: number; pair: string; hist: boolean };
  const edges: Edge[] = [];
  const V = (c: number, r: number) => r * (m.cols + 1) + c;
  for (let r = 0; r < m.rows; r++) for (let c = 0; c < m.cols; c++) {
    const k = r * m.cols + c;
    if (!ok(k)) continue;
    for (const [dc, dr] of [[1, 0], [0, 1]] as const) {
      const c2 = c + dc, r2 = r + dr;
      if (c2 >= m.cols || r2 >= m.rows) continue;
      const k2 = r2 * m.cols + c2;
      if (!ok(k2) || m.label[k2] === m.label[k]) continue;
      const g = [m.groups[m.label[k]], m.groups[m.label[k2]]].sort().join('|');
      const hist = !!(m.hist[k] && m.hist[k2]);
      // общая сторона клеток: для соседа справа — вертикальная, снизу — горизонтальная
      if (dc) edges.push({ a: V(c + 1, r), b: V(c + 1, r + 1), pair: g, hist });
      else edges.push({ a: V(c, r + 1), b: V(c + 1, r + 1), pair: g, hist });
    }
  }
  const out: SectorLine[] = [];
  const byPair = new Map<string, Edge[]>();
  for (const e of edges) { const l = byPair.get(e.pair); if (l) l.push(e); else byPair.set(e.pair, [e]); }
  const c0 = T.cellCenter(0, 0);
  const vxy = (v: number): XY => [c0[0] - T.cellKm / 2 + (v % (m.cols + 1)) * m.stepKm, c0[1] - T.cellKm / 2 + Math.floor(v / (m.cols + 1)) * m.stepKm];
  for (const [pair, es] of byPair) {
    const adj = new Map<number, number[]>();
    const link = (v: number, i: number) => { const l = adj.get(v); if (l) l.push(i); else adj.set(v, [i]); };
    es.forEach((e, i) => { link(e.a, i); link(e.b, i); });
    const used = new Uint8Array(es.length);
    const chains: { vs: number[]; hist: number }[] = [];
    for (let s = 0; s < es.length; s++) {
      if (used[s]) continue;
      used[s] = 1;
      const vs = [es[s].a, es[s].b];
      let h = es[s].hist ? 1 : 0;
      // в обе стороны, пока есть неиспользованное ребро из конца цепочки
      for (const dir of [1, -1]) {
        for (;;) {
          const end = dir > 0 ? vs[vs.length - 1] : vs[0];
          const next = (adj.get(end) ?? []).find((i) => !used[i]);
          if (next == null) break;
          used[next] = 1;
          if (es[next].hist) h++;
          const v = es[next].a === end ? es[next].b : es[next].a;
          if (dir > 0) vs.push(v); else vs.unshift(v);
        }
      }
      chains.push({ vs, hist: h / (vs.length - 1) });
    }
    const [ga, gb] = pair.split('|');
    const bl = m.boundaries.find((b) => (b.right === ga && b.left === gb) || (b.right === gb && b.left === ga));
    const blXY = bl?.line.map((x) => T.proj.toXY(x));
    for (const ch of chains) {
      const raw = ch.vs.map(vxy);
      // по директиве — сама линия директивы на протяжении цепочки; иначе — ступеньки сетки, спрямлённые и сглаженные
      const xy = blXY && ch.hist >= 0.5 ? subLine(blXY, raw[0], raw[raw.length - 1]) : smooth(simplifyXY(raw, m.stepKm * 0.75), 2);
      let len = 0;
      for (let i = 1; i < xy.length; i++) len += Math.hypot(xy[i][0] - xy[i - 1][0], xy[i][1] - xy[i - 1][1]);
      if (len < minKm) continue;
      out.push({ pair: [ga, gb], points: simplifyXY(xy, m.stepKm * 0.1).map((p) => { const ll = T.proj.toLL(p); return [+ll[0].toFixed(4), +ll[1].toFixed(4)] as LngLat; }), historical: +ch.hist.toFixed(2) });
    }
  }
  return out;
}

/** Полосы стороны side в момент time по положению войск units. */
export function sectorMap(T: Theatre, scenario: Scenario, units: SectorUnit[], side: string, time: string, o: SectorOptions = {}): SectorMap {
  const level = o.level ?? 'front';
  const gOf = o.groups ?? groupOf(scenario, level);
  const step = Math.max(1, Math.round((o.stepKm ?? T.cellKm * 2) / T.cellKm));
  const stepKm = step * T.cellKm;
  const cols = Math.ceil(T.cols / step), rows = Math.ceil(T.rows / step);
  const reach = Math.max(o.reachKm ?? 80, T.cellKm * 6);
  const live = units.filter((u) => !u.destroyed);
  const own = live.filter((u) => u.side === side), enemy = live.filter((u) => u.side !== side);
  const groups = [...new Set(own.map((u) => gOf.get(u.id) ?? u.id))].sort();
  const gi = new Map(groups.map((g, i) => [g, i]));
  const ownXY = own.map((u) => ({ p: T.proj.toXY(u.at), g: gi.get(gOf.get(u.id) ?? u.id)! }));
  const enXY = enemy.map((u) => T.proj.toXY(u.at));
  const N = cols * rows;
  const label = new Int16Array(N).fill(-1), hist = new Uint8Array(N);
  const ownKm = new Float32Array(N), enemyKm = new Float32Array(N);
  for (let r = 0; r < rows; r++) for (let c = 0; c < cols; c++) {
    const k = r * cols + c, p = centerOf(T, step, c, r);
    // квадраты расстояний (без корня в цикле — сетка большого театра считается каждый ход)
    let best = Infinity, bg = -1;
    for (const u of ownXY) { const dx = u.p[0] - p[0], dy = u.p[1] - p[1], d = dx * dx + dy * dy; if (d < best) { best = d; bg = u.g; } }
    let be = Infinity;
    for (const q of enXY) { const dx = q[0] - p[0], dy = q[1] - p[1], d = dx * dx + dy * dy; if (d < be) be = d; }
    best = Math.sqrt(best); be = Math.sqrt(be);
    ownKm[k] = best; enemyKm[k] = be;
    if (best <= reach) label[k] = bg;
  }
  // исторические линии: клетки двух объединений пары — по сторонам линии (кроме зон за концами линии)
  const bs = activeBoundaries(scenario, time, side);
  for (const b of bs) {
    const R = gi.get(b.right), L = gi.get(b.left);
    if (R == null || L == null) continue;
    const line = b.line.map((x) => T.proj.toXY(x));
    for (let k = 0; k < N; k++) {
      if (label[k] !== R && label[k] !== L) continue;
      const s = sideOf(line, centerOf(T, step, k % cols, Math.floor(k / cols)));
      if (s === 0) continue;
      label[k] = s > 0 ? R : L;
      hist[k] = 1;
    }
  }
  return { side, level, groups, step, stepKm, cols, rows, label, hist, ownKm, enemyKm, boundaries: bs };
}

/**
 * Множитель «выгодности» клетки театра для выбора пути объединением group: в полосе соседа по директиве —
 * 1 + foreign (время движения не меняется — только выбор пути, как и разброс путей).
 */
export function sectorPrefer(T: Theatre, m: SectorMap, group: string, foreign: number): ((i: number) => number) | null {
  const g = m.groups.indexOf(group);
  if (g < 0 || foreign <= 0 || !m.boundaries.length) return null;
  return (i: number) => {
    const k = Math.floor(Math.floor(i / T.cols) / m.step) * m.cols + Math.floor((i % T.cols) / m.step);
    return m.hist[k] && m.label[k] >= 0 && m.label[k] !== g ? 1 + foreign : 1;
  };
}

/**
 * Полосы стороны словами (для штаба модели, советника и игрока): у каждого объединения — соседи и линия с ними
 * (по директиве: пункты и срок; иначе — «по расположению войск»), и кто из своих стоит в полосе соседа.
 */
export function sectorText(T: Theatre, scenario: Scenario, units: SectorUnit[], side: string, time: string, short: (id: string) => string = (id) => id): string[] {
  const groups = groupOf(scenario, 'front');
  const m = sectorMap(T, scenario, units, side, time, { groups });
  if (m.groups.length < 2) return m.groups.length ? [`Сторона действует одним объединением (${short(m.groups[0])}): разграничительных линий нет.`] : [];
  const pairs = new Set(sectorLines(T, m, { depthKm: 1e6, minKm: 0 }).map((l) => l.pair.join('|')));
  for (const b of m.boundaries) if (m.groups.includes(b.right) && m.groups.includes(b.left)) pairs.add([b.right, b.left].sort().join('|'));
  const out: string[] = [];
  for (const key of pairs) {
    const [a, b] = key.split('|');
    const d = m.boundaries.find((x) => (x.right === a && x.left === b) || (x.right === b && x.left === a));
    out.push(d
      ? `${short(a)} / ${short(b)} — по директиве (${d.title}): ${(d.places ?? []).join(' — ')}${d.inclusive ? `; пункты включительно — для ${short(d.inclusive)}` : ''}; справа по линии — ${short(d.right)}. За концами линии — по расположению войск.`
      : `${short(a)} / ${short(b)} — линия директивой не установлена: полосы по расположению войск.`);
  }
  for (const b of activeBoundaries(scenario, time, side).filter((x) => x.kind === 'army'))
    out.push(`${short(b.right)} / ${short(b.left)} — линия армий (${b.title}): ${(b.places?.length ? b.places : b.line.map((p) => `${p[1].toFixed(2)}° с. ш. ${p[0].toFixed(2)}° в. д.`)).join(' — ')}; справа по линии — ${short(b.right)}.`);
  const out2 = sectorViolations(T, scenario, units, time, groups).filter((v) => units.find((u) => u.id === v.formation)?.side === side);
  if (out2.length) out.push(`В полосе соседа: ${out2.map((v) => `${short(v.formation)} (в полосе ${short(v.in)})`).join(', ')}.`);
  return out;
}

/** Выходы формирований в полосу соседа по действующей директиве (по снимку положений). */
export function sectorViolations(T: Theatre, scenario: Scenario, units: SectorUnit[], time: string, groups?: Map<string, string>): SectorViolation[] {
  const gOf = groups ?? groupOf(scenario, 'front');
  const out: SectorViolation[] = [];
  for (const side of new Set(units.map((u) => u.side))) {
    const bs = activeBoundaries(scenario, time, side);
    if (!bs.length) continue;
    for (const u of units) {
      if (u.side !== side || u.destroyed) continue;
      const g = gOf.get(u.id) ?? u.id;
      for (const b of bs) {
        if (b.right !== g && b.left !== g) continue;
        const s = sideOf(b.line.map((x) => T.proj.toXY(x)), T.proj.toXY(u.at));
        const inG = s > 0 ? b.right : s < 0 ? b.left : g;
        if (inG !== g) out.push({ formation: u.id, group: g, in: inG, time, boundary: b.id });
      }
    }
  }
  return out;
}

/**
 * С какой стороны линии точка: 1 — справа (по ходу линии), −1 — слева, 0 — за концами линии
 * (ближайшая точка линии — её конец, а сама точка лежит дальше конца). open — линия продолжается
 * за концы (для «кто по какую сторону» — без зон за концами).
 */
export function sideOf(line: XY[], p: XY, open = false): -1 | 0 | 1 {
  let best = Infinity, cross = 0, beyond = false;
  for (let i = 1; i < line.length; i++) {
    const a = line[i - 1], b = line[i];
    const dx = b[0] - a[0], dy = b[1] - a[1], len2 = dx * dx + dy * dy || 1;
    const t = ((p[0] - a[0]) * dx + (p[1] - a[1]) * dy) / len2;
    const tc = Math.max(0, Math.min(1, t));
    const d = Math.hypot(a[0] + dx * tc - p[0], a[1] + dy * tc - p[1]);
    if (d < best - 1e-9) {
      best = d;
      // у внутренней вершины сторона — по биссектрисе: берём отрезок, к которому точка ближе по проекции
      cross = dx * (p[1] - a[1]) - dy * (p[0] - a[0]);
      beyond = (i === 1 && t < 0) || (i === line.length - 1 && t > 1);
    }
  }
  if (beyond && !open) return 0;
  return cross < 0 ? 1 : -1;
}

/** Дуглас — Пекер с допуском tol, км. */
function simplifyXY(p: XY[], tol: number): XY[] {
  if (p.length < 3) return p;
  const keep = new Uint8Array(p.length);
  keep[0] = keep[p.length - 1] = 1;
  const st: [number, number][] = [[0, p.length - 1]];
  while (st.length) {
    const [i, j] = st.pop()!;
    const a = p[i], b = p[j], dx = b[0] - a[0], dy = b[1] - a[1], L = Math.hypot(dx, dy) || 1;
    let md = 0, mk = -1;
    for (let k = i + 1; k < j; k++) { const d = Math.abs(dy * (p[k][0] - a[0]) - dx * (p[k][1] - a[1])) / L; if (d > md) { md = d; mk = k; } }
    if (md > tol && mk > 0) { keep[mk] = 1; st.push([i, mk], [mk, j]); }
  }
  return p.filter((_, i) => keep[i]);
}

/** Сглаживание ступенек сетки: Чайкин, концы на месте. */
function smooth(p: XY[], n: number): XY[] {
  let q = p;
  for (let k = 0; k < n && q.length > 2; k++) {
    const r: XY[] = [q[0]];
    for (let i = 0; i < q.length - 1; i++) {
      const a = q[i], b = q[i + 1];
      r.push([a[0] * 0.75 + b[0] * 0.25, a[1] * 0.75 + b[1] * 0.25], [a[0] * 0.25 + b[0] * 0.75, a[1] * 0.25 + b[1] * 0.75]);
    }
    r.push(q[q.length - 1]);
    q = r;
  }
  return q;
}

/** Часть ломаной между проекциями точек a и b на неё. */
function subLine(line: XY[], a: XY, b: XY): XY[] {
  const at = (p: XY) => {
    let best = Infinity, pos = 0, acc = 0, pt: XY = line[0];
    for (let i = 1; i < line.length; i++) {
      const u = line[i - 1], v = line[i], dx = v[0] - u[0], dy = v[1] - u[1], L = Math.hypot(dx, dy) || 1e-9;
      const t = Math.max(0, Math.min(1, ((p[0] - u[0]) * dx + (p[1] - u[1]) * dy) / (L * L)));
      const q: XY = [u[0] + dx * t, u[1] + dy * t], d = Math.hypot(q[0] - p[0], q[1] - p[1]);
      if (d < best) { best = d; pos = acc + t * L; pt = q; }
      acc += L;
    }
    return { pos, pt };
  };
  let s = at(a), e = at(b);
  if (s.pos > e.pos) [s, e] = [e, s];
  const out: XY[] = [s.pt];
  let acc = 0;
  for (let i = 1; i < line.length; i++) {
    acc += Math.hypot(line[i][0] - line[i - 1][0], line[i][1] - line[i - 1][1]);
    if (acc > s.pos && acc < e.pos) out.push(line[i]);
  }
  out.push(e.pt);
  return out;
}

/** Сценарий с действительными линиями (для деления полос, карты, отчёта и обстановки). */
export const withBoundaries = (scenario: Scenario, state?: Pick<SimState, 'directives' | 'boundaries'> | null): Scenario =>
  state?.directives || state?.boundaries?.length ? { ...scenario, boundaries: effectiveBoundaries(scenario, state) } : scenario;

/** Правила поверх базовых: поля переписываются, вложенные объекты — слиянием. */
export function mergeRules(base: Rules, over: Partial<Rules>): Rules {
  const b = base as unknown as Record<string, unknown>;
  const out: Record<string, unknown> = { ...b };
  for (const [k, v] of Object.entries(over)) {
    const x = b[k];
    out[k] = v && x && typeof v === 'object' && typeof x === 'object' && !Array.isArray(v) && !Array.isArray(x) ? { ...x, ...v } : v;
  }
  return out as unknown as Rules;
}

export async function rulesFrom(get: DataGetter, id: string): Promise<Rules> {
  const r = (await get('rules', `${id}.json`)) as Rules;
  return r.extends ? mergeRules(await rulesFrom(get, r.extends), r) : r;
}

/** Исполнить распоряжения в начале хода; неисполнимые — с причиной. */
export function applyActions(ctx: SimContext, state: SimState, actions: StaffAction[]): { state: SimState; results: { action: StaffAction; ok: boolean; text: string }[] } {
  let s: SimState = { ...state, formations: [...state.formations], logistics: state.logistics ? { ...state.logistics } : undefined };
  const results: { action: StaffAction; ok: boolean; text: string }[] = [];
  let bridges = 0;
  for (const a of actions) {
    const c = checkAction(ctx, s, a, 0);
    results.push({ action: a, ok: c.ok, text: c.text });
    if (!c.ok) continue;
    if (a.kind === 'base') {
      const lg = s.logistics![a.side];
      s.logistics![a.side] = { ...lg, bases: lg.bases.map((b) => (b.id === a.base ? { ...b, at: a.to, name: a.toName ?? describePlace(ctx.theatre, a.to).replace(/^у /, ''), activeFrom: c.eta!, moved: true } : b)) };
    } else if (a.kind === 'priority') {
      const lg = s.logistics?.[a.side] ?? { bases: [], priority: [] };
      s.logistics = { ...(s.logistics ?? {}), [a.side]: { ...lg, priority: [...a.formations] } };
    } else if (a.kind === 'bridge') {
      bridges++;
      ctx.theatre.addBridge({ id: `u_${s.time}_${bridges}`, at: c.at!, name: `переправа ${describePlace(ctx.theatre, c.at!)}`, openFrom: c.eta!, side: a.side, kind: 'crossing' });
    } else if (a.kind === 'demolish') {
      ctx.theatre.destroyBridge(c.bridge!, c.eta!);
    } else if (a.kind === 'boundary' || a.kind === 'directive') {
      const b = lineOf(ctx, s, a);
      if (typeof b !== 'string') { const { rightName: _r, ...line } = b; s.boundaries = [...(s.boundaries ?? []), line]; }
    } else {
      s.formations = s.formations.map((f) => (f.id === a.formation ? { ...f, position: a.at, enterAt: c.eta!, reserveFrom: undefined } : f));
    }
  }
  s = { ...s };
  return { state: s, results };
}

/** Проверить распоряжение: исполнимо ли, когда вступит в силу. pendingBridges — сколько переправ уже наводится в этом же распоряжении. */
export function checkAction(ctx: SimContext, state: SimState, a: StaffAction, pendingBridges = 0): ActionCheck {
  const T = ctx.theatre, t = state.time;
  if (a.kind === 'base') {
    const b = state.logistics?.[a.side]?.bases.find((x) => x.id === a.base);
    if (!b) return { ok: false, text: 'нет такой базы снабжения' };
    if (!own(ctx, state, a.side, a.to)) return { ok: false, text: 'новое место базы — не на своей территории' };
    const ps = profileOf(ctx, a.side).supply;
    const km = dist(T.proj.toXY(b.at), T.proj.toXY(a.to));
    const h = (ps?.baseSetupHours ?? 24) + (km / (ps?.baseMoveKmPerDay ?? 60)) * 24;
    const eta = addHours(t, Math.round(h));
    return { ok: true, text: `перенос ${Math.round(km)} км; на время переноса база не действует; заработает ≈ ${eta.slice(8, 10)}.${eta.slice(5, 7)} ${eta.slice(11, 16)}`, eta };
  }
  if (a.kind === 'priority') {
    const n = state.formations.filter((f) => f.side === a.side && onMap(f, t)).length;
    const lim = Math.max(1, Math.ceil(n / 3));
    if (a.formations.length > lim) return { ok: false, text: `приоритет — не более чем трети объединений (${lim})` };
    return { ok: true, text: a.formations.length ? `приоритетным — подвоз ×1,5, остальным — ×0,75` : 'подвоз поровну' };
  }
  if (a.kind === 'bridge') {
    const eng = profileOf(ctx, a.side).engineering ?? ENGINEERING;
    const r = T.nearestRiver(a.at, Math.max(2, T.cellKm * 1.5));
    if (!r) return { ok: false, text: 'здесь нет реки — переправа не нужна' };
    if (T.bridgeOpen(r.i, t)) return { ok: false, text: 'здесь уже есть действующая переправа' };
    const building = T.data.bridges.filter((b) => b.side === a.side && b.openFrom && b.openFrom > t).length + pendingBridges;
    if (building >= eng.parks) return { ok: false, text: `все понтонные парки заняты (одновременно — ${eng.parks})` };
    const reachKm = Math.max(10, ctx.rules.contactKm * 2);
    const near = state.formations.some((f) => f.side === a.side && onMap(f, t) && dist(T.proj.toXY(f.position), T.proj.toXY(r.at)) <= reachKm);
    if (!near) return { ok: false, text: `рядом (до ${reachKm} км) нет наших войск — некому прикрыть наводку` };
    const eta = addHours(t, r.major ? eng.bridgeHoursMajor : eng.bridgeHoursMinor);
    return { ok: true, at: r.at, eta, text: `${r.major ? 'большая' : 'малая'} река; переправа будет готова ≈ ${eta.slice(8, 10)}.${eta.slice(5, 7)} ${eta.slice(11, 16)}` };
  }
  if (a.kind === 'demolish') {
    const P = T.proj.toXY(a.at);
    const open = T.data.bridges.filter((b) => (!b.openFrom || b.openFrom <= t) && (!b.destroyedAt || b.destroyedAt > t))
      .map((b) => ({ b, d: dist(T.proj.toXY(b.at), P) })).filter((x) => x.d <= Math.max(3, T.cellKm * 2)).sort((x, y) => x.d - y.d)[0];
    if (!open) return { ok: false, text: 'рядом нет действующего моста или переправы' };
    if (!own(ctx, state, a.side, open.b.at)) return { ok: false, text: 'мост не на нашей территории — подорвать некому' };
    const eta = addHours(t, 2);
    return { ok: true, at: open.b.at, eta, text: `${open.b.name ?? 'мост'} будет подорван ≈ ${eta.slice(8, 10)}.${eta.slice(5, 7)} ${eta.slice(11, 16)}`, bridge: open.b.id };
  }
  if (a.kind === 'boundary' || a.kind === 'directive') {
    const r = lineOf(ctx, state, a);
    if (typeof r === 'string') return { ok: false, text: r };
    const eta = r.from;
    return { ok: true, eta, at: a.line[0], text: `${r.title}: справа по линии — ${r.rightName}; вступит в силу ≈ ${eta.slice(8, 10)}.${eta.slice(5, 7)} ${eta.slice(11, 16)}` };
  }
  const f = state.formations.find((x) => x.id === a.formation);
  if (!f || f.side !== a.side || !f.reserveFrom) return { ok: false, text: 'это не резерв, ожидающий ввода' };
  if (!own(ctx, state, a.side, a.at)) return { ok: false, text: 'район сосредоточения — не на своей территории' };
  const eta = maxH(f.reserveFrom, addHours(t, 24));
  return { ok: true, eta, text: `сосредоточится в районе ≈ ${eta.slice(8, 10)}.${eta.slice(5, 7)} ${eta.slice(11, 16)}${f.reserveFrom > addHours(t, 24) ? ' (раньше резерв не готов)' : ''}` };
}

/**
 * Линия распоряжения (армии — игрок) или директивы (фронты — модель-Ставка): проверка и линия с определённой стороной.
 * Кто справа по ходу линии — по среднему положению войск каждого объединения; срок — задержка доведения армиям
 * или delayHours директивы.
 */
export function lineOf(ctx: SimContext, state: SimState, a: Extract<StaffAction, { kind: 'boundary' | 'directive' }>): (Boundary & { rightName: string }) | string {
  const level = a.kind === 'boundary' ? 'army' : 'front';
  const defs = new Map(ctx.scenario.formations.map((f) => [f.id, f]));
  const A = defs.get(a.a), B = defs.get(a.b);
  if (!A || !B || a.a === a.b) return 'нужны два разных объединения';
  if (A.side !== a.side || B.side !== a.side) return 'оба объединения должны быть своими';
  const echelons = level === 'army' ? ['army'] : ['front'];
  const t = commandTerms(ctx, a.side);
  if (!echelons.includes(A.echelon) || !echelons.includes(B.echelon)) return level === 'army' ? 'линия распоряжения — между армиями' : `${t.directive} — между ${t.groupsGen}`;
  const fronts = groupOf(ctx.scenario, 'front');
  if (level === 'army' && fronts.get(a.a) !== fronts.get(a.b)) return `армии разных ${t.groupsGen} — линию между ними устанавливает ${t.top}`;
  if (a.line.length < 2) return 'линия — хотя бы из двух точек';
  if (a.line.some((p) => ctx.theatre.indexOf(p) < 0)) return 'точка линии вне театра';
  const T = ctx.theatre, groups = groupOf(ctx.scenario, level);
  const line = a.line.map((p) => T.proj.toXY(p));
  const centre = (g: string) => {
    const ps = state.formations.filter((f) => !f.destroyed && onMap(f, state.time) && (groups.get(f.id) ?? f.id) === g).map((f) => T.proj.toXY(f.position));
    return ps.length ? sideOf(line, [ps.reduce((s, p) => s + p[0], 0) / ps.length, ps.reduce((s, p) => s + p[1], 0) / ps.length], true) : 0;
  };
  const sa = centre(a.a), sb = centre(a.b);
  if (!sa || !sb) return 'у одного из объединений нет войск на театре';
  if (sa === sb) return 'войска обоих объединений — по одну сторону линии';
  const [right, left] = sa > 0 ? [A, B] : [B, A];
  const delay = a.kind === 'boundary' ? profileOf(ctx, a.side).orderDelayHours.army ?? 6 : a.delayHours;
  const short = (n: string) => n.replace(/\s*\(.*?\)\s*/g, ' ').trim();
  return {
    id: `${a.kind === 'boundary' ? 'p' : 's'}_${a.issuedAt}_${[a.a, a.b].sort().join('_')}`, kind: level, side: a.side, right: right.id, left: left.id,
    title: `${short(right.name)} / ${short(left.name)} (${a.kind === 'boundary' ? 'распоряжение' : `${t.directive} ${t.topGen}`} ${a.issuedAt.slice(8, 10)}.${a.issuedAt.slice(5, 7)})`,
    from: addHours(a.issuedAt, Math.max(0, delay)), until: null, line: a.line, places: a.places, inclusive: null,
    note: a.kind === 'directive' ? a.reason : undefined, issuedBy: a.kind === 'boundary' ? 'player' : 'stavka', issuedAt: a.issuedAt, rightName: short(right.name),
  };
}

/** Передача командования человеку: будущие наводки его стороны сняты, резервы — к вводу по его решению, тыл — под его управлением. */
export function prepareTakeover(ctx: SimContext, state: SimState, side: string): SimState {
  const T = ctx.theatre;
  T.dropBridges((b) => b.side === side && !!b.openFrom && b.openFrom > state.time);
  const formations = state.formations.map((f) => (f.side === side && f.enterAt && f.enterAt > state.time && !f.destroyed && !f.detachFrom
    ? { ...f, reserveFrom: f.enterAt, enterAt: NOT_COMMITTED } : f));
  const names = new Map<string, string>();
  const sp = ctx.scenario.supply?.[side];
  for (const x of [...(sp?.sources ?? []), ...(sp?.phases ?? []).flatMap((p) => p.sources)]) {
    if (typeof x === 'string') { const a = T.area(x); if (a) names.set(a.center.join(','), areaTitle(a.name)); }
  }
  const bases = supplySources(ctx, side, state.time).map((at, k) => ({ id: `base${k + 1}`, name: names.get(at.join(',')) ?? describePlace(T, at).replace(/^у /, ''), at, activeFrom: null }));
  const logistics: Record<string, Logistics> = { ...(state.logistics ?? {}), [side]: { bases, priority: [] } };
  return { ...state, formations, logistics };
}

interface CombatEnv {
  byId: Map<string, Formation>;
  /** Часы подвоза к точке для формирования (Infinity — не доходит). */
  supplyHours: (f: Formation, at?: LngLat) => number;
  isCut: (f: Formation) => boolean;
  /** seed прогона — для разброса путей. */
  seed: number;
  /** Выбор пути: разброс путей и полосы по директивам. */
  prefer: (f: Formation, mob: Mobility) => ((i: number) => number) | undefined;
  /** Уровень укреплённости там, где стоит обороняющийся, с учётом прорыва полосы (rules.beltBreachKm). */
  fortAt: (at: LngLat) => number;
}

export interface SimContext {
  scenario: Scenario;
  theatre: Theatre;
  /** Профили сторон по id профиля. */
  profiles: Record<string, SideProfile>;
  rules: Rules;
  /** Агентная модель: действуют дивизии, армии и корпуса — узлы подчинения (приказ им ядро доводит до всех их дивизий). */
  agentModel?: boolean;
}

/**
 * Изменения по датам (Scenario.changes): исполняются в первом ходе, начало которого не раньше at, один раз (индексы
 * исполненных — в состоянии). Пополнение — к текущим силам и к начальным (укомплектованность); ещё не введённому
 * формированию — откладывается до ввода. Переподчинение — только существующему штабу, не себе и не своему потомку;
 * иначе — запись change-skipped с причиной. Возвращает индексы исполненных (undefined — изменений нет).
 */
function applyChanges(scen: Scenario, fs: Formation[], byId: Map<string, Formation>, now: string, done0: number[] | undefined, journal: JournalEntry[]): number[] | undefined {
  const list = scen.changes;
  if (!list?.length) return done0;
  const done = new Set(done0 ?? []);
  // подчинённость: штабы без положения (фронты) — из сценария, действующие формирования — из состояния
  const parentOf = new Map<string, string | null>(scen.formations.map((f) => [f.id, f.parent ?? null]));
  for (const f of fs) parentOf.set(f.id, f.parent);
  const skip = (i: number, formation: string, reason: string) => { done.add(i); journal.push({ kind: 'change-skipped', time: now, formation, change: i, reason }); };
  list.forEach((c, i) => {
    if (done.has(i) || c.at > now) return;
    const f = byId.get(c.formation);
    if (c.kind === 'reinforce') {
      if (!f) return skip(i, c.formation, `нет действующего формирования ${c.formation}`);
      if (f.destroyed) return skip(i, c.formation, 'формирование уже разгромлено — пополнять нечего');
      if (!onMap(f, now) || f.detachFrom) return; // ещё не введено — пополнение при вводе
      const got = { personnel: c.personnel ?? 0, tanks: c.tanks ?? 0, guns: c.guns ?? 0 };
      for (const k of ['personnel', 'tanks', 'guns'] as const) { f[k] += got[k]; f.initial[k] += got[k]; }
      done.add(i);
      journal.push({ kind: 'reinforced', time: now, formation: f.id, ...got });
      return;
    }
    if (c.parent === c.formation) return skip(i, c.formation, 'переподчинение самому себе');
    if (!parentOf.has(c.parent)) return skip(i, c.formation, `нет штаба ${c.parent} среди формирований сценария`);
    for (let p: string | null | undefined = c.parent, n = 0; p && n < 64; p = parentOf.get(p), n++) {
      if (p === c.formation) return skip(i, c.formation, `${c.parent} — в подчинении самого ${c.formation}: переподчинение образовало бы цикл`);
    }
    if (!f) return skip(i, c.formation, `нет действующего формирования ${c.formation}`);
    const from = f.parent;
    f.parent = c.parent;
    parentOf.set(f.id, c.parent);
    done.add(i);
    journal.push({ kind: 'resubordinated', time: now, formation: f.id, from, to: c.parent });
  });
  return [...done].sort((a, b) => a - b);
}

function applyLoss(f: Formation, frac: number) {
  const k = Math.max(0, 1 - frac);
  f.personnel = Math.round(f.personnel * k);
  f.tanks = Math.round(f.tanks * (1 - Math.min(1, frac * 1.3)));
  f.guns = Math.round(f.guns * (1 - Math.min(1, frac * 0.8)));
}

function centerXY(ps: XY[]): XY {
  return [ps.reduce((s, p) => s + p[0], 0) / ps.length, ps.reduce((s, p) => s + p[1], 0) / ps.length];
}

/**
 * Режим боя (rules.regimes): котёл — окружённые обороняются или прорываются; застройка — вся оборона в городе;
 * укреплённая полоса; переправа — между наступающими и обороняющимися большая река; лес и болото — там бо́льшая
 * часть обороны; иначе — открытая местность.
 */
export function combatRegime(att: Formation[], def: Formation[], T: Theatre, streetFight: boolean, fortLv: number): Regime {
  if (def.some((f) => f.cutOff) || att.some((f) => f.cutOff || f.order?.task === 'breakout')) return 'pocket';
  if (streetFight) return 'urban';
  if (fortLv) return 'belt';
  const a = centerXY(att.map((f) => T.proj.toXY(f.position)));
  const crosses = def.some((f) => {
    const d = T.proj.toXY(f.position), n = Math.max(2, Math.ceil(dist(a, d) / (T.cellKm / 2)));
    for (let k = 1; k < n; k++) {
      const i = T.indexOf(T.proj.toLL([a[0] + ((d[0] - a[0]) * k) / n, a[1] + ((d[1] - a[1]) * k) / n]));
      if (i >= 0 && T.river[i] === 2) return true;
    }
    return false;
  });
  if (crosses) return 'river';
  const wooded = def.filter((f) => ['forest', 'marsh'].includes(T.terrainAt(f.position))).length;
  return wooded * 2 > def.length ? 'forest' : 'open';
}

/** Начальное состояние: действующие формирования — те, у кого есть положение и тип. */
export function createState(ctx: SimContext, seed = 1): SimState {
  const defs = new Map(ctx.scenario.formations.map((f) => [f.id, f]));
  const formations: Formation[] = ctx.scenario.formations.filter((f) => (f.position || f.detachFrom) && f.type).map((f) => ({
    id: f.id, name: f.name, side: f.side, echelon: f.echelon, parent: f.parent ?? null, type: f.type!, position: f.position ?? defs.get(f.detachFrom!.formation)?.position ?? [0, 0],
    personnel: f.personnel ?? 0, tanks: f.tanks ?? 0, guns: f.guns ?? 0,
    initial: { personnel: f.personnel ?? 0, tanks: f.tanks ?? 0, guns: f.guns ?? 0 },
    ammo: f.ammo ?? 2, fuel: f.fuel ?? 2, fatigue: 0, posture: f.posture ?? 'defend', dugInHours: f.posture === 'defend' ? 48 : 0,
    order: null, route: null, destroyed: false, enterAt: f.enterAt ?? null, ...(f.detachFrom ? { detachFrom: f.detachFrom } : {}),
  }));
  return { scenario: ctx.scenario.id, time: ctx.scenario.start, turn: 0, formations, pending: [...ctx.scenario.orders], rngState: seed >>> 0, seed: seed >>> 0, journal: [] };
}

function hash3(a: number, b: number, c: number): number {
  let h = Math.imul(a ^ 0x9e3779b9, 0x85ebca6b) ^ Math.imul(b + 0x632be59b, 0xc2b2ae35) ^ c;
  h ^= h >>> 15; h = Math.imul(h, 0x2c1b3c6d); h ^= h >>> 12; h = Math.imul(h, 0x297a2d39); h ^= h >>> 15;
  return (h >>> 0) / 4294967296;
}

/**
 * Время подвоза до формирования, часов: к любой клетке его полосы в пределах половины дистанции боя —
 * армия и корпус занимают район в несколько км глубиной, подвоз приходит к их тыловой части,
 * а не к точке знака (иначе вплотную к узлу обороны противника знак «отрезан»).
 */
function hoursNear(ctx: SimContext, fld: Float64Array, at: LngLat): number {
  const T = ctx.theatre, supKm = Math.max(ctx.rules.contactKm / 2, 1);
  const i = T.indexOf(at);
  if (i < 0) return Infinity;
  const p0 = T.proj.toXY(at), c0 = i % T.cols, r0 = Math.floor(i / T.cols);
  const rc = Math.max(1, Math.ceil(supKm / T.cellKm) + 1);
  let best = Infinity;
  for (let r = r0 - rc; r <= r0 + rc; r++) for (let c = c0 - rc; c <= c0 + rc; c++) {
    if (!T.inside(c, r)) continue;
    const q = T.cellCenter(c, r);
    if (Math.hypot(q[0] - p0[0], q[1] - p0[1]) <= Math.max(supKm, T.cellKm * 1.5)) best = Math.min(best, fld[r * T.cols + c]);
  }
  return best;
}

/** Принять приказ в любой момент (от эксперта, модели или сценария): исполнение — после задержки доведения. */
export function issueOrder(state: SimState, order: Order): SimState {
  return { ...state, pending: [...state.pending, order] };
}

/** Подвижность формирования сейчас: техника без горючего идёт пешком. */
function mobilityOf(ctx: SimContext, f: Formation) {
  const type = profileOf(ctx, f.side).unitTypes[f.type];
  return type?.mobility === 'foot' || f.fuel > 0 ? type?.mobility ?? 'foot' : 'foot';
}

export function profileOf(ctx: SimContext, side: string): SideProfile {
  const s = ctx.scenario.sides.find((x) => x.id === side);
  const p = s && ctx.profiles[s.profile];
  if (!p) throw new Error(`нет профиля для стороны ${side}`);
  return p;
}

function resolveCombat(att: Formation[], def: Formation[], ctx: SimContext, rng: Rng, now: string, dt: number, journal: JournalEntry[], moved: Set<string>, env: CombatEnv, umpire: UmpireMod[]) {
  const T = ctx.theatre, R = ctx.rules;
  // поправки посредника: к бою, где участвует любое из названных формирований; одна на множитель (самая сильная)
  const ids = new Set([...att, ...def].map((f) => f.id));
  const mods = umpire.filter((m) => m.formations.some((id) => ids.has(id)));
  const um = (k: UmpireFactor) => {
    const ms = mods.filter((m) => m.factor === k);
    if (!ms.length) return 1;
    const m = ms.reduce((a, b) => (Math.abs(Math.log(b.mult)) > Math.abs(Math.log(a.mult)) ? b : a));
    return Math.min(UMPIRE_LIMITS[1], Math.max(UMPIRE_LIMITS[0], m.mult));
  };
  const A = att.reduce((s, f) => s + power(f, profileOf(ctx, f.side), R).total, 0) * um('attack');
  // превышение: средняя высота наступающих (по силе) против высоты каждого обороняющегося
  const HA = R.heightAdvantage;
  const hs = HA ? att.map((f) => ({ h: T.heightAt(f.position), w: power(f, profileOf(ctx, f.side), R).total })).filter((x) => x.h != null) : [];
  const hAtt = hs.length ? hs.reduce((s, x) => s + x.h! * x.w, 0) / Math.max(1e-9, hs.reduce((s, x) => s + x.w, 0)) : null;
  const dParts = def.map((f) => {
    const p = power(f, profileOf(ctx, f.side), R).total;
    const terrain = R.defense.terrain[T.terrainAt(f.position)] ?? 1;
    const prepared = f.posture === 'defend' && f.dugInHours >= R.defense.prepareHours ? R.defense.prepared : 1;
    const fort = 1 + R.defense.fortificationPerLevel * env.fortAt(f.position);
    const hd = HA && hAtt != null ? T.heightAt(f.position) : null;
    const height = HA && hd != null ? 1 + Math.max(-HA.max, Math.min(HA.max, ((hd - hAtt!) / HA.perM) * HA.bonus)) : 1;
    return { f, p, terrain, prepared, fort, height, total: p * terrain * prepared * fort * height };
  });
  const D = dParts.reduce((s, x) => s + x.total, 0) * um('defense');
  if (D <= 0 || A <= 0) return;
  const avg = (k: 'terrain' | 'prepared' | 'fort' | 'height') => dParts.reduce((s, x) => s + x[k] * x.p, 0) / Math.max(1e-9, dParts.reduce((s, x) => s + x.p, 0));
  const noise = Math.exp(R.noise * rng.normal());
  const ratio = (A / D) * noise;
  const day = dt / 24;
  // темп — по таблице от соотношения сил, с поправкой на местность обороняющихся (город — кварталами)
  const at = def.reduce((m, f) => Math.min(m, R.advanceTerrain?.[T.terrainAt(f.position)] ?? 1), 1);
  // укреплённая полоса: темп не выше предельного для её уровня («прогрызание» обороны)
  const fortLv = def.reduce((m, f) => Math.max(m, env.fortAt(f.position)), 0);
  const cap = fortLv && R.fortAdvanceKm ? R.fortAdvanceKm[Math.min(fortLv, R.fortAdvanceKm.length - 1)] ?? Infinity : Infinity;
  const streetFight = def.every((f) => T.terrainAt(f.position) === 'urban');
  const regime = combatRegime(att, def, T, streetFight, fortLv);
  const RG = R.regimes?.[regime] ?? {};
  const freePace = interp(R.advance, ratio) * at * (RG.advance ?? 1);
  const advancePerDay = Math.min(freePace, cap) * um('pace');
  // «удерживать любой ценой»: обороняющиеся не отходят и несут повышенные потери;
  // наступающие продвигаются, только если оборона прорвана (обходят узел сопротивления)
  // окружённые не могут отойти: держатся на месте с повышенными потерями
  const pinned = (f: Formation) => f.order?.task === 'hold' || !!f.cutOff;
  const holding = def.every(pinned);
  // прорыв — по темпу без предела полосы: предел ограничивает скорость «прогрызания», но не исключает прорыв
  const breakthrough = freePace >= BREAKTHROUGH_KM;
  // городской бой (rules.holdGivesGround): «держаться» — не отходить по своей воле, но квартал за кварталом уступать
  const yields = !!R.holdGivesGround;
  // уличный бой: оборона в застройке «держится», но наступающие берут квартал за кварталом (с городским темпом),
  // а не стоят перед узлом, пока он не рухнет целиком
  const advanceKm = holding && !breakthrough && !yields && !streetFight ? 0 : advancePerDay * day;
  const attackerLoss = interp(R.attackerLoss, ratio) * day * um('attackerLoss') * (RG.attackerLoss ?? 1);
  const defenderLoss = interp(R.defenderLoss, ratio) * day * (holding && advancePerDay > 0 ? 1.5 : 1) * um('defenderLoss') * (RG.defenderLoss ?? 1);
  const factors: CombatFactor[] = [
    { name: 'сила наступающих', value: +A.toFixed(1) },
    { name: 'сила обороняющихся (без поправок)', value: +dParts.reduce((s, x) => s + x.p, 0).toFixed(1) },
    { name: 'местность', value: +avg('terrain').toFixed(2) },
    { name: 'подготовленная оборона', value: +avg('prepared').toFixed(2) },
    { name: 'укрепления', value: +avg('fort').toFixed(2) },
    ...(HA && avg('height') !== 1 ? [{ name: 'превышение (высоты местности)', value: +avg('height').toFixed(2) }] : []),
    { name: 'случайность (разброс)', value: +noise.toFixed(2) },
    ...(at < 1 ? [{ name: 'темп по местности', value: +at.toFixed(2) }] : []),
    ...(R.regimes && (RG.advance ?? 1) !== 1 ? [{ name: `темп: ${REGIME_RU[regime]}`, value: RG.advance! }] : []),
    ...(Number.isFinite(cap) ? [{ name: 'предел темпа в укреплённой полосе, км/сут', value: cap }] : []),
    ...UMPIRE_FACTORS.filter((k) => um(k) !== 1).map((k) => ({ name: `посредник: ${UMPIRE_FACTOR_RU[k]} — ${mods.filter((m) => m.factor === k).map((m) => m.reason).join('; ')}`, value: +um(k).toFixed(2) })),
  ];
  for (const f of att) applyLoss(f, attackerLoss);
  for (const f of def) applyLoss(f, defenderLoss);

  // продвижение: наступающие — к своим целям, обороняющиеся отходят от центра наступающих
  if (advanceKm > 0.05) {
    const ca = centerXY(att.map((f) => T.proj.toXY(f.position)));
    for (const f of att) {
      const to = targetPoint(ctx, f.order?.target, env.byId);
      const p = T.proj.toXY(f.position);
      const goal = to ? T.proj.toXY(to) : null;
      if (!goal) continue;
      const d = dist(p, goal);
  // … строки 677–706

/**
 * Куда отходит обороняющийся: из 16 направлений — то, где подвоз ближе (к своим
 * тылам), при равенстве — прочь от наступающих.
 */
function retreatPoint(f: Formation, p: XY, attackersCenter: XY, km: number, T: Theatre, env: CombatEnv): LngLat {
  const away: XY = [p[0] - attackersCenter[0], p[1] - attackersCenter[1]];
  const an = Math.hypot(away[0], away[1]) || 1;
  let best: LngLat | null = null, bestScore = Infinity;
  for (let k = 0; k < 16; k++) {
    const a = (Math.PI * 2 * k) / 16;
    const q: XY = [p[0] + Math.cos(a) * km, p[1] + Math.sin(a) * km];
    const ll = T.proj.toLL(q);
    const h = env.supplyHours(f, ll);
    if (!Number.isFinite(h) || T.terrainAt(ll) === 'water') continue;
    const awayDot = (Math.cos(a) * away[0] + Math.sin(a) * away[1]) / an; // 1 — прямо от противника
    const score = h - awayDot * 6; // 6 ч подвоза ≈ выигрыш отхода прямо от противника
    if (score < bestScore) { bestScore = score; best = ll; }
  }
  return best ?? T.proj.toLL([p[0] + (away[0] / an) * km, p[1] + (away[1] / an) * km]);
}

/**
 * Полосы сторон по действующим линиям: множитель выбора пути для формирования (null — линий нет). Линии между
 * фронтами делят полосы фронтов, линии между армиями (распоряжения игрока) — полосы армий; множители перемножаются.
 */
function sectorPreferences(ctx: SimContext, scen: Scenario, units: Formation[], now: string): (f: Formation) => ((i: number) => number) | null {
  const k = ctx.rules.sectors?.foreign ?? 0;
  const act = activeBoundaries(scen, now);
  if (k <= 0 || !act.length) return () => null;
  const levels = (['front', 'army'] as const).filter((lv) => act.some((b) => b.kind === lv));
  const groups = Object.fromEntries(levels.map((lv) => { const key = `${lv}`; const c = groupCache.get(ctx.scenario) ?? {}; c[key] ??= groupOf(ctx.scenario, lv); groupCache.set(ctx.scenario, c); return [lv, c[key]]; })) as Record<'front' | 'army', Map<string, string>>;
  const pts = units.map((u) => ({ id: u.id, side: u.side, at: u.position }));
  const fns = new Map<string, ((i: number) => number) | null>();
  const maps = new Map<string, SectorMap | null>();
  return (f) => {
    const parts: ((i: number) => number)[] = [];
    for (const lv of levels) {
      const g = groups[lv].get(f.id) ?? f.id;
      const key = `${lv}|${f.side}|${g}`;
      if (!fns.has(key)) {
        const mk = `${lv}|${f.side}`;
        if (!maps.has(mk)) maps.set(mk, act.some((b) => b.kind === lv && b.side === f.side) ? sectorMap(ctx.theatre, { ...scen, boundaries: act.filter((b) => b.kind === lv) }, pts, f.side, now, { level: lv, groups: groups[lv] }) : null);
        const m = maps.get(mk);
        fns.set(key, m ? sectorPrefer(ctx.theatre, m, g, k) : null);
      }
      const fn = fns.get(key);
      if (fn) parts.push(fn);
    }
    return !parts.length ? null : parts.length === 1 ? parts[0] : (i: number) => parts.reduce((a, p) => a * p(i), 1);
  };
}

export function step(prev: SimState, ctx: SimContext): SimState {
  const dt = ctx.scenario.turnHours;
  const now = prev.time;
  const end = addHours(now, dt);
  const rng = createRng(prev.rngState);
  const T = ctx.theatre, R = ctx.rules;
  const fs: Formation[] = prev.formations.map((f) => ({ ...f, position: [...f.position] as LngLat }));
  const byId = new Map(fs.map((f) => [f.id, f]));
  const journal: JournalEntry[] = [];
  const xy = (f: Formation): XY => T.proj.toXY(f.position);
  const active = () => fs.filter((f) => onMap(f, now));

  // 0. выделение корпусов и отрядов: в момент enterAt — там, где стоит родитель, с долей его сил
  for (const f of fs) {
    const d = f.detachFrom;
    if (!d || !f.enterAt || f.enterAt > now) continue;
    const p = byId.get(d.formation);
    f.detachFrom = undefined;
    if (!p || p.destroyed) { f.destroyed = true; continue; }
    const take = (k: 'personnel' | 'tanks' | 'guns') => Math.min(p[k], d[k] ?? Math.round(p[k] * (d.share ?? 0)));
    const got = { personnel: take('personnel'), tanks: take('tanks'), guns: take('guns') };
    for (const k of ['personnel', 'tanks', 'guns'] as const) {
      const was = p[k];
      p[k] -= got[k]; f[k] = got[k]; f.initial[k] = got[k];
      if (was > 0) p.initial[k] = Math.round(p.initial[k] * (p[k] / was));
    }
    Object.assign(f, { position: [...p.position] as LngLat, ammo: p.ammo, fuel: p.fuel, fatigue: p.fatigue, posture: p.posture, dugInHours: 0 });
    journal.push({ kind: 'detached', time: now, formation: f.id, from: p.id, ...got });
  }

  // 0а. изменения по датам (пополнения, переподчинение) — после выделения: выделенному при вводе прибавляется к его доле
  const changesDone = applyChanges(ctx.scenario, fs, byId, now, prev.changesDone, journal);

  // 1. приказы, дошедшие до исполнителя к концу хода
  const pending: Order[] = [];
  // когда приказ дошёл до исполнителя в этом ходе (rules.orderPartialTurn)
  const reached = new Map<string, number>();
  for (const o of [...prev.pending].sort((a, b) => a.issuedAt.localeCompare(b.issuedAt))) {
    const f = byId.get(o.formation);
    if (!f || f.destroyed) continue;
    if (!onMap(f, end)) { pending.push(o); continue; } // ещё не прибыло — приказ ждёт
    const delay = profileOf(ctx, f.side).orderDelayHours[f.echelon] ?? 0;
    if (t2ms(addHours(o.issuedAt, delay)) <= t2ms(end)) {
      f.order = o;
      f.posture = POSTURE[o.task];
      f.route = null;
      delete f.followsParent;
      reached.set(f.id, t2ms(addHours(o.issuedAt, delay)));
      journal.push({ kind: 'order', time: now, formation: f.id, order: o, effective: true });
    } else pending.push(o);
  }

  // переправы, наведённые сапёрами в этом прогоне, — в расчёт путей и подвоза
  T.setDynamicCrossings(prev.crossings ?? []);
  const crossings = [...(prev.crossings ?? [])];

  // территория (если ведётся): с прошлого хода или исходная — по ближайшим войскам и тылам сторон
  const sides = ctx.scenario.sides.map((x) => x.id);
  const sideIdx = (side: string) => sides.indexOf(side);
  const terr: Int8Array | null = !R.territory ? null : prev.territory ? Int8Array.from(prev.territory)
    : initialTerritory(T, [
      ...active().map((f) => ({ side: sideIdx(f.side), at: f.position })),
      ...sides.flatMap((sd) => supplySources(ctx, sd, now, prev.logistics).map((at) => ({ side: sideIdx(sd), at }))),
    ], sides);
  // по территории противника — медленнее (заслоны, разрушения, зачистка)
  const terrCost = (f: Formation, mob: string) => {
    const cap = R.territory?.enemyKmPerDay[mob as keyof NonNullable<Rules['territory']>['enemyKmPerDay']];
    if (!terr || !cap) return () => 0;
    const k = sideIdx(f.side), h = (T.cellKm * 24) / cap;
    return (i: number) => (terr[i] >= 0 && terr[i] !== k ? h : 0);
  };
  // контроль территории и подвоз — по положению на начало хода
  const sup = ctx.scenario.supply || prev.logistics ? supplyState(ctx, active(), now, terr, prev.logistics) : null;
  // подвоз к формированию — к тыловой части его полосы (hoursNear)
  const supplyHours = (f: Formation, at: LngLat = f.position) => {
    const fld = sup?.fields.get(f.side);
    return fld ? hoursNear(ctx, fld, at) : 0;
  };
  const range = (f: Formation) => profileOf(ctx, f.side).supply?.rangeHours ?? Infinity;
  // подвоз проверяется там, где формирование было на начало хода: поле подвоза построено на этот момент
  // … строки 192–487

/** Остановиться, не доходя до противника ближе расстояния соприкосновения. */
function stopShortOfEnemy(f: Formation, to: LngLat, all: Formation[], T: Theatre, radius: (e: Formation) => number, inner = 0): LngLat | null {
  const a = T.proj.toXY(f.position), b = T.proj.toXY(to);
  const enemies = all.filter((e) => e.side !== f.side).map((e) => ({ p: T.proj.toXY(e.position), r: radius(e) }));
  // уже в зоне противника — можно подходить до дистанции боя (inner), но не глубже: без боя сквозь противника не пройти
  const hit = (q: XY) => enemies.some((e) => { const d0 = dist(a, e.p), d = dist(q, e.p); return d < e.r && (d0 >= e.r * 0.999 || (d < inner && d < d0 - 0.05)); });
  if (!hit(b)) return null;
  let lo = 0, hi = 1;
  for (let i = 0; i < 20; i++) {
    const m = (lo + hi) / 2;
    const p: XY = [a[0] + (b[0] - a[0]) * m, a[1] + (b[1] - a[1]) * m];
    if (hit(p)) hi = m; else lo = m;
  }
  return T.proj.toLL([a[0] + (b[0] - a[0]) * lo, a[1] + (b[1] - a[1]) * lo]);
}

/** Время подвоза до формирований стороны на начало хода, часов (Infinity — не доходит), и предел стороны. */
export function supplyHoursOf(ctx: SimContext, state: SimState, side: string): { hours: Map<string, number>; rangeHours: number } {
  const units = state.formations.filter((f) => onMap(f, state.time));
  const terr = state.territory ? Int8Array.from(state.territory) : null;
  const sup = supplyState(ctx, units, state.time, terr, state.logistics);
  const fld = sup.fields.get(side);
  const hours = new Map(units.filter((f) => f.side === side).map((f) => [f.id, fld ? hoursNear(ctx, fld, f.position) : 0]));
  return { hours, rangeHours: profileOf(ctx, side).supply?.rangeHours ?? Infinity };
}

/**
 * Источники снабжения стороны — точки (районы — их центры). Тыл под управлением штаба (logistics) —
 * его базы: перенесённая база действует с activeFrom и только на своей территории.
 */
export function supplySources(ctx: SimContext, side: string, time: string, logistics?: SimState['logistics'], territory?: ArrayLike<number> | null): LngLat[] {
  const lg = logistics?.[side];
  if (lg) {
    const k = ctx.scenario.sides.findIndex((x) => x.id === side);
    return lg.bases.filter((b) => (!b.activeFrom || b.activeFrom <= time) && (!b.moved || !territory || territory[ctx.theatre.indexOf(b.at)] === k)).map((b) => b.at);
  }
  const sp = ctx.scenario.supply?.[side];
  const all = [...(sp?.sources ?? []), ...(sp?.phases ?? []).filter((p) => p.from <= time && (!p.until || time < p.until)).flatMap((p) => p.sources)];
  return all.map((x) => (Array.isArray(x) ? x : ctx.theatre.area(x)?.center ?? null)).filter((x): x is LngLat => !!x);
}

/** Контроль территории и время подвоза по сторонам на начало хода. */
export function supplyState(ctx: SimContext, units: Formation[], time: string, territory?: Int8Array | null, logistics?: SimState['logistics']) {
  const sides = ctx.scenario.sides.map((x) => x.id);
  // территория — по положению войск больше, чем по их силе (показатель 0,1): фронтовые части стоят на своей земле
  const control = controlMap(ctx.theatre, units, sides, (f) => power(f, profileOf(ctx, f.side), ctx.rules).total, 10, 0.1);
  const fields = new Map<string, Float64Array>();
  for (const side of sides) {
    const src = supplySources(ctx, side, time, logistics, territory);
    // зона влияния: наступающие и на марше — радиус соприкосновения; в обороне (кольцо окружения) — половина полосы
    const zoc = (f: Formation) => f.posture === 'attack' || f.posture === 'march' ? ctx.rules.contactKm
      : Math.max(ctx.rules.contactKm, (profileOf(ctx, f.side).unitTypes[f.type]?.frontageKm ?? 0) / 2);
    const terr = territory ? { owner: territory, side: sides.indexOf(side), ownZoneKm: ctx.rules.contactKm / 2, holdKm: ctx.rules.territory?.supplyHoldKm ?? ctx.rules.contactKm } : undefined;
    if (src.length) fields.set(side, supplyField(ctx.theatre, side, src, units, profileOf(ctx, side), ctx.rules, time, zoc, terr).hours);
  }
  return { control, fields };
}

/** Точка цели: координаты, центр района или текущее положение формирования (если оно на карте). */
export function targetPoint(ctx: SimContext, t: Target | undefined, units?: Map<string, Formation>): LngLat | null {
  if (!t) return null;
  if (Array.isArray(t)) return t;
  if (typeof t === 'object') { const u = units?.get(t.formation); return u && !u.destroyed ? u.position : null; }
  return ctx.theatre.area(t)?.center ?? null;
}

/**
 * Разброс выбора пути: время клетки при выборе пути умножается на плавный шум (районы в несколько км).
 * Шум свой у формирования и приказа и постоянный на прогон: путь не дёргается от хода к ходу, а разный seed даёт
 * разные пути — дорогой, лесом, полем напрямик.
 */
function varietyCost(ctx: SimContext, seed: number, f: Formation, mob: Mobility): ((i: number) => number) | null {
  void mob;
  const v = ctx.rules.routeVariety ?? 0;
  if (v <= 0) return null;
  const T = ctx.theatre;
  const bs = Math.max(2, Math.round(Math.min(4, T.cellKm * 8) / T.cellKm)); // район шума: 2–4 км
  const key = hashStr(`${f.id}|${f.order?.id ?? ''}`) ^ seed;
  const at = (x: number, y: number) => hash3(x, y, key);
  // множитель «как кажется выгодным» 1…1+2v: только выбор пути, время движения — по местности
  return (i: number) => {
    const c = i % T.cols, r = Math.floor(i / T.cols), gx = c / bs, gy = r / bs, x0 = Math.floor(gx), y0 = Math.floor(gy), tx = gx - x0, ty = gy - y0;
    const n = (at(x0, y0) * (1 - tx) + at(x0 + 1, y0) * tx) * (1 - ty) + (at(x0, y0 + 1) * (1 - tx) + at(x0 + 1, y0 + 1) * tx) * ty;
    return 1 + 2 * v * n;
  };
}

function charsRle(a: string[]): string {
  let s = '';
  for (let i = 0; i < a.length;) { let j = i; while (j < a.length && a[j] === a[i]) j++; s += (j - i > 1 ? j - i : '') + a[i]; i = j; }
  return s;
}

/** Растр, обрезанный по области: целые клетки, границы — по краям клеток. */
export function cropGrid(g: TerrainGrid, b: BBox, heights = false): TerrainGrid | null {
  const [w, s, e, n] = g.bbox, dx = (e - w) / g.cols, dy = (n - s) / g.rows;
  const c0 = Math.max(0, Math.floor((b[0] - w) / dx)), c1 = Math.min(g.cols, Math.ceil((b[2] - w) / dx));
  const r0 = Math.max(0, Math.floor((n - b[3]) / dy)), r1 = Math.min(g.rows, Math.ceil((n - b[1]) / dy));
  if (c1 <= c0 || r1 <= r0) return null;
  // растры бывают с разными кодами (местность — o/f/m/u/h/w, дороги — n/r/h): режем по буквам, не по классам
  const all = heights ? heightTokens(g.rle, g.cols * g.rows) : rleChars(g.rle, g.cols * g.rows), cols = c1 - c0, rows = r1 - r0;
  const out: string[] = [];
  for (let r = 0; r < rows; r++) for (let c = c0; c < c1; c++) out.push(all[(r0 + r) * g.cols + c]);
  const r6 = (x: number) => +x.toFixed(6);
  return { bbox: [r6(w + c0 * dx), r6(n - r1 * dy), r6(w + c1 * dx), r6(n - r0 * dy)], cols, rows, rle: heights ? tokensRle(out) : charsRle(out) };
}

/** Театр, обрезанный по области: объекты, задевающие её, и растры. */
export function cropTheatre(T: TheatreData, b: BBox, id = `${T.id}-crop`): TheatreData {
  const terrainGrid = T.terrainGrid ? cropGrid(T.terrainGrid, b) ?? undefined : undefined;
  const roadGrid = T.roadGrid ? cropGrid(T.roadGrid, b) ?? undefined : undefined;
  // сетка высот — та же обрезка по клеткам, значения через запятую (base и stepM — прежние)
  const hg = T.heightGrid ? cropGrid(T.heightGrid, b, true) : null;
  const heightGrid = T.heightGrid && hg ? { ...T.heightGrid, bbox: hg.bbox, cols: hg.cols, rows: hg.rows, rle: hg.rle } : undefined;
  return {
    ...T, id, name: `${T.name} — фрагмент`, bbox: b,
    ...(terrainGrid ? { terrainGrid } : {}), ...(roadGrid ? { roadGrid } : {}), ...(heightGrid ? { heightGrid } : {}),
    terrain: T.terrain.filter((x) => touches(b, x.ring)),
    roads: T.roads.filter((r) => touches(b, r.line)),
    rivers: T.rivers.filter((r) => touches(b, r.line)),
    bridges: T.bridges.filter((x) => inBox(b, x.at)),
    areas: T.areas.filter((a) => touches(b, a.ring)),
    lines: (T.lines ?? []).filter((l) => touches(b, l.line)),
  };
}

/**
 * Контуры местности по растру: клетки одного класса сливаются в многоугольники по краям клеток (лес, болото,
 * застройка, высоты, вода; открытая местность — фон). Так у растровых театров, где векторных контуров нет, есть
 * слой «Местность: контуры» — на карте, в редакторе и в GeoJSON.
 */
export function gridContours(g: TerrainGrid): TerrainShape[] {
  const k = decodeGrid(g), { cols, rows } = g;
  const [w, , , n] = g.bbox, dx = (g.bbox[2] - w) / cols, dy = (n - g.bbox[1]) / rows;
  const out: TerrainShape[] = [];
  for (const cls of ['hills', 'forest', 'marsh', 'urban', 'water'] as TerrainClass[]) {
    const ci = TERRAIN_CLASSES.indexOf(cls);
    const inM = (c: number, r: number) => c >= 0 && r >= 0 && c < cols && r < rows && k[r * cols + c] === ci;
    // рёбра границы в одном обходе (по часовой стрелке на карте): ключ — начальная вершина
    const W = cols + 1, next = new Map<number, number[]>();
    const add = (c0: number, r0: number, c1: number, r1: number) => { const a = r0 * W + c0; const l = next.get(a); if (l) l.push(r1 * W + c1); else next.set(a, [r1 * W + c1]); };
    for (let r = 0; r < rows; r++) for (let c = 0; c < cols; c++) {
      if (k[r * cols + c] !== ci) continue;
      if (!inM(c, r - 1)) add(c, r, c + 1, r);
      if (!inM(c + 1, r)) add(c + 1, r, c + 1, r + 1);
      if (!inM(c, r + 1)) add(c + 1, r + 1, c, r + 1);
      if (!inM(c - 1, r)) add(c, r + 1, c, r);
    }
    const outer: [number, number][][] = [], holes: [number, number][][] = [];
    for (const start of [...next.keys()]) {
      while (next.get(start)?.length) {
        const loop: [number, number][] = [];
        let v = start;
        do {
          const l = next.get(v)!;
          const u = l.pop()!;
          if (!l.length) next.delete(v);
          loop.push([v % W, Math.floor(v / W)]);
          v = u;
        } while (v !== start && next.has(v));
        // лишние вершины на прямых участках
        const pts = loop.filter((p, i) => { const a = loop[(i - 1 + loop.length) % loop.length], b = loop[(i + 1) % loop.length]; return (p[0] - a[0]) * (b[1] - p[1]) !== (p[1] - a[1]) * (b[0] - p[0]); });
        if (pts.length < 3) continue;
        let area = 0;
        for (let i = 0; i < pts.length; i++) { const a = pts[i], b = pts[(i + 1) % pts.length]; area += a[0] * b[1] - b[0] * a[1]; }
        (area > 0 ? outer : holes).push(pts);
      }
    }
    const toLL = (l: [number, number][]): LngLat[] => l.map(([c, r]) => [+(w + c * dx).toFixed(5), +(n - r * dy).toFixed(5)]);
    // дыра — к внешнему контуру, внутри которого её вершина (луч по строке сетки)
    const inside = (pt: [number, number], poly: [number, number][]) => {
      let o = false;
      for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
        const [xi, yi] = poly[i], [xj, yj] = poly[j];
        if ((yi > pt[1]) !== (yj > pt[1]) && pt[0] < ((xj - xi) * (pt[1] - yi)) / (yj - yi) + xi) o = !o;
      }
      return o;
    };
    const shapes = outer.map((o) => ({ o, h: [] as [number, number][][] }));
    for (const h of holes) {
      const p: [number, number] = [h[0][0] + 0.01, h[0][1] + 0.013];
      const sh = shapes.find((x) => inside(p, x.o));
      if (sh) sh.h.push(h);
    }
    for (const x of shapes) out.push({ class: cls, ring: toLL(x.o), holes: x.h.map(toLL) });
  }
  return out;
}

/** Высоты «значение*повторы» через запятую → список значений по клеткам и обратно. */
function heightTokens(rle: string, n: number): string[] {
  const out: string[] = [];
  for (const t of rle.split(',')) { const [v, k] = t.split('*'); for (let i = 0; i < (k ? Number(k) : 1); i++) out.push(v); }
  if (out.length !== n) throw new Error(`высоты: ${out.length} клеток вместо ${n}`);
  return out;
}

export function layerCounts(T: TheatreData, b?: BBox): Record<TheatreLayerId, number> {
  const bb = b ?? T.bbox;
  return {
    terrain: T.terrainGrid ? 1 : 0,
    height: T.heightGrid ? 1 : 0,
    terrainShapes: terrainShapes(T).filter((x) => touches(bb, x.ring)).length,
    roads: T.roads.filter((r) => r.kind !== 'rail' && touches(bb, r.line)).length,
    rail: T.roads.filter((r) => r.kind === 'rail' && touches(bb, r.line)).length,
    rivers: T.rivers.filter((r) => touches(bb, r.line)).length,
    bridges: T.bridges.filter((x) => inBox(bb, x.at)).length,
    areas: T.areas.filter((a) => touches(bb, a.ring)).length,
    lines: (T.lines ?? []).filter((l) => touches(bb, l.line)).length,
  };
}

/** Слой театра в GeoJSON (объекты, задевающие область). */
export function layerGeoJSON(T: TheatreData, layer: TheatreLayerId, b?: BBox): GJ {
  const bb = b ?? T.bbox;
  switch (layer) {
    case 'terrainShapes': return fc(terrainShapes(T).filter((x) => touches(bb, x.ring)).map((x) => ({ type: 'Feature', properties: { class: x.class }, geometry: { type: 'Polygon', coordinates: [ring(x.ring), ...x.holes.map(ring)] } })));
    case 'roads': case 'rail': return fc(T.roads.filter((r) => (layer === 'rail') === (r.kind === 'rail') && touches(bb, r.line)).map((r) => ({ type: 'Feature', properties: { kind: r.kind, name: r.name ?? null }, geometry: { type: 'LineString', coordinates: r.line } })));
    case 'rivers': return fc(T.rivers.filter((r) => touches(bb, r.line)).map((r) => ({ type: 'Feature', properties: { name: r.name, major: r.major }, geometry: { type: 'LineString', coordinates: r.line } })));
    case 'bridges': return fc(T.bridges.filter((x) => inBox(bb, x.at)).map((x) => ({ type: 'Feature', properties: { id: x.id, name: x.name ?? null, kind: x.kind ?? null, openFrom: x.openFrom ?? null, destroyedAt: x.destroyedAt ?? null, side: x.side ?? null }, geometry: { type: 'Point', coordinates: x.at } })));
    case 'areas': return fc(T.areas.filter((a) => touches(bb, a.ring)).map((a) => ({ type: 'Feature', properties: { id: a.id, name: a.name, title: areaTitle(a.name) }, geometry: { type: 'Polygon', coordinates: [ring(a.ring)] } })));
    case 'lines': return fc((T.lines ?? []).filter((l) => touches(bb, l.line)).map((l) => ({ type: 'Feature', properties: { id: l.id, name: l.name, fortification: l.fortification ?? null, side: l.side ?? null, depthKm: l.depthKm ?? null }, geometry: { type: 'LineString', coordinates: l.line } })));
    default: return fc([]);
  }
}

/**
 * Рецепт сборщика театра по области (как data/theatres/src/*.recipe.json) — готовый к сборке: местность и рельеф
 * по правилам встроенных театров, большие реки — по длине в охвате, районы — населённые пункты OpenStreetMap.
 * Исторический слой (рубежи, разрушенные мосты, переправы, автобаны 1945 г.) дописывается вручную.
 */
export function recipeFor(o: { id: string; name: string; bbox: BBox; cellKm: number; places?: ('city' | 'town' | 'village')[] }): Record<string, unknown> {
  const lat = (o.bbox[1] + o.bbox[3]) / 2;
  const dLat = +(o.cellKm / 111.32).toFixed(5), dLng = +(o.cellKm / (111.32 * Math.cos((lat * Math.PI) / 180))).toFixed(5);
  const spanKm = Math.max((o.bbox[2] - o.bbox[0]) * 111.32 * Math.cos((lat * Math.PI) / 180), (o.bbox[3] - o.bbox[1]) * 111.32);
  return {
    id: o.id, name: o.name, bbox: o.bbox.map((x) => +x.toFixed(4)), cellKm: o.cellKm, defaultTerrain: 'open',
    grid: { dLng, dLat },
    landcover: { source: 'esa-worldcover-2021', rules: { water: 0.5, urban: 0.35, marsh: 0.3, forest: 0.5 } },
    relief: { source: 'copernicus-dem-90', smoothPx: 5, hillsReliefM: 35, hillsSlope: 0.025 },
    rivers: { major: [], minor: [], autoMajorKm: Math.max(5, Math.round(spanKm / 6)) },
    roads: { highwayRefs: [], roadHighways: o.cellKm <= 0.5 ? ['trunk', 'primary', 'secondary'] : ['trunk', 'primary'], simplifyDeg: +(o.cellKm * 0.003).toFixed(4) },
    rail: { simplifyDeg: +(o.cellKm * 0.003).toFixed(4) },
    bridges: { dedupeKm: Math.max(0.2, o.cellKm / 2), rules: [], crossings: [] },
    areas: { explicit: [], fromOsm: { places: o.places ?? (o.cellKm <= 0.5 ? ['city', 'town', 'village', 'suburb'] : ['city', 'town']) } },
    lines: [],
    osmParts: spanKm > 250 ? 3 : spanKm > 120 ? 2 : 1,
    sources: [
      'Земной покров: ESA WorldCover 10 m 2021 v200 (CC BY 4.0), © ESA WorldCover project / Copernicus Sentinel data',
      'Рельеф: Copernicus DEM GLO-90 (© DLR e.V. 2010–2014 and © Airbus Defence and Space GmbH 2014–2018, Copernicus programme)',
      'Реки, дороги, железные дороги, населённые пункты: © участники OpenStreetMap (ODbL), выборка через Overpass API',
    ],
    caveats: ['Земной покров и дорожная сеть современные; исторический слой (рубежи, переправы, разрушенные мосты, шоссе того времени) не задан — дополните рецепт.'],
  };
}

function rleChars(rle: string, n: number): string[] {
  const out: string[] = [];
  let k = 0;
  for (const ch of rle) {
    if (ch >= '0' && ch <= '9') { k = k * 10 + (ch.charCodeAt(0) - 48); continue; }
    for (let i = 0; i < (k || 1); i++) out.push(ch);
    k = 0;
  }
  if (out.length !== n) throw new Error(`растр: ${out.length} клеток вместо ${n}`);
  return out;
}

/** Контуры местности театра: векторные (старые театры) или по растру. */
export function terrainShapes(T: TheatreData): TerrainShape[] {
  let v = shapesCache.get(T);
  if (!v) {
    v = T.terrain.length ? T.terrain.map((x) => ({ class: x.class, ring: x.ring, holes: [] })) : T.terrainGrid ? gridContours(T.terrainGrid) : [];
    shapesCache.set(T, v);
  }
  return v;
}

/** Театр — документ карты: слои театра (растр местности добавляет просмотр — он рисуется в браузере). */
export function theatreToDocument(T: TheatreData): MapDocument {
  const [w, s, e, n] = T.bbox;
  const span = Math.max(e - w, (n - s) * 1.6, 0.05);
  const doc = emptyDocument([(w + e) / 2, (s + n) / 2], +(Math.log2((360 * 900) / (256 * span)) - 0.4).toFixed(1));
  doc.name = `Театр: ${T.name}`;
  const mk = (id: TheatreLayerId, name: string, visible = true, opacity = 1): Layer => ({ id: `th-${id}`, name, role: 'base', visible, locked: true, opacity, source: { system: 'theatre', ref: T.id, readOnly: true } });
  doc.layers = [mk('terrainShapes', 'Местность: контуры', false, 0.6), mk('areas', 'Районы и пункты', true, 0.7), mk('rail', 'Железные дороги'), mk('roads', 'Дороги и шоссе'), mk('rivers', 'Реки и каналы'), mk('lines', 'Рубежи'), mk('bridges', 'Мосты и переправы')];
  const F: Feature[] = [];
  for (const x of terrainShapes(T)) {
    const p = TERR_PRESET[x.class];
    const f = createFeature('area', p ?? 'std.swamp', { points: x.ring, layerId: 'th-terrainShapes' }, 1);
    // застройка, высоты, вода — заливкой цвета растра местности (лес и болото — своими знаками)
    const fill = TERR_FILL[x.class];
    if (!p && fill) f.style = { ...f.style, smooth: false, fill: fill[0], fillOpacity: 0.75, hatch: null, cross: null, edge: [{ color: fill[1], width: 0.6, opacity: 0.9, offset: 0 }] } as typeof f.style;
    f.name = `Местность: ${({ forest: 'лес', marsh: 'болото', urban: 'город', hills: 'высоты', water: 'вода', open: 'открытая' } as Record<string, string>)[x.class] ?? x.class}`;
    F.push(f);
  }
  for (const a of T.areas) {
    const f = createFeature('line', 'std.border', { points: [...a.ring, a.ring[0]], layerId: 'th-areas' }, 0.5, 'neutral');
    f.name = `${areaTitle(a.name)} · ${a.id}`;
    F.push(f);
  }
  for (const r of T.roads) {
    const f = createFeature('line', r.kind === 'rail' ? 'inf.rail' : r.kind === 'highway' ? 'std.road' : 'std.dirtRoad', { points: r.line, layerId: r.kind === 'rail' ? 'th-rail' : 'th-roads' }, r.kind === 'highway' ? 1 : 0.7);
    f.name = r.name ? `${r.kind === 'rail' ? 'Ж/д' : r.kind === 'highway' ? 'Шоссе' : 'Дорога'}: ${r.name}` : r.kind === 'rail' ? 'Железная дорога' : r.kind === 'highway' ? 'Шоссе' : 'Дорога';
    F.push(f);
  }
  for (const r of T.rivers) {
    const f = createFeature('line', 'inf.river', { points: r.line, layerId: 'th-rivers' }, r.major ? 1.3 : 0.7);
    f.name = `${r.name}${r.major ? ' (большая река)' : ''}`;
    F.push(f);
  }
  for (const l of T.lines ?? []) {
    const f = createFeature('line', 'atlas.defense', { points: l.line, layerId: 'th-lines' }, 1.2, l.side ? 'enemy' : 'neutral');
    f.name = `${l.name}${l.fortification ? ` · укреплённость ${l.fortification}` : ''}`;
    F.push(f);
  }
  for (const b of T.bridges) {
    const f = createFeature('symbol', b.destroyedAt ? 'std.bridgeDestroyed' : b.openFrom ? 'std.pontoon' : 'std.bridge', { at: b.at, layerId: 'th-bridges' }, 0.6, 'neutral') as SymbolFeature;
    f.name = `${b.name ?? 'Мост'}${b.openFrom ? ` · наведён ${b.openFrom.slice(0, 10)}` : ''}${b.destroyedAt ? ` · разрушен ${b.destroyedAt.slice(0, 10)}` : ''}`;
    F.push(f);
  }
  doc.features = F;
  return doc;
}

function tokensRle(a: string[]): string {
  const out: string[] = [];
  for (let i = 0; i < a.length;) { let j = i; while (j < a.length && a[j] === a[i]) j++; out.push(j - i > 1 ? `${a[i]}*${j - i}` : a[i]); i = j; }
  return out.join(',');
}

/** Двоичная куча по приоритету (для A*). */
export class MinHeap {
  private ids: number[] = [];
  private pr: number[] = [];
  get size() { return this.ids.length; }
  push(id: number, p: number) {
    this.ids.push(id); this.pr.push(p);
    let i = this.ids.length - 1;
    while (i > 0) {
      const j = (i - 1) >> 1;
      if (this.pr[j] <= this.pr[i]) break;
      [this.ids[i], this.ids[j]] = [this.ids[j], this.ids[i]];
      [this.pr[i], this.pr[j]] = [this.pr[j], this.pr[i]];
      i = j;
    }
  }
  pop(): number {
    const top = this.ids[0];
    const lastId = this.ids.pop()!, lastP = this.pr.pop()!;
    if (this.ids.length) {
      this.ids[0] = lastId; this.pr[0] = lastP;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1, r = l + 1;
        let m = i;
        if (l < this.ids.length && this.pr[l] < this.pr[m]) m = l;
        if (r < this.ids.length && this.pr[r] < this.pr[m]) m = r;
        if (m === i) break;
        [this.ids[i], this.ids[m]] = [this.ids[m], this.ids[i]];
        [this.pr[i], this.pr[m]] = [this.pr[m], this.pr[i]];
        i = m;
      }
    }
    return top;
  }
}

export class Theatre {
  readonly proj: LocalProjection;
  readonly cols: number;
  readonly rows: number;
  readonly cellKm: number;
  private readonly x0: number;
  private readonly y0: number;
