/** Убрать промежуточные точки на прямых участках. */
/** Начало пути длиной km (по ломаной). */
export function cutAt(t: Theatre, path: LngLat[], km: number): { trail: LngLat[]; km: number } {
  const out: LngLat[] = [path[0]];
  let left = km;
  for (let i = 1; i < path.length; i++) {
    const a = t.proj.toXY(path[i - 1]), b = t.proj.toXY(path[i]);
    const d = dist(a, b);
    if (d >= left) {
      const k = d > 0 ? left / d : 0;
      out.push(t.proj.toLL([a[0] + (b[0] - a[0]) * k, a[1] + (b[1] - a[1]) * k]));
      return { trail: out, km };
    }
    left -= d;
    out.push(path[i]);
  }
  return { trail: out, km: km - left };
}

/** Раскрыть RLE с произвольными однобуквенными кодами. */
export function decodeCodes(rle: string, n: number): string[] {
  const out: string[] = new Array(n);
  let i = 0, k = 0;
  for (const ch of rle) {
    if (ch >= '0' && ch <= '9') { k = k * 10 + (ch.charCodeAt(0) - 48); continue; }
    out.fill(ch, i, i + (k || 1));
    i += k || 1;
    k = 0;
  }
  if (i !== n) throw new Error(`растр: ${i} клеток вместо ${n}`);
  return out;
}

/** Раскрыть RLE растра в индексы TERRAIN_CLASSES. */
export function decodeGrid(g: TerrainGrid): Uint8Array {
  const out = new Uint8Array(g.cols * g.rows);
  let i = 0, n = 0;
  for (const ch of g.rle) {
    if (ch >= '0' && ch <= '9') { n = n * 10 + (ch.charCodeAt(0) - 48); continue; }
    const cls = TERRAIN_CODES[ch];
    if (!cls) throw new Error(`terrainGrid: неизвестный код «${ch}»`);
    const k = TERRAIN_CLASSES.indexOf(cls);
    out.fill(k, i, i + (n || 1));
    i += n || 1;
    n = 0;
  }
  if (i !== out.length) throw new Error(`terrainGrid: ${i} клеток вместо ${out.length}`);
  return out;
}

/** Сетка высот: «значение» или «значение*повторы» через запятую → метры. */
export function decodeHeights(g: NonNullable<TheatreData['heightGrid']>): Float32Array {
  const out = new Float32Array(g.cols * g.rows);
  let i = 0;
  for (const tok of g.rle.split(',')) {
    const [v, n] = tok.split('*');
    const h = g.base + Number(v) * g.stepM;
    out.fill(h, i, i + (n ? Number(n) : 1));
    i += n ? Number(n) : 1;
  }
  if (i !== out.length) throw new Error(`heightGrid: ${i} клеток вместо ${out.length}`);
  return out;
}

/** Сжать индексы TERRAIN_CLASSES в RLE (для сборщиков театров и тестов). */
export function encodeGrid(cells: ArrayLike<number>): string {
  const code = Object.fromEntries(Object.entries(TERRAIN_CODES).map(([k, v]) => [TERRAIN_CLASSES.indexOf(v), k]));
  let s = '';
  for (let i = 0; i < cells.length;) {
    let j = i;
    while (j < cells.length && cells[j] === cells[i]) j++;
    s += (j - i > 1 ? j - i : '') + code[cells[i]];
    i = j;
  }
  return s;
}

function pathKm(t: Theatre, path: LngLat[]): number {
  let s = 0;
  for (let i = 1; i < path.length; i++) s += dist(t.proj.toXY(path[i - 1]), t.proj.toXY(path[i]));
  return s;
}

function simplify(pts: LngLat[]): LngLat[] {
  if (pts.length < 3) return pts;
  const out = [pts[0]];
  for (let i = 1; i < pts.length - 1; i++) {
    const a = out[out.length - 1], b = pts[i], c = pts[i + 1];
    const cross = (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0]);
    if (Math.abs(cross) > 1e-12) out.push(b);
  }
  out.push(pts[pts.length - 1]);
  return out;
}

/** Путь до точки, ближайшей к pos (движение остановлено раньше — перед противником). */
export function trailTo(t: Theatre, trail: LngLat[], pos: LngLat): LngLat[] {
  const p = t.proj.toXY(pos);
  let best = 0, bd = Infinity;
  for (let i = 1; i < trail.length; i++) {
    const a = t.proj.toXY(trail[i - 1]), b = t.proj.toXY(trail[i]);
    const dx = b[0] - a[0], dy = b[1] - a[1], L = dx * dx + dy * dy || 1;
    const k = Math.max(0, Math.min(1, ((p[0] - a[0]) * dx + (p[1] - a[1]) * dy) / L));
    const d = Math.hypot(a[0] + dx * k - p[0], a[1] + dy * k - p[1]);
    if (d < bd) { bd = d; best = i; }
  }
  return [...trail.slice(0, best), pos];
}

